import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react'
import { createRoot } from 'react-dom/client'
import {
  ArrowUpRight, Bell, CalendarDays, Check, ChevronLeft, ChevronRight, Circle, CircleCheck, CircleHelp, ClipboardList, Clock3, Flame, Grid2X2, LogOut,
  Brain, Factory, Globe2, Home, Inbox, Layers3, Mail, Menu, Moon, MoreHorizontal, Network, Package, Paperclip, Plus, Radar, RefreshCw, Search, Settings, Sparkles, Star, Sun, Upload, Users, X, type LucideIcon
} from 'lucide-react'
import { customers as seedCustomers, followups as seedFollowups, products as seedProducts, projects as seedProjects, quotes as seedQuotes } from './data'
import { api } from './api'
import type { Customer, CustomerLead, CustomerStage, DailyLog, EmailSync, Followup, ImportBatch, ImportPreview, LeadDiscoveryRun, LeadSearchTask, MailboxAccount, MailEmail, Product, ProductCustomerRelation, ProductProfileStatus, Project, Quote, SalesOrder, Supplier, SupplierContact, SupplierDocument, SupplierFollowup, SupplierInsight, SupplierProduct, SupplierProjectLink, SupplierRfq, Task, TimelineEvent, WorkspaceMember } from './types'
import './styles.css'
import './account-menu.css'

type View = 'dashboard' | 'crm' | 'leads' | 'suppliers' | 'mail' | 'products' | 'relationships' | 'quotes' | 'projects' | 'tasks' | 'calendar' | 'imports'
type CrmFilter = 'all' | 'incomplete' | 'overdue'
const nav: [string, string, LucideIcon][] = [
  ['dashboard', '总览', Grid2X2], ['crm', '外贸 CRM', Users], ['leads', '客户线索发现', Radar], ['suppliers', '供应商中心', Factory], ['mail', '邮件中心', Mail], ['products', '产品中心', Package],
  ['relationships', '产品关系', Network], ['quotes', '报价管理', ClipboardList], ['assets', 'AI 资产', Sparkles], ['imports', 'AI 导入暂存箱', Inbox], ['tasks', '每日计划', ClipboardList], ['calendar', '工作日历', CalendarDays], ['projects', '项目推进', Layers3],
]
const stageLabels: Record<CustomerStage, string> = {
  New: '新线索', Inquiry: '询盘', Quoted: '已报价', Sample: '寄样中', Negotiation: '谈判中', Won: '已成交', Lost: '已流失',
  'New Inquiry': 'New Inquiry', 'Technical Discussion': 'Technical Discussion', Quotation: 'Quotation',
  'Sample Payment': 'Sample Payment', 'Sample Payment Pending': 'Sample Payment Pending',
  'Technical Testing': 'Technical Testing', 'Technical Confirmation': 'Technical Confirmation', 'Maintain Relationship': 'Maintain Relationship',
}

function currentAccount() {
  let email = sessionStorage.getItem('zhiwu-account-email') || ''
  if (!email) {
    try {
      const token = sessionStorage.getItem('zhiwu-access-token') || ''
      const payload = token.split('.')[1]
      email = payload ? JSON.parse(atob(payload.replace(/-/g, '+').replace(/_/g, '/')))?.email || '' : ''
    } catch { email = '' }
  }
  email = email.toLowerCase()
  const isPeter = email === 'peter@neonliontech.com'
  return {
    email,
    initial: isPeter ? 'P' : 'Z',
    name: isPeter ? 'Peter' : 'Zhiwu',
    role: isPeter ? 'Member' : 'Founder',
  }
}

function App() {
  const [authenticated, setAuthenticated] = useState(() => Boolean(sessionStorage.getItem('zhiwu-access-token')))
  const [theme, setTheme] = useState<'dark' | 'light'>(() => localStorage.getItem('zhiwu-theme') === 'light' ? 'light' : 'dark')
  const [view, setView] = useState<View>(() => window.location.hash.startsWith('#mail') ? 'mail' : 'dashboard')
  const [sidebar, setSidebar] = useState(false)
  const [customers, setCustomers] = useState(seedCustomers)
  const [products, setProducts] = useState(seedProducts)
  const [members, setMembers] = useState<WorkspaceMember[]>([])
  const [followupRows, setFollowupRows] = useState(seedFollowups)
  const [projects, setProjects] = useState(seedProjects)
  const [quotes, setQuotes] = useState(seedQuotes)
  const [orders, setOrders] = useState<SalesOrder[]>([])
  const [productCustomerRelations, setProductCustomerRelations] = useState<ProductCustomerRelation[]>([])
  const [emails, setEmails] = useState<MailEmail[]>([])
  const [emailSync, setEmailSync] = useState<EmailSync>({ status: 'Not configured', total_synced: 0, last_sync_time: null })
  const [mailbox, setMailbox] = useState<MailboxAccount>({ label: '当前邮件中心', email_address: null, is_active: false, configured: false })
  const [tasks, setTasks] = useState<Task[]>([])
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([])
  const [suppliers, setSuppliers] = useState<Supplier[]>([])
  const [supplierInsights, setSupplierInsights] = useState<SupplierInsight[]>([])
  const [supplierLinks, setSupplierLinks] = useState<SupplierProjectLink[]>([])
  const [supplierRfqs, setSupplierRfqs] = useState<SupplierRfq[]>([])
  const [leadSearchTasks, setLeadSearchTasks] = useState<LeadSearchTask[]>([])
  const [customerLeads, setCustomerLeads] = useState<CustomerLead[]>([])
  const [leadRuns, setLeadRuns] = useState<LeadDiscoveryRun[]>([])
  const [dailyLog, setDailyLog] = useState<DailyLog | null>(null)
  const [focusDate, setFocusDate] = useState(() => new Date().toISOString().slice(0, 10))
  const [selected, setSelected] = useState<Customer | null>(null)
  const [selectedEmail, setSelectedEmail] = useState<MailEmail | null>(null)
  const [selectedSupplier, setSelectedSupplier] = useState<Supplier | null>(null)
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null)
  const [selectedProject, setSelectedProject] = useState<Project | null>(null)
  const [selectedQuote, setSelectedQuote] = useState<Quote | null>(null)
  const [historyProduct, setHistoryProduct] = useState<Product | null>(null)
  const [modal, setModal] = useState<'customer' | 'customer-edit' | 'product' | 'product-edit' | 'product-history' | 'followup' | 'quote' | 'quote-edit' | 'task' | 'review' | 'password' | null>(null)
  const [supplierModal, setSupplierModal] = useState<'create' | 'link' | 'rfq' | null>(null)
  const [relationProduct, setRelationProduct] = useState<Product | null>(null)
  const [query, setQuery] = useState('')
  const [crmFilter, setCrmFilter] = useState<CrmFilter>('all')
  const [globalQuery, setGlobalQuery] = useState('')
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  useEffect(() => {
    document.documentElement.dataset.theme = theme
    localStorage.setItem('zhiwu-theme', theme)
  }, [theme])
  const [accountMenuOpen, setAccountMenuOpen] = useState(false)
  const account = useMemo(() => currentAccount(), [authenticated])
  const workbench = useMemo(() => {
    const today = new Date().toISOString().slice(0, 10)
    const customerItem = (customer: Customer) => ({ id: customer.id, title: customer.company_name, date: customer.next_followup_date })
    const emailItem = (email: MailEmail) => ({ id: email.id, title: email.subject || email.sender_name || email.sender, date: email.received_at })
    return {
      overdue_followups: customers.filter(customer => customer.next_followup_date && customer.next_followup_date < today).map(customerItem),
      quotation: customers.filter(customer => ['Quotation', 'Quoted'].includes(customer.customer_stage)).map(customerItem),
      sample: customers.filter(customer => ['Sample', 'Sample Payment', 'Sample Payment Pending', 'Technical Testing'].includes(customer.customer_stage)).map(customerItem),
      waiting_reply: emails.filter(email => ['unread', 'linked', 'followup_created'].includes(email.status)).map(emailItem),
      new_leads: emails.filter(email => email.status === 'new_lead' && !email.customer_id).map(emailItem),
      tasks: tasks.filter(task => task.status !== 'Completed').map(task => ({ id: task.id, title: task.title, date: task.task_date, priority: task.priority })),
    }
  }, [customers, emails, tasks])
  const today = new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }).format(new Date(`${focusDate}T12:00:00`))
  const visibleCustomers = useMemo(() => {
    const today = new Date().toISOString().slice(0, 10)
    return customers.filter(customer => {
      const matchesQuery = `${customer.company_name} ${customer.country} ${customer.contact_person} ${customer.product_interest} ${customer.application || ''} ${customer.customer_summary || ''} ${customer.customer_need || ''} ${(customer.customer_tags || []).join(' ')}`.toLowerCase().includes(query.toLowerCase())
      if (!matchesQuery) return false
      if (crmFilter === 'incomplete') return isCustomerIncomplete(customer)
      if (crmFilter === 'overdue') return Boolean(customer.next_followup_date && customer.next_followup_date < today)
      return true
    })
  }, [customers, query, crmFilter])
  const crmActionCount = useMemo(() => {
    const today = new Date().toISOString().slice(0, 10)
    return customers.filter(customer => isCustomerIncomplete(customer) || Boolean(customer.next_followup_date && customer.next_followup_date < today)).length
  }, [customers])
  const alertDate = new Date().toISOString().slice(0, 10)
  const hasNotifications = tasks.some(task => task.task_date === alertDate && task.status !== 'Completed') || emails.some(email => ['unread', 'new_lead'].includes(email.status))
  useEffect(() => {
    if (!authenticated || !sessionStorage.getItem('zhiwu-access-token')) return
    const loadWorkspace = async () => {
      let [customerRows, productRows, loadedFollowups, loadedProjects, loadedQuotes, loadedOrders] = await Promise.all([api.customers(), api.products(), api.followups(), api.projects(), api.quotes(), api.orders().catch(() => [])])
      if (!customerRows.length) {
        await api.seedDemo()
        ;[customerRows, productRows, loadedFollowups, loadedProjects, loadedQuotes, loadedOrders] = await Promise.all([api.customers(), api.products(), api.followups(), api.projects(), api.quotes(), api.orders().catch(() => [])])
      }
      setCustomers(customerRows.length ? customerRows : seedCustomers); setProducts(productRows.length ? productRows : seedProducts)
      setFollowupRows(loadedFollowups.length ? loadedFollowups : seedFollowups); setProjects(loadedProjects.length ? loadedProjects : seedProjects); setQuotes(loadedQuotes.length ? loadedQuotes : seedQuotes); setOrders(loadedOrders)
      try {
        const [mailRows, syncRow, mailboxRow] = await Promise.all([api.emails(), api.emailSync(), api.mailbox()])
        setEmails(mailRows); setEmailSync(syncRow); setMailbox(mailboxRow)
      } catch (error) {
        console.info('Mail Center is waiting for the V1.2 database migration.', error)
      }
      try {
        setProductCustomerRelations(await api.productCustomerRelations())
      } catch (error) {
        console.info('Product relationships are waiting for the V1.5 database migration.', error)
      }
      try { setMembers(await api.workspaceMembers()) } catch (error) { console.info('Workspace member labels are waiting for the V1.8 database migration.', error) }
      try {
        const [taskRows, events, log] = await Promise.all([api.tasks(), api.timeline(), api.dailyLog(focusDate)])
        setTasks(taskRows); setTimelineEvents(events); setDailyLog(log)
      } catch (error) {
        console.info('Daily Focus is waiting for the V1.6 database migration.', error)
      }
      try {
        const [supplierRows, links, rfqs, insights] = await Promise.all([api.suppliers(), api.supplierProjectLinks(), api.supplierRfqs(), api.supplierInsights()])
        setSuppliers(supplierRows); setSupplierLinks(links); setSupplierRfqs(rfqs); setSupplierInsights(insights)
      } catch (error) {
        console.info('Supplier Center is waiting for the V1.12 database migration.', error)
      }
      try {
        const [searchTasks, leads, runs] = await Promise.all([api.leadSearchTasks(), api.customerLeads(), api.leadDiscoveryRuns()])
        setLeadSearchTasks(searchTasks); setCustomerLeads(leads); setLeadRuns(runs)
      } catch (error) {
        console.info('Lead Discovery is waiting for the V1.13 database migration.', error)
      }
    }
    void loadWorkspace().catch(error => console.error('Unable to load workspace data:', error))
  }, [authenticated, focusDate])
  useEffect(() => {
    const match = window.location.hash.match(/^#mail\/([^/]+)$/)
    if (!match || match[1] === 'unlinked') return
    const email = emails.find(item => item.id === match[1])
    if (email) { setView('mail'); setSelectedEmail(email) }
  }, [emails])
  useEffect(() => {
    if ('serviceWorker' in navigator) {
      void navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(error => console.info('PWA service worker unavailable', error))
    }
  }, [])
  const addCustomer = async (form: HTMLFormElement) => {
    const value = Object.fromEntries(new FormData(form)) as Record<string, string>
    const customer = await api.createCustomer({ company_name: value.company_name, country: value.country, contact_person: value.contact_person, email: value.email, whatsapp: value.whatsapp || '', product_interest: value.product_interest || '', customer_stage: 'New', next_followup_date: value.next_followup_date || '', notes: value.notes || '' })
    setCustomers(current => [customer, ...current])
    setModal(null)
  }
  const addProduct = async (form: HTMLFormElement) => {
    const value = Object.fromEntries(new FormData(form)) as Record<string, string>
    const list = (key: string) => (value[key] || '').split(/[,，\n]/).map(item => item.trim()).filter(Boolean)
    const payload = { product_name: value.product_name, product_code: value.product_code, category: value.category || '', application: value.application || '', description: value.description || '', notes: value.notes || '', technical_keywords: list('technical_keywords'), confirmed_applications: list('confirmed_applications'), target_industries: list('target_industries'), target_company_types: list('target_company_types'), exclusion_rules: list('exclusion_rules'), evidence_urls: list('evidence_urls'), profile_status: (value.profile_status || '草稿') as Product['profile_status'] }
    const product = await api.createProduct(payload)
    setProducts(current => [product, ...current])
    setModal(null)
  }
  const updateProductProfile = async (form: HTMLFormElement) => {
    if (!selectedProduct) return
    const value = Object.fromEntries(new FormData(form)) as Record<string, string>
    const list = (key: string) => (value[key] || '').split(/[,，\n]/).map(item => item.trim()).filter(Boolean)
    const payload = { product_name: value.product_name, product_code: value.product_code, category: value.category || '', application: value.application || '', description: value.description || '', notes: value.notes || '', technical_keywords: list('technical_keywords'), confirmed_applications: list('confirmed_applications'), target_industries: list('target_industries'), target_company_types: list('target_company_types'), exclusion_rules: list('exclusion_rules'), evidence_urls: list('evidence_urls'), profile_status: (value.profile_status || '草稿') as Product['profile_status'] }
    const product = await api.updateProduct(selectedProduct.id, payload)
    setProducts(current => current.map(item => item.id === product.id ? product : item))
    setSelectedProduct(product); setModal(null)
  }
  const addFollowup = async (form: HTMLFormElement) => {
    if (!selected) return
    const value = Object.fromEntries(new FormData(form)) as Record<string, string>
    const payload: Omit<Followup, 'id'> = { customer_id: selected.id, date: value.date, content: value.content, next_action: value.next_action || '安排下一步跟进', status: 'Open' }
    const record = sessionStorage.getItem('zhiwu-access-token') ? await api.createFollowup(payload) : { ...payload, id: `demo-followup-${Date.now()}` }
    setFollowupRows(current => [record, ...current]); setModal(null)
  }
  const addQuote = async (payload: Omit<Quote, 'id'>) => {
    const quote = sessionStorage.getItem('zhiwu-access-token') ? await api.createQuote(payload) : { ...payload, id: `demo-quote-${Date.now()}`, quote_number: `DEMO-${Date.now()}`, version: 1, created_at: new Date().toISOString().slice(0, 10) }
    setQuotes(current => [quote, ...current]); setModal(null)
  }
  const editQuote = async (quote: Quote, payload: Partial<Omit<Quote, 'id' | 'customer_id' | 'quote_number' | 'version' | 'created_at' | 'updated_at'>>) => {
    const updated = await api.updateQuote(quote.id, payload)
    setQuotes(current => current.map(item => item.id === updated.id ? updated : item)); setSelectedQuote(updated); setModal(null)
  }
  const createQuoteRevision = async (quote: Quote) => {
    const revision = await api.createQuoteRevision(quote.id)
    setQuotes(current => [revision, ...current]); setSelectedQuote(revision); setModal('quote-edit')
  }
  const importMailQuoteDrafts = async () => {
    const result = await api.quoteMailDrafts()
    setQuotes(current => [...result.quotes, ...current]); alert(result.message + `\n本次新增 ${result.created} 条草稿，跳过 ${result.skipped} 封。`)
  }
  const convertQuoteToOrder = async (quote: Quote) => {
    if (!window.confirm(`确认将 ${quote.quote_number || '该报价'} V${quote.version || 1} 转为销售订单？仅已接受且具真实发送凭证的报价可转换。`)) return
    const order = await api.convertQuoteToOrder(quote.id)
    setOrders(current => [order, ...current]); setQuotes(current => current.map(item => item.id === quote.id ? { ...item, converted_order_id: order.id } : item))
  }
  const updateStage = async (customer: Customer, stage: CustomerStage) => {
    const updated = { ...customer, customer_stage: stage }
    const { id: _id, created_at: _createdAt, last_contact_date: _lastContactDate, ...payload } = updated
    const next = sessionStorage.getItem('zhiwu-access-token') ? await api.updateCustomer(customer.id, payload) : updated
    setCustomers(current => current.map(item => item.id === customer.id ? next : item)); setSelected(next)
  }
  const editCustomer = async (form: HTMLFormElement) => {
    if (!selected) return
    const value = Object.fromEntries(new FormData(form)) as Record<string, string>
    const selectedProduct = products.find(product => product.id === value.product_id)
    const nextAction = value.next_action.split(/\r?\n/).map(item => item.trim()).filter(Boolean)
    const tags = value.customer_tags.split(/[,，\n]/).map(item => item.trim()).filter(Boolean)
    const edited: Customer = {
      ...selected,
      company_name: value.company_name.trim(), country: value.country.trim(), contact_person: value.contact_person.trim(), email: value.email.trim(),
      whatsapp: value.whatsapp.trim(), website: value.website.trim(), wechat: value.wechat.trim(), industry: value.industry.trim(),
      priority: value.priority as Customer['priority'], customer_value: Math.min(5, Math.max(1, Number(value.customer_value) || 3)),
      customer_stage: value.customer_stage as CustomerStage, product_interest: selectedProduct?.product_code || value.product_interest.trim(),
      application: value.application.trim(), next_followup_date: value.next_followup_date, status_label: value.status_label.trim(),
      customer_summary: value.customer_summary.trim(), customer_background: value.customer_background.trim(), customer_need: value.customer_need.trim(),
      important_notes: value.important_notes.trim(), notes: value.notes.trim(), customer_tags: tags, next_action: nextAction,
    }
    const { id: _id, created_at: _createdAt, last_contact_date: _lastContactDate, ...payload } = edited
    const updated = await api.updateCustomer(selected.id, payload)
    const projectId = value.project_id
    if (projectId) {
      const project = projects.find(item => item.id === projectId)
      if (project) {
        const projectUpdated = await api.updateProject(projectId, {
          project_name: value.project_name.trim() || project.project_name, product_id: value.product_id || undefined,
          application: value.application.trim(), stage: value.customer_stage as CustomerStage, notes: value.project_notes.trim(),
        })
        setProjects(current => current.map(item => item.id === projectUpdated.id ? projectUpdated : item))
      }
    }
    setCustomers(current => current.map(item => item.id === updated.id ? updated : item)); setSelected(updated); setModal(null)
  }
  const updateCrmFromEmail = async (email: MailEmail, payload: { customer_id: string; project_id?: string; product_id?: string; customer_stage: CustomerStage; next_action: string; followup_date: string; notes: string; create_task: boolean; task_date?: string }) => {
    const result = await api.updateCrmFromEmail(email.id, payload)
    setCustomers(current => current.map(item => item.id === result.customer.id ? result.customer : item))
    if (result.project) setProjects(current => current.map(item => item.id === result.project!.id ? result.project! : item))
    setFollowupRows(current => [result.followup, ...current])
    if (result.task) setTasks(current => [result.task!, ...current])
    setEmails(current => current.map(item => item.id === email.id ? result.email : item))
    setSelectedEmail(current => current?.id === email.id ? result.email : current)
  }
  const linkEmail = async (email: MailEmail, customer: Customer) => {
    const linked = await api.linkEmail(email.id, { customer_id: customer.id, contact_name: customer.contact_person })
    setEmails(current => current.map(item => item.id === email.id ? linked : item))
    setSelectedEmail(current => current?.id === email.id ? linked : current)
  }
  const createCustomerFromEmail = async (email: MailEmail, payload: Omit<Customer, 'id' | 'created_at' | 'last_contact_date'>) => {
    const result = await api.createCustomerFromEmail(email.id, payload)
    setCustomers(current => [result.customer, ...current])
    setEmails(current => current.map(item => item.id === email.id ? result.email : item))
    setSelectedEmail(current => current?.id === email.id ? result.email : current)
  }
  const updateEmailStatus = async (email: MailEmail, status: MailEmail['status']) => {
    const updated = await api.updateEmailStatus(email.id, status)
    setEmails(current => current.map(item => item.id === email.id ? updated : item))
    setSelectedEmail(current => current?.id === email.id ? updated : current)
  }
  const linkProductCustomer = async (customer: Customer) => {
    if (!relationProduct) return
    const relation = await api.linkProductCustomer(relationProduct.id, customer.id)
    setProductCustomerRelations(current => current.some(item => item.id === relation.id) ? current : [relation, ...current])
    setRelationProduct(null)
  }
  const addTask = async (form: HTMLFormElement) => {
    const value = Object.fromEntries(new FormData(form)) as Record<string, string>
    const task = await api.createTask({
      title: value.title, description: value.description || '', category: value.category as Task['category'], priority: value.priority as Task['priority'], status: 'Pending',
      task_date: value.task_date, start_time: value.start_time || null, end_time: value.end_time || null,
      estimated_minutes: value.estimated_minutes ? Number(value.estimated_minutes) : null,
      customer_id: value.customer_id || null, project_id: value.project_id || null, product_id: value.product_id || null,
    })
    setTasks(current => [...current, task].sort((a, b) => `${a.task_date}${a.start_time || ''}`.localeCompare(`${b.task_date}${b.start_time || ''}`)))
    setModal(null)
  }
  const toggleTask = async (task: Task) => {
    const updated = await api.updateTaskStatus(task.id, task.status === 'Completed' ? 'Pending' : 'Completed')
    setTasks(current => current.map(item => item.id === task.id ? updated : item))
    if (updated.status === 'Completed') {
      const events = await api.timeline({ event_date: focusDate })
      setTimelineEvents(current => [...events, ...current.filter(item => item.event_date !== focusDate)])
    }
  }
  const saveDailyReview = async (form: HTMLFormElement) => {
    const value = Object.fromEntries(new FormData(form)) as Record<string, string>
    const record = await api.saveDailyLog(focusDate, { summary: value.summary || '', problem: value.problem || '', tomorrow_plan: value.tomorrow_plan || '', rating: value.rating ? Number(value.rating) : null })
    setDailyLog(record); setModal(null)
    setTimelineEvents(await api.timeline())
  }
  const openEmail = (email: MailEmail) => {
    window.history.replaceState(null, '', `${window.location.pathname}#mail/${email.id}`)
    setView('mail'); setSelectedEmail(email)
  }
  const openNotificationTask = (task: Task) => {
    setFocusDate(task.task_date)
    setView('tasks')
    setNotificationsOpen(false)
  }
  const openNotificationEmail = (email: MailEmail) => {
    setNotificationsOpen(false)
    openEmail(email)
  }
  const signOut = () => {
    sessionStorage.removeItem('zhiwu-access-token')
    sessionStorage.removeItem('zhiwu-account-email')
    window.history.replaceState(null, '', window.location.pathname)
    setAccountMenuOpen(false)
    setNotificationsOpen(false)
    setAuthenticated(false)
  }
  if (!authenticated) return <Login onAuthenticated={() => setAuthenticated(true)} />
  return <div className="app-shell">
    <aside className={`sidebar ${sidebar ? 'is-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><img src={`${import.meta.env.BASE_URL}favicon.svg`} alt="干就是学工作站"/></div><div><strong>干就是学</strong><span>工作站</span></div><button className="mobile-close" onClick={() => setSidebar(false)}><X size={18}/></button></div>
      <nav>{nav.map(([key, label, Icon]) => <button key={key} className={view === key ? 'active' : ''} onClick={() => { if (key === 'dashboard' || key === 'crm' || key === 'leads' || key === 'suppliers' || key === 'mail' || key === 'products' || key === 'relationships' || key === 'projects' || key === 'tasks' || key === 'calendar' || key === 'imports') setView(key as View); setSidebar(false) }}><Icon size={18}/><span>{label}</span>{key === 'crm' && crmActionCount > 0 && <em title="待补资料或逾期跟进的客户">{crmActionCount}</em>}{key === 'leads' && customerLeads.filter(lead => lead.status === '待审核').length > 0 && <em title="待审核公开线索">{customerLeads.filter(lead => lead.status === '待审核').length}</em>}{key === 'suppliers' && suppliers.filter(supplier => supplier.next_followup_date && supplier.next_followup_date <= new Date().toISOString().slice(0, 10)).length > 0 && <em title="到期供应商跟进">{suppliers.filter(supplier => supplier.next_followup_date && supplier.next_followup_date <= new Date().toISOString().slice(0, 10)).length}</em>}</button>)}</nav>
      <div className="nav-bottom"><a href="https://notes.101921.xyz/" target="_blank" rel="noopener noreferrer" aria-label="在新标签页打开知识库"><CalendarDays size={18}/><span>知识库 ↗</span></a><button onClick={() => setModal('password')}><Settings size={18}/><span>设置</span></button><button className="profile" onClick={() => setModal('password')}><div className="avatar">{account.initial}</div><div><b>{account.name}</b><small>{account.role} · 修改密码</small></div><ChevronRight size={16}/></button></div>
    </aside>
    <main>
      <header><button className="menu" onClick={() => setSidebar(true)}><Menu/></button><div className="crumb">工作空间 <ChevronRight size={15}/> <b>{{ dashboard: '总览', crm: '外贸 CRM', leads: '客户线索发现', suppliers: '供应商中心', mail: '邮件中心', products: '产品中心', relationships: '产品关系', quotes: '报价管理', imports: 'AI 导入暂存箱', tasks: '每日计划', calendar: '工作日历', projects: '项目推进' }[view]}</b></div><div className="header-actions"><label className="global-search"><Search size={17}/><input value={globalQuery} onChange={event => setGlobalQuery(event.target.value)} placeholder="搜索客户、产品、项目或邮件" /></label><button className="theme-toggle" type="button" onClick={() => setTheme(current => current === 'dark' ? 'light' : 'dark')} aria-label={theme === 'dark' ? '切换到浅色模式' : '切换到深色模式'} title={theme === 'dark' ? '切换到浅色模式' : '切换到深色模式'}>{theme === 'dark' ? <Sun size={17}/> : <Moon size={17}/>}<span>{theme === 'dark' ? '浅色' : '深色'}</span></button><div className="notification-wrap"><button className="icon-button" aria-label="打开提醒中心" aria-expanded={notificationsOpen} onClick={() => setNotificationsOpen(current => !current)}><Bell size={19}/>{hasNotifications && <i/>}</button>{notificationsOpen && <NotificationCenter tasks={tasks} emails={emails} onOpenTask={openNotificationTask} onOpenEmail={openNotificationEmail} onOpenTasks={() => { setFocusDate(new Date().toISOString().slice(0, 10)); setView('tasks'); setNotificationsOpen(false) }} onOpenMail={() => { setView('mail'); setNotificationsOpen(false) }} />}</div><div className="account-menu"><button className="avatar avatar-small account-trigger" aria-label="打开账号菜单" aria-expanded={accountMenuOpen} onClick={() => setAccountMenuOpen(current => !current)}>{account.initial}</button>{accountMenuOpen && <div className="account-popover"><b>{account.name}</b><small>{account.email || '当前登录账号'}</small><button onClick={signOut}><LogOut size={15}/>退出登录</button></div>}</div></div></header>
      {globalQuery.trim() && <WorkspaceSearch query={globalQuery} customers={customers} products={products} projects={projects} emails={emails} close={() => setGlobalQuery('')} openCustomer={customer => { setView('crm'); setSelected(customer) }} openProduct={() => setView('products')} openProject={customer => { setView('projects'); setSelected(customer) }} openEmail={openEmail} />}
      {view === 'dashboard' && <><Dashboard customers={customers} projects={projects} followups={followupRows} emails={emails} tasks={tasks} today={today} onOpenCRM={() => setView('crm')} onOpenMail={() => setView('mail')} onOpenTasks={() => setView('tasks')} onOpenProducts={() => setView('products')} openCustomer={setSelected} /><SupplierDashboard suppliers={suppliers} rfqs={supplierRfqs} links={supplierLinks} insights={supplierInsights} open={() => setView('suppliers')} onOpenSupplier={setSelectedSupplier}/></>}
      {view === 'crm' && <CRM customers={visibleCustomers} allCustomers={customers} projects={projects} members={members} query={query} setQuery={setQuery} filter={crmFilter} setFilter={setCrmFilter} open={setSelected} create={() => setModal('customer')} addFollowup={customer => { setSelected(customer); setModal('followup') }} />}
      {view === 'leads' && <LeadDiscovery products={products} tasks={leadSearchTasks} leads={customerLeads} runs={leadRuns} onChanged={async () => { const [searchTasks, leads, runs, taskRows, customerRows] = await Promise.all([api.leadSearchTasks(), api.customerLeads(), api.leadDiscoveryRuns(), api.tasks(), api.customers()]); setLeadSearchTasks(searchTasks); setCustomerLeads(leads); setLeadRuns(runs); setTasks(taskRows); setCustomers(customerRows) }} />}
      {view === 'suppliers' && <SupplierCenter suppliers={suppliers} links={supplierLinks} rfqs={supplierRfqs} insights={supplierInsights} open={setSelectedSupplier} create={() => setSupplierModal('create')} link={() => setSupplierModal('link')} createRfq={() => setSupplierModal('rfq')} />}
      {view === 'mail' && <MailCenter emails={emails} sync={emailSync} mailbox={mailbox} customers={customers} projects={projects} products={products} open={openEmail} />}
      {view === 'imports' && <ImportInbox customers={customers} afterApplied={async () => { const [customerRows, productRows, loadedFollowups, loadedProjects, taskRows, events, supplierRows, links, rfqs, insights] = await Promise.all([api.customers(), api.products(), api.followups(), api.projects(), api.tasks(), api.timeline(), api.suppliers(), api.supplierProjectLinks(), api.supplierRfqs(), api.supplierInsights()]); setCustomers(customerRows); setProducts(productRows); setFollowupRows(loadedFollowups); setProjects(loadedProjects); setTasks(taskRows); setTimelineEvents(events); setSuppliers(supplierRows); setSupplierLinks(links); setSupplierRfqs(rfqs); setSupplierInsights(insights) }} />}
      {view === 'products' && <Products products={products} customers={customers} relations={productCustomerRelations} projects={projects} followups={followupRows} emails={emails} tasks={tasks} timelineEvents={timelineEvents} create={() => setModal('product')} edit={product => { setSelectedProduct(product); setModal('product-edit') }} history={product => { setHistoryProduct(product); setModal('product-history') }} />}
      {view === 'relationships' && <RelationshipMatrix products={products} customers={customers} projects={projects} relations={productCustomerRelations} openCustomer={setSelected} linkCustomer={setRelationProduct} />}
      {view === 'quotes' && <QuoteManagement quotes={quotes} orders={orders} customers={customers} projects={projects} products={products} emails={emails} create={() => { setSelectedQuote(null); setModal('quote') }} edit={quote => { setSelectedQuote(quote); setModal('quote-edit') }} revise={createQuoteRevision} convert={convertQuoteToOrder} importMailDrafts={importMailQuoteDrafts} />}
      {view === 'projects' && <ProjectManagement projects={projects} customers={customers} members={members} products={products} quotes={quotes} followups={followupRows} emails={emails} tasks={tasks} timelineEvents={timelineEvents} suppliers={suppliers} supplierLinks={supplierLinks} supplierRfqs={supplierRfqs} openCustomer={setSelected} openProject={setSelectedProject} />}
      {view === 'tasks' && <><Workbench queue={workbench} openMail={() => setView('mail')} /><DailyFocus tasks={tasks} customers={customers} projects={projects} products={products} focusDate={focusDate} today={today} dailyLog={dailyLog} setFocusDate={setFocusDate} create={() => setModal('task')} complete={toggleTask} review={() => setModal('review')} /></>}
      {view === 'calendar' && <CalendarView tasks={tasks} events={timelineEvents} customers={customers} focusDate={focusDate} setFocusDate={setFocusDate} onOpenTasks={() => setView('tasks')} />}
    </main>
    {selected && <CustomerDrawer customer={selected} projects={projects} quotes={quotes} followups={followupRows} products={products} emails={emails} tasks={tasks} timelineEvents={timelineEvents} suppliers={suppliers} supplierLinks={supplierLinks} close={() => setSelected(null)} addFollowup={() => setModal('followup')} addQuote={() => setModal('quote')} updateStage={updateStage} editCustomer={() => setModal('customer-edit')} openEmail={openEmail} />}
    {selectedSupplier && <SupplierDrawer supplier={selectedSupplier} customers={customers} projects={projects} products={products} links={supplierLinks.filter(link => link.supplier_id === selectedSupplier.id)} rfqs={supplierRfqs.filter(rfq => rfq.supplier_id === selectedSupplier.id)} close={() => setSelectedSupplier(null)} changed={async () => { const [supplierRows, links, rfqs, insights] = await Promise.all([api.suppliers(), api.supplierProjectLinks(), api.supplierRfqs(), api.supplierInsights()]); setSuppliers(supplierRows); setSupplierLinks(links); setSupplierRfqs(rfqs); setSupplierInsights(insights) }} />}
    {selectedEmail && <MailDetail email={selectedEmail} customers={customers} projects={projects} products={products} close={() => { window.history.replaceState(null, '', `${window.location.pathname}#mail`); setSelectedEmail(null) }} updateCrm={updateCrmFromEmail} linkEmail={linkEmail} createCustomer={createCustomerFromEmail} updateStatus={updateEmailStatus} openCustomer={setSelected} />}
    {selectedProject && <ProjectWarRoom project={selectedProject} customers={customers} members={members} products={products} quotes={quotes} followups={followupRows} emails={emails} tasks={tasks} timelineEvents={timelineEvents} suppliers={suppliers} supplierLinks={supplierLinks} supplierRfqs={supplierRfqs} close={() => setSelectedProject(null)} openCustomer={customer => { setSelectedProject(null); setSelected(customer) }} openEmail={email => { setSelectedProject(null); setSelectedEmail(email) }} />}
    {modal === 'customer' && <CustomerForm close={() => setModal(null)} submit={addCustomer} />}
    {modal === 'customer-edit' && selected && <CustomerEditForm customer={selected} products={products} projects={projects.filter(project => project.customer_id === selected.id)} close={() => setModal(null)} submit={editCustomer} />}
    {modal === 'product' && <ProductForm close={() => setModal(null)} submit={addProduct} />}
    {modal === 'product-edit' && selectedProduct && <ProductForm product={selectedProduct} close={() => setModal(null)} submit={updateProductProfile} />}
    {modal === 'product-history' && historyProduct && <ProductHistory product={historyProduct} customers={customers} relations={productCustomerRelations} projects={projects} followups={followupRows} emails={emails} tasks={tasks} timelineEvents={timelineEvents} close={() => setModal(null)} />}
    {modal === 'followup' && selected && <FollowupForm customer={selected} close={() => setModal(null)} submit={addFollowup} />}
    {modal === 'quote' && <QuoteForm customer={selected || undefined} customers={customers} projects={projects} products={products} emails={emails} close={() => setModal(null)} submit={addQuote} />}
    {modal === 'quote-edit' && selectedQuote && <QuoteForm quote={selectedQuote} customers={customers} projects={projects} products={products} emails={emails} close={() => setModal(null)} submit={payload => editQuote(selectedQuote, payload)} />}
    {modal === 'task' && <TaskForm close={() => setModal(null)} submit={addTask} customers={customers} projects={projects} products={products} initialDate={focusDate} />}
    {modal === 'review' && <DailyReviewForm close={() => setModal(null)} submit={saveDailyReview} value={dailyLog} date={focusDate} />}
    {modal === 'password' && <PasswordForm close={() => setModal(null)} />}
    {relationProduct && <ProductCustomerLinkModal product={relationProduct} customers={customers} relations={productCustomerRelations} close={() => setRelationProduct(null)} submit={linkProductCustomer} />}
    {supplierModal === 'create' && <SupplierForm close={() => setSupplierModal(null)} submit={async supplier => { const created = await api.createSupplier(supplier); setSuppliers(current => [created, ...current]); setSupplierModal(null); setSelectedSupplier(created) }} />}
    {supplierModal === 'link' && <SupplierLinkForm suppliers={suppliers} customers={customers} projects={projects} close={() => setSupplierModal(null)} submit={async link => { const created = await api.createSupplierProjectLink(link); setSupplierLinks(current => [created, ...current]); setSupplierModal(null) }} />}
    {supplierModal === 'rfq' && <SupplierRfqForm suppliers={suppliers} customers={customers} projects={projects} close={() => setSupplierModal(null)} submit={async rfq => { const created = await api.createSupplierRfq(rfq); setSupplierRfqs(current => [created, ...current]); setSupplierModal(null) }} />}
    <nav className="mobile-bottom-nav" aria-label="移动快捷导航"><button className={view === 'dashboard' ? 'active' : ''} onClick={() => setView('dashboard')}><Home size={19}/><span>首页</span></button><button className={view === 'crm' ? 'active' : ''} onClick={() => setView('crm')}><Users size={19}/><span>客户</span></button><button className={view === 'mail' ? 'active' : ''} onClick={() => setView('mail')}><Mail size={19}/><span>邮件</span></button><button className={view === 'tasks' ? 'active' : ''} onClick={() => setView('tasks')}><CircleCheck size={19}/><span>任务</span></button><button onClick={() => setSidebar(true)}><MoreHorizontal size={20}/><span>更多</span></button></nav>
  </div>
}

function NotificationCenter({ tasks, emails, onOpenTask, onOpenEmail, onOpenTasks, onOpenMail }: { tasks: Task[]; emails: MailEmail[]; onOpenTask: (task: Task) => void; onOpenEmail: (email: MailEmail) => void; onOpenTasks: () => void; onOpenMail: () => void }) {
  const today = new Date().toISOString().slice(0, 10)
  const todayTasks = tasks.filter(task => task.task_date === today && task.status !== 'Completed').sort((a, b) => `${a.start_time || ''}${a.title}`.localeCompare(`${b.start_time || ''}${b.title}`)).slice(0, 3)
  const newEmails = emails.filter(email => ['unread', 'new_lead'].includes(email.status)).sort((a, b) => b.received_at.localeCompare(a.received_at)).slice(0, 3)
  const total = todayTasks.length + newEmails.length
  return <section className="notification-center" aria-label="工作提醒"><div className="notification-head"><div><p>WORKSPACE ALERTS</p><h2>提醒中心</h2></div>{total > 0 && <span>{total} 项待处理</span>}</div>{todayTasks.length > 0 && <div className="notification-group"><div className="notification-group-head"><b><CircleCheck size={15}/> 今日待办</b><button onClick={onOpenTasks}>查看全部</button></div>{todayTasks.map(task => <button className="notification-row" key={task.id} onClick={() => onOpenTask(task)}><span className={`notification-symbol ${task.priority}`}><ClipboardList size={14}/></span><div><b>{task.title}</b><small>{task.start_time ? `${task.start_time} · ` : ''}{task.category} · 待完成</small></div><ChevronRight size={15}/></button>)}</div>}{newEmails.length > 0 && <div className="notification-group"><div className="notification-group-head"><b><Mail size={15}/> 新邮件</b><button onClick={onOpenMail}>查看全部</button></div>{newEmails.map(email => <button className="notification-row" key={email.id} onClick={() => onOpenEmail(email)}><span className="notification-symbol mail"><Mail size={14}/></span><div><b>{email.sender_name || email.sender}</b><small>{email.subject || '无主题'}</small></div><time>{email.received_at.slice(5, 10)}</time><ChevronRight size={15}/></button>)}</div>}{total === 0 && <div className="notification-empty"><CircleCheck size={20}/><b>暂时没有需要处理的提醒</b><span>今天的待办和新邮件都会显示在这里。</span></div>}</section>
}

function WorkspaceSearch({ query, customers, products, projects, emails, close, openCustomer, openProduct, openProject, openEmail }: { query: string; customers: Customer[]; products: Product[]; projects: Project[]; emails: MailEmail[]; close: () => void; openCustomer: (customer: Customer) => void; openProduct: (product: Product) => void; openProject: (customer: Customer) => void; openEmail: (email: MailEmail) => void }) {
  const needle = query.trim().toLowerCase()
  const customerMatches = customers.filter(customer => `${customer.company_name} ${customer.country} ${customer.contact_person} ${customer.product_interest} ${customer.application || ''} ${(customer.customer_tags || []).join(' ')} ${customer.customer_summary || ''}`.toLowerCase().includes(needle)).slice(0, 4)
  const productMatches = products.filter(product => `${product.product_name} ${product.product_code} ${product.category} ${product.application}`.toLowerCase().includes(needle)).slice(0, 4)
  const projectMatches = projects.map(project => ({ project, customer: customers.find(customer => customer.id === project.customer_id) })).filter(({ project, customer }) => `${project.project_name} ${project.application} ${project.stage} ${customer?.company_name || ''}`.toLowerCase().includes(needle)).slice(0, 4)
  const emailMatches = emails.filter(email => `${email.sender_name || ''} ${email.sender} ${email.subject}`.toLowerCase().includes(needle)).slice(0, 4)
  const total = customerMatches.length + productMatches.length + projectMatches.length + emailMatches.length
  const choose = (callback: () => void) => { callback(); close() }
  return <div className="workspace-search-layer" onClick={close}><section className="workspace-search-results" onClick={event => event.stopPropagation()}><div className="workspace-search-head"><b>搜索结果</b><span>{total ? `“${query.trim()}”相关结果` : '没有匹配结果'}</span><button onClick={close}><X size={16}/></button></div>{customerMatches.length > 0 && <SearchGroup title="客户">{customerMatches.map(customer => <button key={customer.id} onClick={() => choose(() => openCustomer(customer))}><Users size={15}/><div><b>{customer.company_name}</b><span>{customer.country} · {customer.contact_person} · {customer.product_interest}</span></div><ChevronRight size={15}/></button>)}</SearchGroup>}{productMatches.length > 0 && <SearchGroup title="产品">{productMatches.map(product => <button key={product.id} onClick={() => choose(() => openProduct(product))}><Package size={15}/><div><b>{product.product_code} · {product.product_name}</b><span>{product.application}</span></div><ChevronRight size={15}/></button>)}</SearchGroup>}{projectMatches.length > 0 && <SearchGroup title="项目">{projectMatches.map(({ project, customer }) => <button key={project.id} onClick={() => customer && choose(() => openProject(customer))}><Layers3 size={15}/><div><b>{project.project_name}</b><span>{customer?.company_name || '待关联客户'} · {project.stage}</span></div><ChevronRight size={15}/></button>)}</SearchGroup>}{emailMatches.length > 0 && <SearchGroup title="邮件主题">{emailMatches.map(email => <button key={email.id} onClick={() => choose(() => openEmail(email))}><Mail size={15}/><div><b>{email.subject}</b><span>{email.sender_name || email.sender}</span></div><ChevronRight size={15}/></button>)}</SearchGroup>}{!total && <div className="workspace-search-empty">试试输入：客户名称、产品编号、国家、项目名称或邮件主题。</div>}</section></div>
}
function SearchGroup({ title, children }: { title: string; children: ReactNode }) { return <section className="workspace-search-group"><h2>{title}</h2>{children}</section> }

function Dashboard({ customers, projects, followups, emails, tasks, today, onOpenCRM, onOpenMail, onOpenTasks, onOpenProducts, openCustomer }: { customers: Customer[]; projects: Project[]; followups: Followup[]; emails: MailEmail[]; tasks: Task[]; today: string; onOpenCRM: () => void; onOpenMail: () => void; onOpenTasks: () => void; onOpenProducts: () => void; openCustomer: (customer: Customer) => void }) {
  const reminders = customers.filter(customer => customer.customer_stage !== 'Maintain Relationship' && customer.customer_stage !== 'Won').sort((a, b) => a.next_followup_date.localeCompare(b.next_followup_date)).slice(0, 4)
  const currentDate = new Date().toISOString().slice(0, 10)
  const todayTasks = tasks.filter(task => task.task_date === currentDate).sort((a, b) => `${a.start_time || ''}${a.title}`.localeCompare(`${b.start_time || ''}${b.title}`)).slice(0, 4)
  const pipeline = [
    ['New Inquiry', customers.filter(c => c.customer_stage === 'New' || c.customer_stage === 'New Inquiry' || c.customer_stage === 'Inquiry').length],
    ['Quotation', customers.filter(c => c.customer_stage === 'Quotation' || c.customer_stage === 'Quoted').length],
    ['Sample', customers.filter(c => c.customer_stage.includes('Sample')).length],
    ['Testing', customers.filter(c => c.customer_stage === 'Technical Testing' || c.customer_stage === 'Technical Confirmation').length],
    ['Negotiation', customers.filter(c => c.customer_stage === 'Negotiation').length], ['Won', customers.filter(c => c.customer_stage === 'Won').length],
  ]
  const samplesPending = customers.filter(c => c.customer_stage.includes('Sample')).length
  const recentUpdates = [...followups].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 3)
  const mailActions = emails.filter(email => ['unread', 'new_lead', 'linked'].includes(email.status)).slice(0, 3)
  return <section className="page dashboard"><div className="hero"><div><p className="eyebrow"><span className="pulse"/> {today}</p><h1>早上好，Zhiwu <span>✦</span></h1><p className="subhead">一眼看清客户状态、项目阶段与下一步商业机会。</p></div></div><MobileDashboardFocus tasks={todayTasks} reminders={reminders.length} emails={mailActions.length} onOpenCRM={onOpenCRM} onOpenMail={onOpenMail} onOpenTasks={onOpenTasks} onOpenProducts={onOpenProducts}/>
    <p className="section-kicker">TODAY'S SALES STATUS</p><div className="metrics metrics-six"><Metric label="客户总数" value={String(customers.length)} delta="来自 CRM 实时统计" icon={<Users/>}/><Metric label="进行中项目" value={String(projects.length)} delta="聚焦本周推进" icon={<Layers3/>}/><Metric label="报价中" value={String(pipeline[1][1])} delta="等待价格沟通" icon={<ClipboardList/>}/><Metric label="样品阶段" value={String(samplesPending)} delta="样品与付款待推进" icon={<Package/>}/><Metric label="待跟进客户" value={String(reminders.length)} delta="按下一步行动排序" icon={<Bell/>}/><Metric label="产品数量" value="5" delta="已关联客户项目" icon={<Sparkles/>}/></div>
    <section className="panel pipeline"><PanelTitle title="销售漏斗" action="进入 CRM" onAction={onOpenCRM}/><div className="pipeline-list">{pipeline.map(([label, count], index) => <button key={label} className="pipeline-step" onClick={onOpenCRM}><span className="pipeline-index">0{index + 1}</span><span>{label}</span><b>{count}</b><i style={{ width: `${Math.max(10, Number(count) / 6 * 100)}%` }}/></button>)}</div></section>
    <div className="dashboard-grid"><section className="panel tasks"><PanelTitle title="Today's Focus" action="进入每日计划" onAction={onOpenTasks}/><div>{todayTasks.length ? todayTasks.map(task => <button className="task" key={task.id} onClick={onOpenTasks}><span className={`task-box ${task.status === 'Completed' ? 'checked' : ''}`}>{task.status === 'Completed' && <Check size={13}/>}</span><span>{task.title}</span>{task.priority === 'important' && <b>重要</b>}<ChevronRight size={16}/></button>) : <p className="detail-empty">今天还没有任务，先安排一件最重要的事。</p>}</div><button className="add-line" onClick={onOpenTasks}><Plus size={17}/> 添加任务</button></section>
    <section className="panel reminders"><PanelTitle title="Customer Intelligence" action="进入 CRM" onAction={onOpenCRM}/>{reminders.map((customer, index) => <button className="reminder-row" key={customer.id} onClick={() => openCustomer(customer)}><span className={`reminder-dot ${customer.status_tone ?? (index ? 'attention' : 'warning')}`}>{customer.status_tone === 'success' ? '●' : '⚠'}</span><div><b>{customer.company_name}</b><span>{customer.next_action?.[0] ?? customer.status_label ?? customer.customer_need ?? '安排下一步行动'}</span></div><time>{customer.next_followup_date.slice(5).replace('-', '/')}</time><ChevronRight size={16}/></button>)}</section>
    <section className="panel mail-alert-panel"><PanelTitle title="Mail Follow-up" action="进入邮件中心" onAction={onOpenMail}/>{mailActions.length ? mailActions.map(email => { const customer = customers.find(item => item.id === email.customer_id); return <div className="mail-alert" key={email.id}><Mail size={15}/><div><b>{customer?.company_name ?? email.sender_name ?? email.sender}</b><span>{customer?.next_action?.[0] ?? email.subject}</span></div><em>{email.status === 'new_lead' ? '新线索' : '待行动'}</em></div> }) : <p className="mail-alert-empty">暂无待处理业务邮件</p>}</section></div>
    <section className="panel activity"><PanelTitle title="Recent Updates" action="查看全部"/><div className="timeline">{recentUpdates.map((update, index) => { const customer = customers.find(item => item.id === update.customer_id); return <Activity key={update.id} icon={index === 1 ? <Package/> : index === 2 ? <Check/> : <Users/>} title={`${customer?.company_name ?? '客户'} · ${update.content}`} text={`Next: ${update.next_action}`} time={update.date}/>} )}</div></section>
  </section>
}

function LeadDiscovery({ products, tasks, leads, runs, onChanged }: { products: Product[]; tasks: LeadSearchTask[]; leads: CustomerLead[]; runs: LeadDiscoveryRun[]; onChanged: () => Promise<void> }) {
  const [openTaskForm, setOpenTaskForm] = useState(false)
  const [editingTask, setEditingTask] = useState<LeadSearchTask | null>(null)
  const [busy, setBusy] = useState(false)
  const [layer, setLayer] = useState<NonNullable<CustomerLead['lead_layer']>>('直接需求候选')
  const [taskFilter, setTaskFilter] = useState('')
  const [countryFilter, setCountryFilter] = useState('')
  const [typeFilter, setTypeFilter] = useState('')
  const [gradeFilter, setGradeFilter] = useState('')
  const [contactFilter, setContactFilter] = useState<'all' | 'email' | 'phone' | 'both'>('all')
  const today = new Date().toISOString().slice(0, 10)
  const scopedLeads = taskFilter ? leads.filter(lead => lead.task_id === taskFilter) : leads
  const selectedTask = tasks.find(task => task.id === taskFilter)
  const latestRun = taskFilter ? runs.find(run => run.task_id === taskFilter) : runs[0]
  const taskNameById = new Map(tasks.map(task => [task.id, task.task_name]))
  const bucketOf = (lead: CustomerLead): CustomerLead['verification_bucket'] => lead.verification_bucket || (lead.status === '已排除' ? '排除名单' : '待补信息')
  const strict = scopedLeads.filter(lead => bucketOf(lead) === '严格客户名单')
  const layerOf = (lead: CustomerLead): NonNullable<CustomerLead['lead_layer']> => lead.lead_layer || (bucketOf(lead) === '排除名单' ? '排除' : lead.discovery_mode === '供应工厂' ? '供应工厂候选' : '待判定')
  const direct = scopedLeads.filter(lead => layerOf(lead) === '直接需求候选')
  const indirect = scopedLeads.filter(lead => layerOf(lead) === '间接应用链')
  const suppliers = scopedLeads.filter(lead => layerOf(lead) === '供应工厂候选')
  const excluded = scopedLeads.filter(lead => layerOf(lead) === '排除')
  const countries = [...new Set(scopedLeads.map(lead => lead.country).filter(Boolean))] as string[]
  const companyTypes = [...new Set(scopedLeads.map(lead => lead.company_type).filter(Boolean))] as string[]
  const shown = scopedLeads.filter(lead => {
    if (layerOf(lead) !== layer) return false
    if (countryFilter && lead.country !== countryFilter) return false
    if (typeFilter && lead.company_type !== typeFilter) return false
    if (gradeFilter && lead.matching_grade !== gradeFilter) return false
    if (contactFilter === 'email' && !lead.public_business_email) return false
    if (contactFilter === 'phone' && !lead.public_business_phone) return false
    if (contactFilter === 'both' && (!lead.public_business_email || !lead.public_business_phone)) return false
    return true
  })
  const run = async (work: () => Promise<unknown>) => { setBusy(true); try { await work(); await onChanged() } catch (error) { alert(error instanceof Error ? error.message : '操作失败，请稍后重试。') } finally { setBusy(false) } }
  const runTask = (task: LeadSearchTask) => run(async () => { setTaskFilter(task.id); setCountryFilter(''); setTypeFilter(''); setGradeFilter(''); setContactFilter('all'); await api.runLeadSearchTask(task.id) })
  const review = (lead: CustomerLead, status: CustomerLead['status']) => run(async () => {
    const exclusionReason = status === '已排除' ? window.prompt('排除原因（例如非目标行业、重复或无效）') || '人工排除' : undefined
    await api.reviewCustomerLead(lead.id, { status, exclusion_reason: exclusionReason })
  })
  const removeTask = (task: LeadSearchTask) => run(async () => {
    if (!window.confirm(`删除搜索任务“${task.task_name}”？\n\n只会删除该任务配置并停止每日运行；已抓到的线索和运行记录会保留。`)) return
    const result = await api.deleteLeadSearchTask(task.id)
    alert(result.message)
  })
  const createTask = (lead: CustomerLead) => run(() => api.createDevelopmentTaskFromLead(lead.id, { priority: lead.match_score >= 70 ? 'important' : 'normal', task_date: today, suggested_next_action: '查看官网并确认业务与目标应用的匹配度；仅在人工确认后决定是否联系。' }))
  const convert = (lead: CustomerLead) => run(async () => {
    if (!window.confirm(`确认将“${lead.company_name}”转入外贸 CRM？系统会先按邮箱、官网域名和公司名去重；不会自动发送任何信息。`)) return
    await api.convertCustomerLead(lead.id, { email: lead.public_business_email || undefined, contact_person: lead.public_contact_name || undefined, country: lead.country || undefined, product_interest: lead.discovered_product_keywords.join(', ') || undefined, application: lead.discovered_application_keywords.join(', ') || undefined, next_action: '人工审核线索后，确认下一步开发动作。', next_followup_date: today, notes: `公开网页线索来源：${lead.source_url}` })
  })
  const importStrictWorkbook = (file?: File) => { if (!file) return; void run(async () => { const result = await api.importCpph2aStrictLeads(file); alert(`严格名单导入完成：${result.total} 家（新增 ${result.inserted}，更新 ${result.updated}；A 类 ${result.a_count}，B 类 ${result.b_count}）。`) }) }
  return <section className="page lead-page"><div className="page-heading"><div><p className="eyebrow"><Radar size={13}/> VERIFIED PUBLIC-WEB DISCOVERY</p><h1>严格客户核验</h1><p>每个产品都先建立自己的下游应用画像，再寻找实际生产或配制这些应用的企业；目录只用于发现企业。自动发现只会进入待补信息，人工严格核验后才可进入 CRM。</p></div><div className="page-actions"><button className="secondary" onClick={() => { setEditingTask(null); setOpenTaskForm(true) }}><Settings size={16}/> 应用画像与任务</button><label className="secondary import-lead-button"><Upload size={16}/> 导入严格 Excel<input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" disabled={busy} onChange={event => { importStrictWorkbook(event.target.files?.[0]); event.currentTarget.value = '' }}/></label><button className="secondary" disabled={busy || !strict.length} onClick={() => void run(() => api.exportStrictCustomerLeads())}>导出 Excel</button><button className="primary" disabled={busy || !tasks.length} onClick={() => void run(() => api.runEnabledLeadSearchTasks())}><RefreshCw size={16}/> {busy ? '正在分析并搜索…' : '按产品画像开始搜索'}</button></div></div>
    <div className="metrics lead-metrics strict-metrics"><Metric icon={<Users/>} label="严格客户" value={String(strict.length)} delta="满足六项硬门槛"/><Metric icon={<Sparkles/>} label="直接需求候选" value={String(direct.length)} delta="目标企业类型与应用均命中"/><Metric icon={<CircleHelp/>} label="间接应用链" value={String(indirect.length)} delta="仅作市场线索，不能进 CRM"/><Metric icon={<Factory/>} label="供应工厂候选" value={String(suppliers.length)} delta="中国大陆生产主体待核验"/><Metric icon={<X/>} label="排除" value={String(excluded.length)} delta="同行、贸易商、媒体、目录等"/></div>
    <div className="compliance-note"><b>产品通用应用优先规则：</b>需求侧搜索只使用该任务已确认的应用画像，不直接拿产品名称找客户；系统按目标企业类型把结果分为直接需求候选或间接应用链。间接线索与供应工厂都禁止进入 CRM；同行、贸易商、媒体和目录进入排除。{latestRun?.status === '跳过' && latestRun.run_log?.[0] ? <span> 上次结果：{latestRun.run_log[0]}</span> : null}</div>
    <section className="panel lead-task-panel"><div className="panel-title"><div><h2>搜索任务</h2><p>每日自动搜索默认关闭；开启后由服务器按设置时间、串行限速运行。</p></div><button onClick={() => { setEditingTask(null); setOpenTaskForm(true) }}><Plus size={15}/> 新建查询任务</button></div><div className="lead-task-list">{tasks.map(task => <article key={task.id}><div><b>{task.task_name}</b><small>{task.discovery_mode === '供应工厂' ? '供应工厂 · 中国大陆生产主体' : '需求客户 · 下游应用主体'} · {task.product_keywords.slice(0, 2).join(' · ') || '待填写关键词'}</small><span>{task.daily_enabled ? `每日 ${task.daily_run_time.slice(0, 5)}` : '仅手动运行'} · {task.status} · 候选企业目标 {task.max_results}{task.source_urls?.length ? ` · ${task.source_urls.length} 个公开目录来源` : ''}</span></div><div><button className="secondary" disabled={busy || task.status === '暂停'} onClick={() => void runTask(task)}>运行</button><button className="secondary" disabled={busy} onClick={() => { setEditingTask(task); setOpenTaskForm(true) }}>编辑</button><button className="secondary" disabled={busy} onClick={() => void run(() => api.updateLeadSearchTask(task.id, { ...task, source_urls: task.source_urls || [], daily_enabled: !task.daily_enabled, status: task.status, daily_run_time: task.daily_run_time.slice(0, 5) }))}>{task.daily_enabled ? '关闭每日' : '开启每日'}</button><button className="danger" disabled={busy} onClick={() => void removeTask(task)}>删除</button></div></article>)}{!tasks.length && <p className="detail-empty">还没有搜索任务。可创建“需求客户”或“供应工厂”查询任务。</p>}</div></section>
    <section className="panel lead-review-panel"><div className="panel-title"><div><h2>分层线索库</h2><p>直接需求候选才可继续严格核验；间接应用链只用于市场研究，供应工厂不进入客户 CRM。</p></div><span className="muted">{selectedTask ? `${selectedTask.task_name} · ` : ''}上次运行：{latestRun?.started_at ? new Date(latestRun.started_at).toLocaleString('zh-CN') : '尚未运行'}</span></div><div className="lead-tabs"><button className={layer === '直接需求候选' ? 'active' : ''} onClick={() => setLayer('直接需求候选')}>直接需求候选 {direct.length}</button><button className={layer === '间接应用链' ? 'active' : ''} onClick={() => setLayer('间接应用链')}>间接应用链 {indirect.length}</button><button className={layer === '供应工厂候选' ? 'active' : ''} onClick={() => setLayer('供应工厂候选')}>供应工厂 {suppliers.length}</button><button className={layer === '排除' ? 'active' : ''} onClick={() => setLayer('排除')}>排除 {excluded.length}</button><button className={layer === '待判定' ? 'active' : ''} onClick={() => setLayer('待判定')}>待判定 {scopedLeads.filter(lead => layerOf(lead) === '待判定').length}</button></div><div className="lead-filters"><select value={taskFilter} onChange={event => { setTaskFilter(event.target.value); setCountryFilter(''); setTypeFilter(''); setGradeFilter(''); setContactFilter('all') }}><option value="">全部任务</option>{tasks.map(task => <option key={task.id} value={task.id}>{task.task_name}</option>)}</select><select value={countryFilter} onChange={event => setCountryFilter(event.target.value)}><option value="">全部地区</option>{countries.map(country => <option key={country}>{country}</option>)}</select><select value={typeFilter} onChange={event => setTypeFilter(event.target.value)}><option value="">全部企业类型</option>{companyTypes.map(type => <option key={type}>{type}</option>)}</select><select value={gradeFilter} onChange={event => setGradeFilter(event.target.value)}><option value="">全部匹配等级</option><option value="A">A｜直接匹配</option><option value="B">B｜相关待确认</option></select><select value={contactFilter} onChange={event => setContactFilter(event.target.value as typeof contactFilter)}><option value="all">全部联系方式</option><option value="email">有公开邮箱</option><option value="phone">有公开电话</option><option value="both">邮箱和电话齐全</option></select></div><p className="lead-scope-note">当前显示：<b>{selectedTask ? selectedTask.task_name : '全部任务的汇总线索'}</b>{selectedTask ? '。切换任务后，数量、国家筛选与上次运行时间都会同步切换。' : '。请先选择任务，避免将不同产品的结果混在一起判断。'}</p><div className="lead-grid">{shown.map(lead => <LeadVerificationCard key={lead.id} lead={lead} sourceTaskName={lead.task_id ? taskNameById.get(lead.task_id) : undefined} bucket={bucketOf(lead)} busy={busy} review={review} createTask={createTask} convert={convert}/>) }{!shown.length && <p className="detail-empty">该任务在当前分层暂无线索；这不代表其他任务的结果会显示在这里。</p>}</div></section>
    {openTaskForm && <LeadSearchTaskForm products={products} task={editingTask || undefined} close={() => { setOpenTaskForm(false); setEditingTask(null) }} submit={async payload => { if (editingTask) await api.updateLeadSearchTask(editingTask.id, payload); else await api.createLeadSearchTask(payload); setOpenTaskForm(false); setEditingTask(null); await onChanged() }}/>}</section>
}

function LeadVerificationCard({ lead, sourceTaskName, bucket, busy, review, createTask, convert }: { lead: CustomerLead; sourceTaskName?: string; bucket: CustomerLead['verification_bucket']; busy: boolean; review: (lead: CustomerLead, status: CustomerLead['status']) => void; createTask: (lead: CustomerLead) => void; convert: (lead: CustomerLead) => void }) {
  const strict = bucket === '严格客户名单'
  const link = (url: string | null | undefined, label: string) => url ? <a href={url} target="_blank" rel="noreferrer">{label}</a> : '未公开'
  const sources = lead.source_urls?.length ? lead.source_urls : [lead.company_source_url || lead.source_url, lead.contact_source_url, lead.product_evidence_url].filter(Boolean) as string[]
  return <article className={`lead-card verification-card ${lead.suspected_duplicate ? 'duplicate' : ''} ${strict ? 'strict' : ''}`}><header><div><span className="lead-score">{strict ? lead.matching_grade || 'A' : lead.match_score}</span><b>{lead.company_name}</b><small>{sourceTaskName ? `来源任务：${sourceTaskName} · ` : ''}{lead.discovery_mode === '供应工厂' ? '供应工厂候选 · 中国大陆' : '需求客户候选'} · {lead.country || '地区待确认'} · {lead.company_type || lead.source_type}</small></div><span className={`status-pill ${strict ? 'success' : 'warning'}`}>{bucket}{strict && lead.matching_grade ? ` · ${lead.matching_grade}` : ''}</span></header>{lead.suspected_duplicate && <p className="lead-warning">疑似与 CRM 或供应商中心重复，不能新建重复客户。</p>}{!strict && <p className="lead-fail">未通过严格核验：{(lead.missing_requirements || ['等待官网复核']).join('；')}</p>}<dl><div><dt>官网</dt><dd>{link(lead.official_website || lead.official_homepage_url || lead.website, '打开官网')}</dd></div><div><dt>联系人/部门</dt><dd>{lead.public_contact_or_department || lead.public_contact_name || lead.contact_department || '未公开，需首轮确认'}</dd></div><div><dt>邮箱</dt><dd>{lead.public_business_email || '未公开'} {lead.email_domain_note || ''}</dd></div><div><dt>电话</dt><dd>{lead.public_business_phone || '未公开'}</dd></div><div><dt>地址/范围</dt><dd>{lead.official_address || lead.business_scope || '未公开，需首轮确认'}</dd></div><div><dt>产品证据</dt><dd>{lead.product_application_evidence || lead.product_evidence_summary || '无直接官方证据'}</dd></div><div><dt>应用范围</dt><dd>{lead.application_scope || lead.discovered_application_keywords.join('；') || '未公开'}</dd></div><div><dt>潜在匹配点</dt><dd>{lead.potential_fit || lead.possible_need || '未公开，需通过首轮询盘确认。'}</dd></div><div><dt>首联部门</dt><dd>{lead.recommended_contact_department || '待确认'}</dd></div><div><dt>首轮问题</dt><dd>{lead.first_contact_questions || '待确认'}</dd></div><div><dt>核验结论</dt><dd>{lead.verification_conclusion || '历史线索待重新核验。'}</dd></div><div><dt>来源链接</dt><dd className="lead-source-links">{sources.map((url, index) => <a key={url} href={url} target="_blank" rel="noreferrer">来源 {index + 1}</a>)}</dd></div></dl>{lead.confirmation_note && <p className="lead-confirmation">{lead.confirmation_note}</p>}<details><summary>核验依据</summary><ul>{lead.score_reasons.map(reason => <li key={reason}>{reason}</li>)}</ul></details><footer>{bucket !== '排除名单' && <button className="secondary" disabled={busy} onClick={() => review(lead, '保留')}>保留</button>}{bucket !== '排除名单' && <button className="secondary" disabled={busy} onClick={() => review(lead, '已排除')}>排除</button>}{strict && <><button className="secondary" disabled={busy} onClick={() => createTask(lead)}>创建开发任务</button><button className="primary" disabled={busy || lead.status === '已转 CRM'} onClick={() => convert(lead)}>{lead.status === '已转 CRM' ? '已转 CRM' : '载入 CRM'}</button></>}</footer></article>
}

function LeadSearchTaskForm({ products, task, close, submit }: { products: Product[]; task?: LeadSearchTask; close: () => void; submit: (payload: Omit<LeadSearchTask, 'id' | 'user_id' | 'last_run_at' | 'last_run_status' | 'last_error' | 'created_at'>) => Promise<void> }) {
  const csv = (values?: string[]) => values?.join(', ') || ''
  return <Modal title={task ? '编辑查询任务' : '新建查询任务'} close={close}><form onSubmit={async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; const list = (value: string) => value.split(/[,，\n]/).map(item => item.trim()).filter(Boolean); try { await submit({ task_name: values.task_name, discovery_mode: values.discovery_mode as LeadSearchTask['discovery_mode'], product_id: values.product_id || null, product_keywords: list(values.product_keywords || ''), application_keywords: list(values.application_keywords || ''), target_countries: list(values.target_countries || ''), excluded_countries: list(values.excluded_countries || ''), target_company_types: list(values.target_company_types || ''), profile_exclusion_rules: [], source_urls: list(values.source_urls || ''), search_language: values.search_language || 'English', max_results: Math.max(1, Math.min(1000, Number(values.max_results) || 50)), daily_enabled: values.daily_enabled === 'on', daily_run_time: values.daily_run_time || '08:30', status: values.status as LeadSearchTask['status'] }) } catch (error) { alert(error instanceof Error ? error.message : '保存失败') } }}><div className="compliance-note">从产品画像库选择产品后，系统自动带入技术关键词、已确认应用、目标企业类型和排除规则。需求侧只能选“已确认”画像；供应工厂可选草稿，但仍只会生成待核验候选。</div><div className="form-grid"><Field label="任务名称 *" name="task_name" required defaultValue={task?.task_name}/><label>查询方向<select name="discovery_mode" defaultValue={task?.discovery_mode || '需求客户'}><option value="需求客户">需求侧客户（下游应用）</option><option value="供应工厂">国内大陆供应工厂</option></select></label><label className="wide">选择产品画像 *<select name="product_id" required defaultValue={task?.product_id || ''}><option value="" disabled>请选择产品画像</option>{products.map(product => <option key={product.id} value={product.id}>{product.product_code} · {product.product_name} · {product.profile_status || '草稿'}</option>)}</select></label><Field label="搜索语言" name="search_language" defaultValue={task?.search_language || 'English'}/><label className="wide">公开目录来源（可选，每行一个展会 / 协会 / 企业目录 URL）<textarea name="source_urls" defaultValue={task?.source_urls?.join('\n') || ''} placeholder="https://example.org/exhibitors\nhttps://example.org/member-directory"/></label><Field label="目标国家 / 地区（需求侧使用）" name="target_countries" defaultValue={csv(task?.target_countries)}/><Field label="排除国家（逗号分隔）" name="excluded_countries" defaultValue={csv(task?.excluded_countries)}/><label>本次候选企业目标<select name="max_results" defaultValue={String(task?.max_results || 50)}><option value="50">50</option><option value="100">100</option><option value="200">200</option><option value="500">500</option><option value="1000">1000</option></select></label><label>任务状态<select name="status" defaultValue={task?.status || '启用'}><option>启用</option><option>暂停</option></select></label><label><span>每日自动搜索</span><input name="daily_enabled" type="checkbox" defaultChecked={task?.daily_enabled || false}/></label><label>运行时间<input name="daily_run_time" type="time" defaultValue={task?.daily_run_time?.slice(0, 5) || '08:30'}/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">{task ? '保存修改' : '保存查询任务'}</button></div></form></Modal>
}
function SupplierDashboard({ suppliers, rfqs, links, insights, open, onOpenSupplier }: { suppliers: Supplier[]; rfqs: SupplierRfq[]; links: SupplierProjectLink[]; insights: SupplierInsight[]; open: () => void; onOpenSupplier: (supplier: Supplier) => void }) {
  const today = new Date().toISOString().slice(0, 10)
  const pendingReply = suppliers.filter(supplier => ['已询价', '等 TDS', '等报价', '等样品'].includes(supplier.current_status))
  const due = suppliers.filter(supplier => supplier.next_followup_date && supplier.next_followup_date <= today).sort((a, b) => String(a.next_followup_date).localeCompare(String(b.next_followup_date))).slice(0, 5)
  const activeQuotes = insights.reduce((total, item) => total + item.effective_quote_count, 0) || rfqs.filter(rfq => ['供应商已回复', '技术评估'].includes(rfq.status)).length
  return <section className="page supplier-dashboard"><div className="panel-title"><div><p className="eyebrow"><Factory size={13}/> SUPPLY CHAIN / SUPPLIERS</p><h2>供应链与供应商摘要</h2></div><button onClick={open}>进入供应商中心 <ChevronRight size={15}/></button></div><div className="supplier-summary-grid"><Metric label="供应商总数" value={String(suppliers.length)} delta="中国供应商资料库" icon={<Factory/>}/><Metric label="待供应商回复" value={String(pendingReply.length)} delta="询价、资料、报价或样品" icon={<Mail/>}/><Metric label="待获取资料" value={String(suppliers.filter(supplier => ['等 TDS', '等报价', '等样品'].includes(supplier.current_status)).length)} delta="TDS / 样品 / 报价" icon={<Paperclip/>}/><Metric label="有效报价数" value={String(activeQuotes)} delta="供应商已回复或有报价资料" icon={<ClipboardList/>}/><Metric label="本周需跟进" value={String(due.length)} delta="按下次跟进日期提醒" icon={<Bell/>}/></div><section className="panel supplier-todo-card"><PanelTitle title="供应商待办" action="查看供应商" onAction={open}/>{due.length ? due.map(supplier => <button className="reminder-row" key={supplier.id} onClick={() => onOpenSupplier(supplier)}><span className="reminder-dot warning">⚠</span><div><b>{supplier.company_name}</b><span>{supplier.next_action || supplier.current_status}</span></div><time>{String(supplier.next_followup_date).slice(5).replace('-', '/')}</time><ChevronRight size={16}/></button>) : <p className="detail-empty">本周暂无到期供应商跟进。</p>}<small className="supplier-link-count">当前有 {links.length} 条客户项目供应链协同记录</small></section></section>
}
function MobileDashboardFocus({ tasks, reminders, emails, onOpenCRM, onOpenMail, onOpenTasks, onOpenProducts }: { tasks: Task[]; reminders: number; emails: number; onOpenCRM: () => void; onOpenMail: () => void; onOpenTasks: () => void; onOpenProducts: () => void }) {
  return <section className="mobile-dashboard-focus"><div className="mobile-focus-head"><div><p className="eyebrow">TODAY'S FOCUS</p><h2>今天最重要的事</h2></div><button onClick={onOpenTasks}>查看全部 <ChevronRight size={15}/></button></div><div className="mobile-focus-list">{tasks.length ? tasks.slice(0, 3).map((task, index) => <button key={task.id} onClick={onOpenTasks}><span>{index + 1}</span><div><b>{task.title}</b><small>{task.category} · {task.status === 'Completed' ? '已完成' : '待完成'}</small></div><ChevronRight size={16}/></button>) : <button className="mobile-empty-focus" onClick={onOpenTasks}><Plus size={16}/><span>安排今天最重要的一件事</span></button>}</div><div className="mobile-quick-actions"><button onClick={onOpenMail}><Mail size={19}/><span>邮件</span><small>{emails} 待处理</small></button><button onClick={onOpenCRM}><Users size={19}/><span>客户</span><small>{reminders} 待跟进</small></button><button onClick={onOpenTasks}><CircleCheck size={19}/><span>待办</span><small>每日计划</small></button><button onClick={onOpenProducts}><Package size={19}/><span>产品</span><small>资料中心</small></button></div></section>
}
function Metric({label,value,delta,icon}:{label:string;value:string;delta:string;icon:ReactNode}) { return <div className="metric"><div className="metric-icon">{icon}</div><div><span>{label}</span><strong>{value}</strong><small>{label==='活跃客户' && <ArrowUpRight size={13}/>} {delta}</small></div></div> }
function PanelTitle({title,action,onAction}:{title:string;action:string;onAction?:()=>void}) { return <div className="panel-title"><h2>{title}</h2><button onClick={onAction}>{action}<ChevronRight size={15}/></button></div> }
function Activity({icon,title,text,time}:{icon:ReactNode;title:string;text:string;time:string}) { return <div className="activity-row"><div className="activity-icon">{icon}</div><div><b>{title}</b><span>{text}</span></div><time>{time}</time></div> }

const dateLabel = (iso: string) => new Intl.DateTimeFormat('zh-CN', { month: 'long', day: 'numeric', weekday: 'long' }).format(new Date(`${iso}T12:00:00`))
const timeLabel = (value?: string | null) => value ? value.slice(0, 5) : '全天'
const taskPriorityLabel: Record<Task['priority'], string> = { important: '🔥 重要', normal: '⭐ 普通', low: '○ 低' }
const timelineIcon: Record<TimelineEvent['event_type'], ReactNode> = { task: <Check size={15}/>, email: <Mail size={15}/>, crm: <Users size={15}/>, project: <Layers3 size={15}/>, note: <ClipboardList size={15}/> }

function Workbench({ queue, openMail }: { queue: Record<string, unknown> | null; openMail: () => void }) {
  const groups: [string, string, string][] = [['quotation', '待报价', 'Quotation'], ['sample', '待寄样 / 测试', 'Sample'], ['waiting_reply', '待客户回复', 'Reply'], ['overdue_followups', '超期跟进', 'Overdue'], ['new_leads', '待确认新线索', 'Lead']]
  if (!queue) return null
  return <section className="page workbench-page"><div className="page-heading"><div><p className="eyebrow"><Flame size={13}/> ACTION WORKBENCH</p><h1>业务待办工作台</h1><p>按邮件和 CRM 的真实状态汇总；先处理最影响推进的事项。</p></div><button className="secondary" onClick={openMail}>打开邮件中心 <ChevronRight size={15}/></button></div><div className="workbench-grid">{groups.map(([key, label, tone]) => { const items = Array.isArray(queue[key]) ? queue[key] as { id: string; title: string; date?: string }[] : []; return <article className={`workbench-card ${tone.toLowerCase()}`} key={key}><div><b>{label}</b><span>{items.length}</span></div>{items.length ? items.slice(0, 4).map(item => <p key={item.id}><strong>{item.title}</strong><small>{item.date ? String(item.date).slice(0, 10) : '待确认日期'}</small></p>) : <em>暂无</em>}</article> })}</div></section>
}

function DailyFocus({ tasks, customers, projects, products, focusDate, today, dailyLog, setFocusDate, create, complete, review }: { tasks: Task[]; customers: Customer[]; projects: Project[]; products: Product[]; focusDate: string; today: string; dailyLog: DailyLog | null; setFocusDate: (date: string) => void; create: () => void; complete: (task: Task) => Promise<void>; review: () => void }) {
  const dailyTasks = tasks.filter(task => task.task_date === focusDate).sort((a, b) => `${a.start_time || ''}${a.title}`.localeCompare(`${b.start_time || ''}${b.title}`))
  const completed = dailyTasks.filter(task => task.status === 'Completed').length
  const rate = dailyTasks.length ? Math.round(completed / dailyTasks.length * 100) : 0
  const consecutive = (() => { const done = new Set(tasks.filter(task => task.status === 'Completed').map(task => task.task_date)); let days = 0; const cursor = new Date(`${focusDate}T12:00:00`); while (done.has(cursor.toISOString().slice(0, 10))) { days += 1; cursor.setDate(cursor.getDate() - 1) } return days })()
  const relationName = (task: Task) => customers.find(customer => customer.id === task.customer_id)?.company_name || products.find(product => product.id === task.product_id)?.product_code || projects.find(project => project.id === task.project_id)?.project_name || task.category
  return <section className="page daily-focus-page"><div className="page-heading"><div><p className="eyebrow"><CalendarDays size={13}/> DAILY FOCUS</p><h1>每日计划</h1><p>{dateLabel(focusDate)} · 把客户推进、个人任务与每天的工作记录放在同一处。</p></div><div className="date-actions"><input aria-label="选择任务日期" type="date" value={focusDate} onChange={event => setFocusDate(event.target.value)}/><button className="primary" onClick={create}><Plus size={17}/> 新建任务</button></div></div>
    <div className="focus-stats"><FocusStat icon={<CircleCheck/>} label="今日完成" value={`${completed} / ${dailyTasks.length}`} detail="已完成任务"/><FocusStat icon={<Sparkles/>} label="完成率" value={`${rate}%`} detail="聚焦最重要的行动"/><FocusStat icon={<Flame/>} label="连续打卡" value={`${consecutive} 天`} detail="完成任务自动计入"/></div>
    <div className="focus-layout"><section className="panel daily-task-panel"><PanelTitle title="今日任务" action="新建任务" onAction={create}/>{dailyTasks.length ? <div className="daily-task-list">{dailyTasks.map(task => <button className={`daily-task ${task.status === 'Completed' ? 'completed' : ''}`} key={task.id} onClick={() => void complete(task)}><span className="daily-check">{task.status === 'Completed' ? <Check size={15}/> : <Circle size={16}/>}</span><div><b>{task.title}</b><span>{taskPriorityLabel[task.priority]} · {task.category} · {relationName(task)}</span></div><time>{task.start_time ? `${timeLabel(task.start_time)}${task.end_time ? `-${timeLabel(task.end_time)}` : ''}` : '全天'}</time></button>)}</div> : <div className="focus-empty"><ClipboardList size={24}/><b>今天还没有计划</b><span>先添加一件可以推动业务的关键任务。</span><button className="primary" onClick={create}><Plus size={15}/> 新建任务</button></div>}</section>
      <section className="panel daily-review-card"><PanelTitle title="今日复盘" action={dailyLog ? '编辑复盘' : '开始复盘'} onAction={review}/>{dailyLog ? <div className="review-summary"><div><span>今日完成</span><b>{dailyLog.summary || '尚未填写'}</b></div><div><span>遇到问题</span><b>{dailyLog.problem || '尚未填写'}</b></div><div><span>明日重点</span><b>{dailyLog.tomorrow_plan || '尚未填写'}</b></div><div className="review-rating"><span>工作评分</span><b>{'★'.repeat(dailyLog.rating || 0)}{'☆'.repeat(5 - (dailyLog.rating || 0))}</b></div></div> : <div className="focus-empty review-empty"><Clock3 size={24}/><b>为今天留下一条记录</b><span>记录完成、问题与明日重点，工作轨迹才会变得可复盘。</span><button className="secondary" onClick={review}>填写今日复盘</button></div>}</section></div>
  </section>
}
function FocusStat({ icon, label, value, detail }: { icon: ReactNode; label: string; value: string; detail: string }) { return <article className="focus-stat"><span>{icon}</span><div><small>{label}</small><b>{value}</b><em>{detail}</em></div></article> }

function CalendarView({ tasks, events, customers, focusDate, setFocusDate, onOpenTasks }: { tasks: Task[]; events: TimelineEvent[]; customers: Customer[]; focusDate: string; setFocusDate: (date: string) => void; onOpenTasks: () => void }) {
  const [month, setMonth] = useState(() => focusDate.slice(0, 7))
  useEffect(() => setMonth(focusDate.slice(0, 7)), [focusDate])
  const first = new Date(`${month}-01T12:00:00`); const start = new Date(first); start.setDate(1 - ((first.getDay() + 6) % 7))
  const dates = Array.from({ length: 42 }, (_, index) => { const value = new Date(start); value.setDate(start.getDate() + index); return value.toISOString().slice(0, 10) })
  const selectedTasks = tasks.filter(task => task.task_date === focusDate).sort((a, b) => `${a.start_time || ''}${a.title}`.localeCompare(`${b.start_time || ''}${b.title}`))
  const selectedEvents = events.filter(event => event.event_date === focusDate).sort((a, b) => `${a.event_time || ''}${a.title}`.localeCompare(`${b.event_time || ''}${b.title}`))
  const moveMonth = (offset: number) => { const next = new Date(`${month}-01T12:00:00`); next.setMonth(next.getMonth() + offset); setMonth(next.toISOString().slice(0, 7)) }
  const customerName = (event: TimelineEvent) => customers.find(customer => customer.id === event.customer_id)?.company_name
  return <section className="page calendar-page"><div className="page-heading"><div><p className="eyebrow"><CalendarDays size={13}/> WORK CALENDAR</p><h1>工作日历</h1><p>查看任务、邮件和 CRM 推进在每一天留下的工作轨迹。</p></div><button className="primary" onClick={onOpenTasks}>进入每日计划 <ChevronRight size={16}/></button></div>
    <div className="calendar-layout"><section className="panel calendar-panel"><div className="calendar-head"><button onClick={() => moveMonth(-1)} aria-label="上个月"><ChevronLeft size={18}/></button><h2>{new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long' }).format(new Date(`${month}-01T12:00:00`))}</h2><button onClick={() => moveMonth(1)} aria-label="下个月"><ChevronRight size={18}/></button></div><div className="calendar-weekdays">{['周一', '周二', '周三', '周四', '周五', '周六', '周日'].map(day => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{dates.map(day => { const dayTasks = tasks.filter(task => task.task_date === day); const isCurrentMonth = day.slice(0, 7) === month; const completed = dayTasks.filter(task => task.status === 'Completed').length; return <button key={day} className={`calendar-day ${isCurrentMonth ? '' : 'muted'} ${day === focusDate ? 'selected' : ''}`} onClick={() => setFocusDate(day)}><time>{Number(day.slice(-2))}</time>{dayTasks.slice(0, 3).map(task => <span className={task.status === 'Completed' ? 'done' : task.priority} key={task.id}>{task.status === 'Completed' ? '✓ ' : ''}{task.title}</span>)}{dayTasks.length > 3 && <small>+{dayTasks.length - 3} 项任务</small>}{dayTasks.length > 0 && <em>{completed}/{dayTasks.length}</em>}</button> })}</div></section>
      <aside className="panel timeline-panel"><div className="timeline-panel-head"><div><p className="eyebrow">DAILY TIMELINE</p><h2>{dateLabel(focusDate)}</h2></div><button className="secondary" onClick={onOpenTasks}>编辑任务</button></div><div className="daily-timeline">{[...selectedTasks.map(task => ({ id: `task-${task.id}`, time: task.status === 'Completed' && task.completed_at ? new Date(task.completed_at).toTimeString().slice(0, 5) : task.start_time?.slice(0, 5), title: task.status === 'Completed' ? `完成：${task.title}` : `计划：${task.title}`, type: 'task' as const, source: task.category, customer: customers.find(customer => customer.id === task.customer_id)?.company_name })), ...selectedEvents.map(event => ({ id: event.id, time: event.event_time?.slice(0, 5), title: event.title, type: event.event_type, source: event.source, customer: customerName(event) }))].sort((a, b) => `${a.time || ''}${a.title}`.localeCompare(`${b.time || ''}${b.title}`)).map(item => <div className="timeline-event" key={item.id}><time>{item.time || '全天'}</time><span>{timelineIcon[item.type]}</span><div><b>{item.title}</b><small>{item.customer ? `${item.source} · ${item.customer}` : item.source}</small></div></div>)}</div>{!selectedTasks.length && !selectedEvents.length && <div className="focus-empty timeline-empty"><CalendarDays size={24}/><b>这一天还没有工作记录</b><span>选中日期后，可以进入每日计划添加任务。</span></div>}</aside></div>
  </section>
}

const countryFlags: Record<string, string> = { India: '🇮🇳', Philippines: '🇵🇭', Netherlands: '🇳🇱', Thailand: '🇹🇭' }
function CustomerTags({ tags = [] }: { tags?: string[] }) { return tags.length ? <div className="customer-tags">{tags.map(tag => <span key={tag}>{tag}</span>)}</div> : null }
function isCustomerIncomplete(customer: Customer) {
  return [customer.country, customer.contact_person, customer.product_interest, customer.customer_need, customer.next_action?.[0]].some(value => !value || value === '待确认')
}
function CustomerCompleteness({ customer }: { customer: Customer }) {
  const filled = [customer.country, customer.contact_person, customer.product_interest, customer.customer_need, customer.next_action?.[0]].filter(value => value && value !== '待确认').length
  return <div className="crm-completeness" title="国家、联系人、产品、需求、下一步行动"><span>资料完整度</span><b>{filled}/5</b><i><em style={{ width: `${filled * 20}%` }}/></i></div>
}
function ValueStars({ value = 3 }: { value?: number }) { return <span className="value-stars" title={`客户价值 ${value}/5`}>{Array.from({ length: 5 }, (_, index) => <Star key={index} size={12} fill={index < value ? 'currentColor' : 'none'}/>)}</span> }

function CRM({customers,allCustomers,projects,members,query,setQuery,filter,setFilter,open,create,addFollowup}:{customers:Customer[];allCustomers:Customer[];projects:Project[];members:WorkspaceMember[];query:string;setQuery:(v:string)=>void;filter:CrmFilter;setFilter:(value:CrmFilter)=>void;open:(c:Customer)=>void;create:()=>void;addFollowup:(customer:Customer)=>void}) {
  const pending = allCustomers.filter(customer => customer.customer_stage !== 'Maintain Relationship' && customer.customer_stage !== 'Won').length
  const quoted = allCustomers.filter(customer => customer.customer_stage === 'Quotation' || customer.customer_stage === 'Quoted').length
  const incomplete = allCustomers.filter(isCustomerIncomplete).length
  const overdue = allCustomers.filter(customer => customer.next_followup_date && customer.next_followup_date < new Date().toISOString().slice(0, 10)).length
  const ownerName = (customer: Customer) => members.find(member => member.user_id === customer.user_id)?.display_name || '共享客户'
  const countries = Object.entries(customers.reduce<Record<string, Customer[]>>((groups, customer) => { (groups[customer.country] ||= []).push(customer); return groups }, {}))
  return <section className="page crm"><div className="page-heading"><div><p className="eyebrow">CUSTOMER INTELLIGENCE LAYER</p><h1>外贸 CRM</h1><p>让每位客户的背景、需求、商业价值与下一步行动一目了然。</p></div><button className="primary" onClick={create}><Plus size={17}/> 新建客户</button></div><div className="crm-kpis"><span><b>{allCustomers.length}</b> 客户</span><span><b>{projects.length}</b> 进行中项目</span><span><b>{pending}</b> 待跟进</span><span><b>{quoted}</b> 报价中</span><span><b>{incomplete}</b> 待补资料</span></div>
    <section className="global-map"><div className="panel-title"><div><p className="eyebrow"><Globe2 size={13}/> GLOBAL CUSTOMERS</p><h2>全球客户分布</h2></div><span>{countries.length} 个国家 / 地区</span></div><div className="country-grid">{countries.map(([country, members]) => <div className="country-card" key={country}><b>{countryFlags[country] ?? '🌍'} {country}</b><small>{members.length} customers</small><div>{members.map(member => <button key={member.id} onClick={() => open(member)}>{member.company_name}</button>)}</div></div>)}</div></section>
    <div className="table-panel crm-card-panel"><div className="table-tools"><label><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索客户、国家、产品、应用、标签或关键词" /></label><div className="crm-filters" aria-label="CRM 筛选"><button className={filter === 'all' ? 'active' : ''} onClick={() => setFilter('all')}>全部</button><button className={filter === 'incomplete' ? 'active' : ''} onClick={() => setFilter('incomplete')}>待补资料 {incomplete}</button><button className={filter === 'overdue' ? 'active' : ''} onClick={() => setFilter('overdue')}>逾期跟进 {overdue}</button></div><span className="intelligence-search">支持：客户 · 产品 · 标签 · 应用</span></div><div className="crm-cards intelligence-cards">{customers.map(customer => { const project = projects.find(item => item.customer_id === customer.id); return <article className="crm-card intelligence-card" key={customer.id}><div className="crm-card-top"><div className="customer-cell"><div className="company-avatar">{countryFlags[customer.country] ?? customer.company_name[0]}</div><div><b>{customer.company_name}</b><span>{customer.country} · {customer.contact_person}</span></div></div><ValueStars value={customer.customer_value}/></div><div className="crm-owner"><span>归属 · {ownerName(customer)}</span><CustomerCompleteness customer={customer}/></div><CustomerTags tags={customer.customer_tags}/><p className="customer-summary">{customer.customer_summary}</p><div className="crm-card-status"><Stage stage={customer.customer_stage}/><span className={`status-label ${customer.status_tone ?? ''}`}>{customer.status_label ?? '跟进中'}</span></div><dl><div><dt>正在开发</dt><dd>{customer.application ?? project?.application ?? '待确认应用'}</dd></div><div><dt>关注产品</dt><dd>{customer.product_interest}</dd></div><div><dt>下一步</dt><dd>{customer.next_action?.[0] ?? customer.status_label ?? '安排下一次客户联系'}</dd></div><div><dt>最后沟通</dt><dd>{customer.last_contact_date}</dd></div></dl><div className="crm-card-actions"><button className="primary" onClick={() => open(customer)}>客户 360 <ChevronRight size={14}/></button><button onClick={() => addFollowup(customer)}>添加跟进</button></div></article> })}</div>{!customers.length && <div className="empty">没有符合当前搜索的客户。</div>}</div></section> }
function stageClass(stage: CustomerStage) { return stage.toLowerCase().replace(/\s/g, '-') }
function Stage({stage}:{stage:CustomerStage}) { return <span className={`stage ${stageClass(stage)}`}>{stageLabels[stage]}</span> }
function Priority({ value }: { value?: Customer['priority'] }) { return value ? <span className={`priority ${value.toLowerCase().replace(/\s/g, '-')}`}>{value}</span> : <span className="priority medium">MEDIUM</span> }

function Products({ products, customers, relations, projects, followups, emails, tasks, timelineEvents, create, edit, history }: { products: Product[]; customers: Customer[]; relations: ProductCustomerRelation[]; projects: Project[]; followups: Followup[]; emails: MailEmail[]; tasks: Task[]; timelineEvents: TimelineEvent[]; create: () => void; edit: (product: Product) => void; history: (product: Product) => void }) {
  const [query, setQuery] = useState('')
  const [status, setStatus] = useState<'全部' | ProductProfileStatus>('全部')
  const visible = products.filter(product => (status === '全部' || (product.profile_status || '草稿') === status) && `${product.product_name} ${product.product_code} ${product.category} ${(product.technical_keywords || []).join(' ')}`.toLowerCase().includes(query.toLowerCase()))
  const confirmed = products.filter(product => product.profile_status === '已确认').length
  const actualCustomers = customers.filter(customer => customer.customer_tags?.includes('实际推进客户'))
  const historicalCustomers = customers.filter(customer => customer.customer_tags?.includes('历史项目'))
  return <section className="page products"><div className="page-heading"><div><p className="eyebrow">PRODUCT INTELLIGENCE / PROFILE LIBRARY</p><h1>产品画像库</h1><p>产品资料、技术边界与实际项目在一处维护。这里只统计明确标注的实际推进客户与历史项目，不混入待确认线索。</p></div><button className="primary" onClick={create}><Plus size={17}/> 添加产品画像</button></div><div className="metrics product-profile-metrics"><Metric icon={<Package/>} label="产品总数" value={String(products.length)} delta="可复用产品资料"/><Metric icon={<Users/>} label="实际推进客户" value={String(actualCustomers.length)} delta="仅计入明确沟通过的客户"/><Metric icon={<Clock3/>} label="历史项目" value={String(historicalCustomers.length)} delta="需重新确认后再激活"/><Metric icon={<CircleCheck/>} label="已确认画像" value={String(confirmed)} delta="可用于需求侧搜索"/></div><div className="product-toolbar"><label><Search size={17}/><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索产品、编号、技术关键词" /></label><select value={status} onChange={event => setStatus(event.target.value as typeof status)}><option>全部</option><option>已确认</option><option>草稿</option></select></div><div className="products-grid">{visible.map(product => <ProductCard key={product.id} product={product} customers={customers} relations={relations} projects={projects} followups={followups} emails={emails} tasks={tasks} timelineEvents={timelineEvents} edit={edit} history={history}/>)}</div>{!visible.length && <div className="empty">没有符合条件的产品画像。</div>}</section>
}
function ProductCard({ product, customers, relations, edit, history }: { product: Product; customers: Customer[]; relations: ProductCustomerRelation[]; projects: Project[]; followups: Followup[]; emails: MailEmail[]; tasks: Task[]; timelineEvents: TimelineEvent[]; edit: (product: Product) => void; history: (product: Product) => void }) { const confirmed = product.profile_status === '已确认'; const customerIds = new Set(relations.filter(relation => relation.product_id === product.id).map(relation => relation.customer_id)); const linkedCustomers = customers.filter(customer => customerIds.has(customer.id)); const actualCustomers = linkedCustomers.filter(customer => customer.customer_tags?.includes('实际推进客户')); const historicalCustomers = linkedCustomers.filter(customer => customer.customer_tags?.includes('历史项目')); return <article className="product-card product-profile-card" onClick={() => edit(product)}><div className="product-art"><span>{product.product_code.slice(0, 2)}</span><div className="product-shape one"/><div className="product-shape two"/></div><div className="product-body"><div className="product-card-status"><span className="category">{product.category}</span><span className={`status-pill ${confirmed ? 'success' : 'warning'}`}>{product.profile_status || '草稿'}</span></div><h2>{product.product_name}</h2><code>{product.product_code}</code><p>{product.description}</p><div className="product-profile-tags">{(product.confirmed_applications || []).slice(0, 2).map(item => <span key={item}>{item}</span>)}{!(product.confirmed_applications || []).length && <span>待补应用画像</span>}</div><div className="product-profile-summary"><span>技术词 {(product.technical_keywords || []).length}</span><span>目标行业 {(product.target_industries || []).length}</span><span>证据 {(product.evidence_urls || []).length}</span></div><div className="product-customer-summary"><b>实际推进 {actualCustomers.length}</b><span>{actualCustomers.length ? actualCustomers.map(customer => customer.company_name).join(' · ') : '暂无明确标注的实际推进客户'}</span>{historicalCustomers.length > 0 && <small>历史项目：{historicalCustomers.map(customer => customer.company_name).join(' · ')}</small>}</div><div className="product-card-actions"><button className="product-history-button" type="button" onClick={event => { event.stopPropagation(); history(product) }}><Clock3 size={14}/> 客户历史</button><span>{confirmed ? '编辑产品画像' : '完善并确认画像'}<ChevronRight size={16}/></span></div></div></article> }

function RelationshipMatrix({ products, customers, projects, relations, openCustomer, linkCustomer }: { products: Product[]; customers: Customer[]; projects: Project[]; relations: ProductCustomerRelation[]; openCustomer: (customer: Customer) => void; linkCustomer: (product: Product) => void }) {
  return <section className="page relationship-page"><div className="page-heading"><div><p className="eyebrow"><Network size={13}/> PRODUCT RELATIONSHIP</p><h1>产品 - 客户关系</h1><p>从产品视角识别正在推进的客户、应用和项目；可直接建立新的客户关联。</p></div></div><div className="relationship-grid">{products.map(product => {
    const linkedIds = new Set([
      ...relations.filter(relation => relation.product_id === product.id).map(relation => relation.customer_id),
      ...customers.filter(customer => customer.product_interest === product.product_code || projects.some(project => project.customer_id === customer.id && project.product_id === product.id)).map(customer => customer.id),
    ])
    const linkedCustomers = customers.filter(customer => linkedIds.has(customer.id))
    return <article className="relationship-card" key={product.id}><div className="relationship-head"><div><code>{product.product_code}</code><h2>{product.product_name}</h2></div><span>{linkedCustomers.length} 客户</span></div><p>{product.application || product.category}</p><div className="relationship-customers">{linkedCustomers.length ? linkedCustomers.map(customer => <button className="relationship-customer-row" type="button" key={customer.id} onClick={() => openCustomer(customer)} title={`打开 ${customer.company_name} 客户 360`}><span>{countryFlags[customer.country] ?? '🌍'}</span><div><b>{customer.company_name}</b><small>{customer.country} · {customer.application || '应用待确认'} · 客户 360</small></div><ChevronRight size={15}/></button>) : <span className="detail-empty">尚未关联客户，请点击下方按钮添加。</span>}<button type="button" className="relationship-add" onClick={() => linkCustomer(product)}><Plus size={14}/> 关联客户</button></div></article>
  })}</div></section>
}

function ProjectManagement({ projects, customers, members, products, quotes, suppliers, supplierLinks, openCustomer, openProject }: { projects: Project[]; customers: Customer[]; members: WorkspaceMember[]; products: Product[]; quotes: Quote[]; followups: Followup[]; emails: MailEmail[]; tasks: Task[]; timelineEvents: TimelineEvent[]; suppliers: Supplier[]; supplierLinks: SupplierProjectLink[]; supplierRfqs: SupplierRfq[]; openCustomer: (customer: Customer) => void; openProject: (project: Project) => void }) {
  const activeProjects = projects.filter(project => !['Won', 'Lost'].includes(project.stage)).length
  const quotationProjects = projects.filter(project => project.stage === 'Quotation' || project.stage === 'Quoted').length
  const technicalProjects = projects.filter(project => project.stage.includes('Technical')).length
  return <section className="page projects-page"><div className="page-heading"><div><p className="eyebrow">CUSTOMER OPPORTUNITY BOARD</p><h1>商机项目推进</h1><p>一张卡是一条“客户 × 产品 × 应用”的具体商机，用于推进技术验证、样品、报价、供应协同与下一步行动。</p></div></div>
    <div className="project-kpis"><span><b>{projects.length}</b> 商机总数</span><span><b>{activeProjects}</b> 推进中</span><span><b>{technicalProjects}</b> 技术 / 样品验证</span><span><b>{quotationProjects}</b> 报价沟通</span></div>
    <div className="project-board-guide"><Layers3 size={16}/><div><b>这里管理一次具体机会，不管理产品档案。</b><span>产品资料、技术边界、适用场景和跨客户历史请在“产品中心”维护；这里仅回答这位客户的这单业务下一步怎么推进。</span></div></div>
    <div className="project-board">{projects.map(project => {
      const customer = customers.find(item => item.id === project.customer_id)
      const product = products.find(item => item.id === project.product_id || item.product_code === project.product_code)
      const quote = quotes.find(item => item.customer_id === project.customer_id && (!product || item.product_id === product.id || item.product_code === product.product_code))
      const projectSuppliers = supplierLinks.filter(link => link.project_id === project.id)
      return <article className="project-card project-war-room-entry" key={project.id} onClick={() => openProject(project)}><div className="project-card-top"><div><span className="project-label">客户商机 · {customer?.company_name ?? '客户待关联'}</span><h2>{project.project_name}</h2></div><Stage stage={project.stage}/></div><dl><div><dt>本次产品</dt><dd>{product?.product_code ?? project.product_code ?? '待确认'}</dd></div><div><dt>本次应用</dt><dd>{project.application}</dd></div><div><dt>当前推进</dt><dd>{project.notes || '安排下一步推进'}</dd></div><div><dt>报价状态</dt><dd>{quote ? `${quote.currency} ${quote.amount?.toLocaleString() ?? '待定'} · ${quote.status}` : '尚未创建报价'}</dd></div></dl><div className="project-supply-block"><b><Factory size={14}/> 供应链协同 · {projectSuppliers.length} 家</b>{projectSuppliers.length ? projectSuppliers.slice(0, 2).map(link => <span key={link.id}>{suppliers.find(supplier => supplier.id === link.supplier_id)?.company_name || '供应商待确认'} · {link.match_status}</span>) : <span>尚未关联供应商</span>}</div><div className="project-card-foot"><span>{customer?.next_followup_date ? `下次跟进 ${customer.next_followup_date}` : '待安排跟进'}</span><button type="button" onClick={event => { event.stopPropagation(); openProject(project) }}>进入作战室 <ChevronRight size={14}/></button>{customer && <button type="button" onClick={event => { event.stopPropagation(); openCustomer(customer) }}>客户 360 <ChevronRight size={14}/></button>}</div></article>
    })}</div>{!projects.length && <div className="empty">还没有项目，请先在 CRM 中创建客户和项目。</div>}</section>
}

type ProjectWarRoomEvent = { id: string; date: string; source: string; title: string; detail?: string; email?: MailEmail }
function ProjectWarRoom({ project, customers, members, products, quotes, followups, emails, tasks, timelineEvents, suppliers, supplierLinks, supplierRfqs, close, openCustomer, openEmail }: { project: Project; customers: Customer[]; members: WorkspaceMember[]; products: Product[]; quotes: Quote[]; followups: Followup[]; emails: MailEmail[]; tasks: Task[]; timelineEvents: TimelineEvent[]; suppliers: Supplier[]; supplierLinks: SupplierProjectLink[]; supplierRfqs: SupplierRfq[]; close: () => void; openCustomer: (customer: Customer) => void; openEmail: (email: MailEmail) => void }) {
  const customer = customers.find(item => item.id === project.customer_id)
  const product = products.find(item => item.id === project.product_id || item.product_code === project.product_code)
  const owner = customer ? members.find(member => member.user_id === customer.user_id)?.display_name || '共享客户' : '待关联客户'
  const productMatches = (productId?: string | null, productCode?: string | null) => Boolean(product && (productId === product.id || productCode === product.product_code))
  const projectQuotes = quotes.filter(quote => quote.customer_id === project.customer_id && productMatches(quote.product_id, quote.product_code))
  const projectEmails = emails.filter(email => email.project_id === project.id || (email.customer_id === project.customer_id && productMatches(email.product_id, null))).sort((left, right) => right.received_at.localeCompare(left.received_at))
  const customerFollowups = followups.filter(followup => followup.customer_id === project.customer_id).sort((left, right) => right.date.localeCompare(left.date))
  const projectTasks = tasks.filter(task => task.project_id === project.id || (task.customer_id === project.customer_id && task.product_id === product?.id)).sort((left, right) => right.task_date.localeCompare(left.task_date))
  const projectEvents = timelineEvents.filter(event => event.project_id === project.id || (event.customer_id === project.customer_id && event.product_id === product?.id))
  const projectSupplierLinks = supplierLinks.filter(link => link.project_id === project.id)
  const projectRfqs = supplierRfqs.filter(rfq => rfq.project_id === project.id)
  const activity: ProjectWarRoomEvent[] = []
  customerFollowups.forEach(followup => activity.push({ id: `followup-${followup.id}`, date: followup.date, source: '客户级跟进', title: followup.content, detail: followup.next_action ? `下一步：${followup.next_action}` : undefined }))
  projectEmails.forEach(email => activity.push({ id: `email-${email.id}`, date: email.received_at.slice(0, 10), source: `邮件 · ${mailCategoryLabels[email.category]}`, title: email.subject || '邮件沟通', detail: email.content_preview, email }))
  projectQuotes.forEach(quote => quote.created_at && activity.push({ id: `quote-${quote.id}`, date: quote.created_at.slice(0, 10), source: '报价', title: `${quote.currency} ${quote.amount?.toLocaleString() || '待定'} · ${quote.status}`, detail: `${quote.quantity} · ${quote.trade_term || '贸易条款待确认'}` }))
  projectTasks.forEach(task => activity.push({ id: `task-${task.id}`, date: task.task_date, source: task.status === 'Completed' ? '已完成任务' : '待办任务', title: task.title, detail: task.description }))
  projectEvents.forEach(event => activity.push({ id: `timeline-${event.id}`, date: event.event_date, source: event.source || '系统记录', title: event.title }))
  projectSupplierLinks.forEach(link => { const supplier = suppliers.find(item => item.id === link.supplier_id); link.created_at && activity.push({ id: `supplier-${link.id}`, date: link.created_at.slice(0, 10), source: '供应链协同', title: `${supplier?.company_name || '供应商待确认'} · ${link.match_status}`, detail: [link.sample_status, link.quote_status, link.next_action].filter(Boolean).join(' · ') || undefined }) })
  activity.sort((left, right) => right.date.localeCompare(left.date))
  const sampleSignals = [customer?.sample_status, ...projectEmails.filter(email => email.category === 'sample').map(email => `客户邮件：${email.subject || '样品相关'}`), ...projectSupplierLinks.map(link => link.sample_status).filter(Boolean)].filter(Boolean) as string[]
  const today = new Date().toISOString().slice(0, 10)
  const lastContactDays = customer?.last_contact_date ? Math.floor((Date.parse(`${today}T12:00:00`) - Date.parse(`${customer.last_contact_date}T12:00:00`)) / 86400000) : null
  const sampleStage = ['Sample', 'Sample Payment', 'Sample Payment Pending', 'Technical Testing', 'Technical Confirmation'].includes(project.stage)
  const risks = [
    !customer ? '项目尚未关联客户，无法确认联系人、跟进日和客户需求。' : null,
    customer && !customer.next_followup_date ? '未设置下一次跟进日期。' : null,
    lastContactDays !== null && lastContactDays > 7 ? `距上次客户沟通已 ${lastContactDays} 天。` : null,
    ['Quotation', 'Quoted'].includes(project.stage) && !projectQuotes.length ? '当前处于报价阶段，但没有关联到本产品的报价记录。' : null,
    sampleStage && !sampleSignals.length ? '当前处于样品或测试阶段，但未记录样品状态。' : null,
    ...projectSupplierLinks.map(link => link.current_risk).filter(Boolean),
  ].filter(Boolean) as string[]
  return <div className="drawer-layer"><aside className="drawer project-war-room"><button className="close" onClick={close}><X size={20}/></button><div className="war-room-head"><p className="eyebrow"><Layers3 size={13}/> OPPORTUNITY WAR ROOM</p><div><span>{customer?.company_name || '客户待关联'}</span><Stage stage={project.stage}/></div><h2>{project.project_name}</h2><p>这是一条具体商机；全部内容只来自已关联的客户、项目、邮件、任务、报价与供应链记录。</p></div><div className="war-room-command"><div><span>当前阶段</span><b>{stageLabels[project.stage]}</b></div><div><span>负责人</span><b>{owner} <small>（继承客户归属）</small></b></div><div><span>下一步</span><b>{customer?.next_action?.[0] || project.notes || '待补充'}</b></div><div><span>截止日</span><b>{customer?.next_followup_date || '未设置'}</b></div></div><div className="war-room-actions">{customer && <button className="primary" onClick={() => openCustomer(customer)}>打开客户 360 <ChevronRight size={15}/></button>}<button className="secondary" onClick={close}>返回项目推进</button></div><section className="war-room-section"><h3>客户需求与本次应用</h3><div className="war-room-grid"><div><span>客户需求</span><b>{customer?.customer_need || customer?.requirements?.join('；') || '尚未记录'}</b></div><div><span>本次应用</span><b>{project.application || customer?.application || '待确认'}</b></div><div><span>关联产品</span><b>{product ? `${product.product_code} · ${product.product_name}` : project.product_code || '待确认'}</b></div><div><span>项目说明</span><b>{project.notes || '尚未记录'}</b></div></div></section><section className="war-room-section"><h3>报价、样品、测试与付款</h3><div className="war-room-status-grid"><div><span>报价</span><b>{projectQuotes.length ? projectQuotes.map(quote => `${quote.currency} ${quote.amount?.toLocaleString() || '待定'} · ${quote.status}`).join('；') : '未关联报价'}</b></div><div><span>样品 / 测试</span><b>{sampleSignals.length ? sampleSignals.join('；') : '尚未记录'}</b></div><div><span>付款相关邮件</span><b>{projectEmails.filter(email => email.category === 'payment').length ? `${projectEmails.filter(email => email.category === 'payment').length} 封已关联` : '未关联付款邮件'}</b></div><div><span>供应商 RFQ</span><b>{projectRfqs.length ? projectRfqs.map(rfq => `${rfq.rfq_number} · ${rfq.status}`).join('；') : '未创建'}</b></div></div></section><section className="war-room-section"><h3>供应协同</h3>{projectSupplierLinks.length ? <div className="war-room-supplier-list">{projectSupplierLinks.map(link => { const supplier = suppliers.find(item => item.id === link.supplier_id); return <article key={link.id}><b>{supplier?.company_name || '供应商待确认'} · {link.match_status}</b><span>{[link.reference_product, link.quote_status, link.sample_status].filter(Boolean).join(' · ') || '报价、样品状态待补'}</span><small>{link.next_action || link.technical_match_notes || '暂无下一步记录'}</small></article> })}</div> : <p className="detail-empty">尚未关联供应商；如需国内供货、询价或送样，可在供应商中心建立协同。</p>}</section><section className="war-room-section"><h3>风险提示</h3>{risks.length ? <div className="war-room-risks">{risks.map(risk => <p key={risk}>⚠ {risk}</p>)}</div> : <p className="war-room-ok">当前已关联记录中未触发规则风险；这不等于客户已经确认采购或测试通过。</p>}</section><section className="war-room-section"><h3>业务时间线</h3><p className="war-room-caption">客户级跟进未必专属于本项目，已单独标注；其余内容仅取项目或客户+产品的关联记录。</p>{activity.length ? <div className="war-room-timeline">{activity.map(item => <article key={item.id}><time>{item.date}</time><div><small>{item.source}</small><b>{item.title}</b>{item.detail && <p>{item.detail}</p>}{item.email && <button type="button" onClick={() => openEmail(item.email!)}>打开邮件 <ChevronRight size={14}/></button>}</div></article>)}</div> : <p className="detail-empty">尚无已关联的邮件、跟进、报价、任务或供应协同记录。</p>}</section></aside></div>
}

function SupplierCenter({ suppliers, links, rfqs, insights, open, create, link, createRfq }: { suppliers: Supplier[]; links: SupplierProjectLink[]; rfqs: SupplierRfq[]; insights: SupplierInsight[]; open: (supplier: Supplier) => void; create: () => void; link: () => void; createRfq: () => void }) {
  const [query, setQuery] = useState('')
  const [status, setStatus] = useState('全部')
  const [exportFilter, setExportFilter] = useState('全部')
  const [materialFilter, setMaterialFilter] = useState('全部')
  const today = new Date().toISOString().slice(0, 10)
  const visible = suppliers.filter(supplier => {
    const search = `${supplier.company_name} ${supplier.english_name || ''} ${supplier.province || ''} ${supplier.city || ''} ${supplier.main_phone || ''} ${supplier.main_email || ''} ${supplier.wechat || ''} ${(supplier.product_keywords || []).join(' ')} ${(supplier.supplier_tags || []).join(' ')}`.toLowerCase().includes(query.toLowerCase())
    const insight = insights.find(item => item.supplier_id === supplier.id)
    const materialsMatch = materialFilter === '全部' || (materialFilter === '有 TDS' && Boolean(insight?.tds_count)) || (materialFilter === '可供样' && Boolean(insight?.sample_available)) || (materialFilter === '有有效报价' && Boolean(insight?.effective_quote_count))
    return search && materialsMatch && (status === '全部' || supplier.current_status === status) && (exportFilter === '全部' || supplier.export_status === exportFilter)
  })
  const documentsHint = (supplier: Supplier) => { const insight = insights.find(item => item.supplier_id === supplier.id); return `${insight?.document_count || 0} 份资料 · TDS ${insight?.tds_count || 0} · 报价 ${insight?.effective_quote_count || 0}` }
  return <section className="page supplier-page"><div className="page-heading"><div><p className="eyebrow"><Factory size={13}/> SUPPLIER INTELLIGENCE</p><h1>供应商中心</h1><p>中国供应商资料库 · 将客户项目、供应商能力、询价、资料和样品推进到同一条链路。</p></div><div className="supplier-page-actions"><button onClick={link}>关联客户项目</button><button onClick={createRfq}>创建供应商询价</button><button className="primary" onClick={create}><Plus size={17}/> 新增供应商</button></div></div><div className="supplier-kpis"><span><b>{suppliers.length}</b> 供应商</span><span><b>{suppliers.filter(supplier => ['等 TDS', '等报价', '等样品'].includes(supplier.current_status)).length}</b> 待资料</span><span><b>{suppliers.filter(supplier => supplier.next_followup_date && supplier.next_followup_date <= today).length}</b> 到期跟进</span><span><b>{links.length}</b> 项目协同</span><span><b>{rfqs.filter(rfq => rfq.status !== '关闭').length}</b> 进行中 RFQ</span></div><section className="table-panel supplier-list-panel"><div className="table-tools supplier-tools"><label><Search size={17}/><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索公司、联系人、产品、地区、电话、邮箱或关键词"/></label><select value={status} onChange={event => setStatus(event.target.value)}><option>全部</option>{['待联系','已询价','等 TDS','等报价','等样品','技术评估','已合作','暂停','淘汰'].map(value => <option key={value}>{value}</option>)}</select><select value={exportFilter} onChange={event => setExportFilter(event.target.value)}><option>全部</option><option>可出口</option><option>不可出口</option><option>待确认</option></select><select value={materialFilter} onChange={event => setMaterialFilter(event.target.value)}><option>全部</option><option>有 TDS</option><option>可供样</option><option>有有效报价</option></select></div><div className="supplier-grid">{visible.map(supplier => { const insight = insights.find(item => item.supplier_id === supplier.id); return <article className="supplier-card" key={supplier.id}><div className="supplier-card-top"><div className="company-avatar"><Factory size={16}/></div><div><b>{supplier.company_name}</b><span>{supplier.city || supplier.province || supplier.country} · {supplier.supplier_type} · {supplier.export_status}</span></div><Stage stage={supplier.current_status as CustomerStage}/></div><div className="supplier-tags">{(supplier.product_keywords || []).slice(0, 4).map(tag => <span key={tag}>{tag}</span>)}</div><dl><div><dt>联系人 / 联系方式</dt><dd>{supplier.main_phone || supplier.main_email || supplier.wechat || '待补充'}</dd></div><div><dt>下一步</dt><dd>{supplier.next_action || '待确认下一步'}</dd></div><div><dt>下次跟进</dt><dd className={supplier.next_followup_date && supplier.next_followup_date <= today ? 'due' : ''}>{supplier.next_followup_date || '未设置'}</dd></div><div><dt>供应链协同</dt><dd>{insight?.project_link_count ?? links.filter(linkItem => linkItem.supplier_id === supplier.id).length} 个客户项目 · {documentsHint(supplier)}{insight?.sample_available ? ' · 可供样' : ''}</dd></div></dl><div className="supplier-card-foot"><span>{supplier.risk_notes ? '⚠ 有风险备注' : supplier.current_status}</span><button className="primary" onClick={() => open(supplier)}>供应商 360 <ChevronRight size={14}/></button></div></article> })}</div>{!visible.length && <div className="empty">没有符合筛选条件的供应商。</div>}</section></section>
}

function SupplierDrawer({ supplier, customers, projects, products, links, rfqs, close, changed }: { supplier: Supplier; customers: Customer[]; projects: Project[]; products: Product[]; links: SupplierProjectLink[]; rfqs: SupplierRfq[]; close: () => void; changed: () => Promise<void> }) {
  const [contacts, setContacts] = useState<SupplierContact[]>([]); const [supplierProducts, setSupplierProducts] = useState<SupplierProduct[]>([]); const [followups, setFollowups] = useState<SupplierFollowup[]>([]); const [documents, setDocuments] = useState<SupplierDocument[]>([]); const [busy, setBusy] = useState(false)
  const load = async () => { const [contactRows, productRows, followupRows, documentRows] = await Promise.all([api.supplierContacts(supplier.id), api.supplierProducts(supplier.id), api.supplierFollowups(supplier.id), api.supplierDocuments(supplier.id)]); setContacts(contactRows); setSupplierProducts(productRows); setFollowups(followupRows); setDocuments(documentRows) }
  useEffect(() => { void load().catch(error => console.error('Unable to load supplier 360:', error)) }, [supplier.id])
  const customerName = (id: string) => customers.find(customer => customer.id === id)?.company_name || '受权限限制的客户'
  const projectName = (id: string) => projects.find(project => project.id === id)?.project_name || '项目待确认'
  const submit = async (work: () => Promise<void>) => { setBusy(true); try { await work(); await load(); await changed() } catch (error) { alert(error instanceof Error ? error.message : '保存失败，请稍后重试。') } finally { setBusy(false) } }
  return <div className="drawer-layer"><aside className="drawer supplier-drawer"><button className="close" onClick={close}><X size={20}/></button><div className="drawer-head"><div className="company-avatar large"><Factory size={22}/></div><div><p>SUPPLIER 360</p><h2>{supplier.company_name}</h2><Stage stage={supplier.current_status as CustomerStage}/></div></div><div className="supplier-contact-strip"><span>{supplier.english_name || '英文名待确认'}</span><span>{supplier.main_phone || '电话待确认'}</span><span>{supplier.main_email || '邮箱待确认'}</span></div><section className="detail-section"><h3>基础信息</h3><div className="contact-grid"><div><span>公司类型</span><b>{supplier.supplier_type}</b></div><div><span>出口能力</span><b>{supplier.export_status}</b></div><div><span>地区 / 地址</span><b>{[supplier.country, supplier.province, supplier.city, supplier.address].filter(Boolean).join(' · ') || '待确认'}</b></div><div><span>官网</span><b>{supplier.website || '待确认'}</b></div></div><CustomerTags tags={supplier.supplier_tags}/><div className="next-action"><Factory size={17}/><div><span>下一步</span><b>{supplier.next_action || '待确认'}</b></div><time>{supplier.next_followup_date || '未设置日期'}</time></div>{supplier.risk_notes && <div className="supplier-risk">风险备注：{supplier.risk_notes}</div>}</section><section className="detail-section"><h3>联系人</h3>{contacts.map(contact => <div className="supplier-detail-row" key={contact.id}><b>{contact.name}{contact.is_primary ? ' · 主要联系人' : ''}</b><span>{[contact.title, contact.mobile || contact.phone, contact.email, contact.wechat].filter(Boolean).join(' · ')}</span></div>)}<form className="supplier-inline-form" onSubmit={event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; void submit(async () => { await api.createSupplierContact({ supplier_id: supplier.id, name: values.name, title: values.title || null, mobile: values.mobile || null, phone: null, email: values.email || null, wechat: values.wechat || null, whatsapp: null, responsible_products: values.responsible_products || null, is_primary: values.is_primary === 'on', notes: null }); event.currentTarget.reset() }) }}><Field label="姓名 *" name="name" required/><Field label="职务" name="title"/><Field label="手机" name="mobile"/><Field label="邮箱" name="email"/><Field label="微信" name="wechat"/><Field label="负责产品" name="responsible_products"/><label className="checkbox-field"><input type="checkbox" name="is_primary"/> 主要联系人</label><button className="secondary" disabled={busy}>新增联系人</button></form></section><section className="detail-section"><h3>产品能力</h3>{supplierProducts.map(item => <div className="supplier-detail-row" key={item.id}><b>{item.product_name}</b><span>{item.reference_model ? `参考：${item.reference_model} · ` : ''}{item.application || '应用待确认'} · NL 牌号：{item.nl_status}</span><small>{item.technical_summary || '技术指标待供应商资料确认'}</small></div>)}<form className="supplier-inline-form" onSubmit={event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; void submit(async () => { await api.createSupplierProduct({ supplier_id: supplier.id, product_name: values.product_name, internal_keywords: values.internal_keywords.split(/[,，]/).map(value => value.trim()).filter(Boolean), nl_product_id: null, nl_status: '无 / 待确认', reference_model: values.reference_model || null, application: values.application || null, technical_summary: values.technical_summary || null, customizable: '待确认', sample_available: '待确认', capacity: null, moq: null, standard_lead_time: null, packaging: null, export_capacity: '待确认', notes: '供应商产品，尚未创建正式 NL 牌号。' }); event.currentTarget.reset() }) }}><Field label="供应商产品 *" name="product_name" required/><Field label="内部关键词" name="internal_keywords"/><Field label="参考 / 对标型号" name="reference_model"/><Field label="应用领域" name="application"/><label className="wide">技术指标摘要<textarea name="technical_summary" placeholder="仅记录供应商正式资料；无资料则保持待确认。"/></label><button className="secondary" disabled={busy}>新增供应商产品</button></form></section><section className="detail-section"><h3>资料中心</h3><div className="document-list">{documents.map(document => <button key={document.id} onClick={() => void api.supplierDocumentPreview(document.id).then(result => window.open(result.url, '_blank', 'noopener,noreferrer')).catch(error => alert(error instanceof Error ? error.message : '无法打开资料'))}><Paperclip size={15}/><div><b>{document.document_type} · {document.file_name}</b><small>{document.source} · {new Date(document.uploaded_at).toLocaleDateString('zh-CN')}</small></div><ChevronRight size={15}/></button>)}</div><form className="supplier-upload-form" onSubmit={event => { event.preventDefault(); const values = new FormData(event.currentTarget); const file = values.get('file'); if (!(file instanceof File) || !file.size) return alert('请选择资料文件。'); void submit(async () => { await api.uploadSupplierDocument({ supplier_id: supplier.id, document_type: String(values.get('document_type')) as SupplierDocument['document_type'], file, source: '手动上传', internal_notes: String(values.get('internal_notes') || '') || undefined }); event.currentTarget.reset() }) }}><select name="document_type" defaultValue="TDS"><option>TDS</option><option>SDS</option><option>COA</option><option>报价单</option><option>产品图片</option><option>认证文件</option><option>邮件附件</option><option>其他资料</option></select><input name="file" type="file"/><input name="internal_notes" placeholder="内部备注（可选）"/><button className="secondary" disabled={busy}>上传资料</button></form></section><section className="detail-section"><h3>客户项目协同</h3>{links.map(link => <div className="supplier-detail-row" key={link.id}><b>{customerName(link.customer_id)} · {projectName(link.project_id)}</b><span>{link.match_status} · {link.reference_product || '参考型号待确认'} · {link.next_followup_date || '未设跟进日期'}</span><small>{link.current_risk || link.technical_match_notes || '技术匹配待确认'}</small></div>)}{rfqs.map(rfq => <div className="supplier-detail-row" key={rfq.id}><b>{rfq.rfq_number} · {rfq.demand_product}</b><span>{rfq.status} · {customerName(rfq.customer_id)} · {rfq.next_followup_date || '未设跟进日期'}</span></div>)}</section><section className="detail-section"><h3>沟通与跟进</h3>{followups.map(followup => <div className="note" key={followup.id}><time>{followup.date} · {followup.channel} · {followup.status}</time><p>{followup.content}</p><small>{followup.conclusion || ''}{followup.next_action ? ` · 下一步：${followup.next_action}` : ''}</small></div>)}<form className="supplier-followup-form" onSubmit={event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; void submit(async () => { await api.createSupplierFollowup({ supplier_id: supplier.id, date: values.date, channel: values.channel as SupplierFollowup['channel'], content: values.content, conclusion: values.conclusion || null, next_action: values.next_action || null, next_followup_date: values.next_followup_date || null, owner_name: null, status: values.status as SupplierFollowup['status'], create_task: values.create_task === 'on' }); event.currentTarget.reset() }) }}><div className="form-grid"><label>日期 *<input name="date" type="date" defaultValue={new Date().toISOString().slice(0, 10)} required/></label><label>沟通方式<select name="channel"><option>微信</option><option>邮件</option><option>电话</option><option>会议</option><option>报价</option><option>样品</option><option>技术确认</option><option>其他</option></select></label><label>当前状态<select name="status" defaultValue={supplier.current_status}>{['待联系','已询价','等 TDS','等报价','等样品','技术评估','已合作','暂停','淘汰'].map(value => <option key={value}>{value}</option>)}</select></label><label>下次跟进<input name="next_followup_date" type="date" defaultValue={supplier.next_followup_date || ''}/></label><label className="wide">沟通内容 *<textarea name="content" required/></label><label className="wide">当前结论<textarea name="conclusion"/></label><label className="wide">下一步<textarea name="next_action"/></label><label className="checkbox-field"><input type="checkbox" name="create_task" defaultChecked/> 同步到每日计划</label></div><div className="form-actions"><button className="primary" disabled={busy}>保存供应商跟进</button></div></form></section></aside></div>
}

function ImportInbox({ customers, afterApplied }: { customers: Customer[]; afterApplied: () => Promise<void> }) {
  const [raw, setRaw] = useState('')
  const [preview, setPreview] = useState<ImportPreview | null>(null)
  const [batch, setBatch] = useState<ImportBatch | null>(null)
  const [batches, setBatches] = useState<ImportBatch[]>([])
  const [selectedCustomerId, setSelectedCustomerId] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const loadBatches = async () => setBatches(await api.imports())
  useEffect(() => { void loadBatches().catch(reason => console.info('Import history is waiting for its database migration.', reason)) }, [])
  const createPreview = async () => {
    setError(''); setPreview(null); setBatch(null); setSelectedCustomerId('')
    let payload: Record<string, unknown>
    try { payload = JSON.parse(raw) as Record<string, unknown> } catch { setError('JSON 格式无效。请复制完整的数据包，不要带 Markdown 代码围栏。'); return }
    setBusy(true)
    try {
      const result = await api.previewImport(payload)
      setPreview(result.preview); setBatch(result.batch)
      if (result.preview.customer_match?.customer_id) setSelectedCustomerId(result.preview.customer_match.customer_id)
      await loadBatches()
    } catch (reason) { setError(reason instanceof Error ? reason.message : '暂存校验失败，请检查 JSON。') } finally { setBusy(false) }
  }
  const apply = async () => {
    if (!batch || !preview) return
    const needsSelection = preview.customer_match?.kind === 'internal_forwarder' || preview.customer_match?.kind === 'company_ambiguous'
    if (needsSelection && !selectedCustomerId) { setError('请先选择真实的海外客户；内部同事邮箱不会被建立为客户。'); return }
    setBusy(true); setError('')
    try {
      await api.applyImport(batch.id, { confirm_company_match: (preview.supplier_match || preview.customer_match)?.requires_confirmation || false, selected_customer_id: selectedCustomerId || undefined })
      await afterApplied(); await loadBatches()
      setBatch(null); setPreview(null); setRaw('')
      alert('已确认导入：CRM、跟进、时间线以及可选的每日任务均已更新。')
    } catch (reason) { setError(reason instanceof Error ? reason.message : '导入失败，请稍后重试。') } finally { setBusy(false) }
  }
  const revert = async (item: ImportBatch) => {
    if (!confirm(`撤销 ${item.source_reference || '这次导入'} 的业务影响？不会硬删除业务数据。`)) return
    setBusy(true); setError('')
    try { const result = await api.revertImport(item.id); await afterApplied(); await loadBatches(); alert(result.message) } catch (reason) { setError(reason instanceof Error ? reason.message : '撤销失败，请稍后重试。') } finally { setBusy(false) }
  }
  const isSupplierImport = Boolean(preview?.supplier_match)
  const match = preview?.supplier_match || preview?.customer_match
  const requiresCustomerChoice = !isSupplierImport && (match?.kind === 'internal_forwarder' || match?.kind === 'company_ambiguous')
  return <section className="page import-page"><div className="page-heading"><div><p className="eyebrow"><Inbox size={13}/> AI IMPORT INBOX</p><h1>AI 导入暂存箱</h1><p>把 ChatGPT 整理出的标准 JSON 先放进暂存箱。只有你预览并确认后，才会写入 CRM。</p></div></div>
    <div className="import-safety"><CircleHelp size={17}/><div><b>不自动猜测、不直接写入</b><span>邮箱精确匹配可更新；公司名匹配必须由你确认。Peter 等内部同事邮箱永远不能自动创建为客户。</span></div></div>
    <div className="import-layout"><div className="import-editor panel"><div className="panel-title"><div><p className="eyebrow">STEP 1</p><h2>粘贴 JSON 数据包</h2></div></div><textarea value={raw} onChange={event => setRaw(event.target.value)} spellCheck={false} placeholder={'{\n  "schema_version": "zhiwu-os-import/v1",\n  "intent": "upsert_customer_and_followup",\n  ...\n}'} /><p>客户产品编号必须以 <code>NL-</code> 开头；供应商产品不得自动生成 NL 牌号。</p><button className="primary" disabled={busy || !raw.trim()} onClick={() => void createPreview()}><RefreshCw size={16}/> {busy ? '正在校验…' : '校验并生成预览'}</button>{error && <div className="login-error">{error}</div>}</div>
      <div className="import-preview panel"><div className="panel-title"><div><p className="eyebrow">STEP 2</p><h2>预览差异</h2></div>{batch && <span className="draft-badge">暂存草稿</span>}</div>{!preview ? <div className="focus-empty"><Inbox size={23}/><b>等待导入数据</b><span>系统会先告诉你将新增或更新哪些业务记录。</span></div> : <><div className={`import-match ${match?.kind || ''}`}><b>{isSupplierImport ? '供应商匹配' : '客户匹配'}：{match?.kind === 'email_exact' ? '邮箱精确匹配' : match?.kind === 'company_manual_review' ? '公司名称待确认' : match?.kind === 'company_ambiguous' ? '公司名称存在歧义' : match?.kind === 'internal_forwarder' ? '内部同事转发' : isSupplierImport ? '将新建供应商' : '将新建客户'}</b><span>{match?.message}</span></div>{requiresCustomerChoice && <label className="import-select">选择真实客户<select value={selectedCustomerId} onChange={event => setSelectedCustomerId(event.target.value)}><option value="">请选择客户</option>{customers.map(customer => <option key={customer.id} value={customer.id}>{customer.company_name} · {customer.country} · {customer.contact_person}</option>)}</select></label>}{!isSupplierImport && match?.kind === 'company_manual_review' && <label className="import-select">确认要更新的客户<select value={selectedCustomerId} onChange={event => setSelectedCustomerId(event.target.value)}>{match.candidates.map(customer => <option key={customer.id} value={customer.id}>{customer.company_name} · {customer.email || '无邮箱'}</option>)}</select></label>}<div className="import-actions">{preview.actions.map((action, index) => <div key={`${action.entity}-${index}`}><span className={action.action === '更新' ? 'update' : ''}>{action.action}</span><b>{action.entity}</b><p>{action.label}</p></div>)}</div>{preview.uncertain_fields.length > 0 && <p className="import-uncertain">待你确认：{preview.uncertain_fields.join('、')}</p>}<button className="primary" disabled={busy} onClick={() => void apply()}><Check size={16}/> {isSupplierImport ? '确认写入供应商中心' : '确认写入 CRM'}</button></>}</div></div>
    <div className="panel import-history"><div className="panel-title"><div><p className="eyebrow">AUDIT LOG</p><h2>导入记录与撤销</h2></div><span>保留历史，不硬删除业务数据</span></div>{batches.length ? <div className="import-history-list">{batches.map(item => <div key={item.id}><div><b>{item.source_reference || '未命名导入'}</b><span>{item.source_date || item.created_at.slice(0, 10)} · {item.source_type || 'chat_summary'}</span></div><em className={`import-status ${item.status}`}>{item.status === 'draft' ? '草稿' : item.status === 'applied' ? '已导入' : item.status === 'reverted' ? '已撤销' : '失败'}</em>{item.status === 'applied' && <button disabled={busy} onClick={() => void revert(item)}>撤销本次影响</button>}</div>)}</div> : <p className="detail-empty">暂无导入记录。每次校验都会创建一份可追溯的暂存草稿。</p>}</div>
  </section>
}

const mailCategoryLabels: Record<MailEmail['category'], string> = { customer_inquiry: '客户询盘', technical: '技术讨论', quotation: '报价相关', sample: '样品相关', payment: '付款相关', other: '其他' }
const mailStatusLabels: Record<MailEmail['status'], string> = { unread: '待跟进', new_lead: '新线索', linked: '已关联', followup_created: '已创建跟进', completed: '已处理' }

function emailCustomerSuggestion(email: MailEmail, customers: Customer[]) {
  if (email.customer_id || email.is_internal_sender) return null
  const sender = email.sender.trim().toLowerCase()
  const domain = sender.split('@')[1]?.split('.')[0] || ''
  const name = (email.sender_name || '').trim().toLowerCase()
  const exact = customers.find(customer => customer.email.trim().toLowerCase() === sender)
  if (exact) return { customer: exact, confidence: '高', reason: '发件人邮箱与客户档案完全一致' }
  const named = customers.find(customer => name && customer.contact_person.toLowerCase().includes(name))
  if (named) return { customer: named, confidence: '中', reason: '发件人姓名与客户联系人一致' }
  const company = customers.find(customer => domain.length > 2 && customer.company_name.toLowerCase().replace(/[^a-z0-9]/g, '').includes(domain.replace(/[^a-z0-9]/g, '')))
  return company ? { customer: company, confidence: '中', reason: '邮箱域名与客户公司名称相符' } : null
}

function emailCrmSuggestion(email: MailEmail) {
  const byCategory: Record<MailEmail['category'], { stage: CustomerStage; action: string }> = {
    quotation: { stage: 'Quotation', action: '确认报价范围、数量、贸易条款及客户回复时间。' },
    sample: { stage: 'Sample Payment', action: '确认样品规格、寄送地址、付款与签收安排。' },
    payment: { stage: 'Sample Payment', action: '核对付款状态，并安排后续样品或订单动作。' },
    technical: { stage: 'Technical Discussion', action: '确认技术参数、应用工艺及需补充的资料。' },
    customer_inquiry: { stage: 'New Inquiry', action: '确认客户需求、规格、数量和预计采购时间。' },
    other: { stage: 'New Inquiry', action: '人工确认此邮件是否需要转为业务行动。' },
  }
  return byCategory[email.category]
}

function MailCenter({ emails, sync, mailbox, customers, projects, products, open }: { emails: MailEmail[]; sync: EmailSync; mailbox: MailboxAccount; customers: Customer[]; projects: Project[]; products: Product[]; open: (email: MailEmail) => void }) {
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState<'all' | MailEmail['category'] | 'unlinked'>(() => window.location.hash === '#mail/unlinked' ? 'unlinked' : 'all')
  const today = new Date().toISOString().slice(0, 10)
  const visible = emails.filter(email => {
    const customer = customers.find(item => item.id === email.customer_id)
    const project = projects.find(item => item.id === email.project_id || item.customer_id === email.customer_id)
    const product = products.find(item => item.id === email.product_id || item.id === project?.product_id)
    const searchable = `${email.sender_name || ''} ${email.sender} ${email.subject} ${email.content_preview || ''} ${customer?.company_name || ''} ${project?.project_name || ''} ${product?.product_code || ''}`.toLowerCase()
    const typeMatches = category === 'all' || (category === 'unlinked' ? !email.customer_id : email.category === category)
    return typeMatches && searchable.includes(query.toLowerCase())
  })
  const customerEmails = emails.filter(email => email.customer_id).length
  const unprocessed = emails.filter(email => ['unread', 'new_lead', 'linked'].includes(email.status)).length
  const attachments = emails.reduce((total, email) => total + email.attachment_count, 0)
  const todayCount = emails.filter(email => email.received_at.slice(0, 10) === today).length
  const filters: [typeof category, string][] = [['all', '全部'], ['customer_inquiry', '客户询盘'], ['technical', '技术讨论'], ['quotation', '报价相关'], ['sample', '样品相关'], ['payment', '付款相关'], ['unlinked', `未关联邮件 ${emails.filter(email => !email.customer_id).length}`]]
  const selectFilter = (value: typeof category) => { window.history.replaceState(null, '', `${window.location.pathname}${value === 'unlinked' ? '#mail/unlinked' : '#mail'}`); setCategory(value) }
  const syncLabel = !mailbox.configured || !mailbox.is_active || sync.status === 'Not configured' || sync.status === 'Idle' ? '等待邮箱配置' : sync.status === 'Success' ? '已同步' : sync.status
  return <section className="page mail-page"><div className="page-heading"><div><p className="eyebrow">MAIL CENTER · BUSINESS INBOX</p><h1>外贸邮件中心</h1><p>每一封客户来信都可关联到客户、项目、产品和下一步行动。</p></div><div className="mailbox-status"><span><Users size={15}/>{mailbox.label}{mailbox.email_address ? ` · ${mailbox.email_address}` : ''}</span><div className="sync-indicator"><RefreshCw size={15}/><span>{syncLabel}</span></div></div></div>
    <div className="mail-metrics"><Metric label="邮件总数" value={String(emails.length)} delta="当前账号全部邮件" icon={<Mail/>}/><Metric label="今日邮件" value={String(todayCount)} delta="当天接收" icon={<Mail/>}/><Metric label="待跟进" value={String(unprocessed)} delta="待转为业务动作" icon={<CircleHelp/>}/><Metric label="客户邮件" value={String(customerEmails)} delta="已关联 CRM" icon={<Users/>}/><Metric label="附件" value={String(attachments)} delta="仅统计，不下载" icon={<Paperclip/>}/></div>
    <section className="mail-list-panel"><div className="table-tools mail-tools"><label><Search size={17}/><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索客户、邮箱、产品、主题或关键词" /></label><span className="mail-sync-time">{sync.last_sync_time ? `上次同步 ${new Date(sync.last_sync_time).toLocaleString('zh-CN')}` : 'IMAP 每 10 分钟同步一次'}</span></div><div className="mail-filters">{filters.map(([value, label]) => <button key={value} className={category === value ? 'active' : ''} onClick={() => selectFilter(value)}>{label}</button>)}</div><div className="mail-list">{visible.map(email => {
      const customer = customers.find(item => item.id === email.customer_id)
      const project = projects.find(item => item.id === email.project_id || item.customer_id === email.customer_id)
      const product = products.find(item => item.id === email.product_id || item.id === project?.product_id)
      return <button className="mail-row business" key={email.id} onClick={() => open(email)}><span className={`mail-unread ${['unread', 'new_lead'].includes(email.status) ? 'is-unread' : ''}`}/><div className="mail-sender"><b>{email.sender_name || email.sender}</b><span>{customer ? `${customer.country} · ${customer.company_name}` : email.is_internal_sender ? '同事转发 · 待识别客户' : '待匹配客户'}</span></div><div className="mail-subject"><b>{email.subject}</b><span>{email.content_preview || '无可用正文预览'}</span></div><div className="mail-business"><b>{product?.product_code ?? customer?.product_interest ?? '待关联产品'}</b><span>{project?.project_name ?? '待关联项目'}</span></div><div className="mail-tags"><span className={`mail-status ${email.status}`}>{mailStatusLabels[email.status]}</span><span className="mail-category">{email.is_internal_sender ? '同事转发' : mailCategoryLabels[email.category]}</span></div><time>{email.received_at.slice(0, 10)}</time>{email.attachment_count > 0 && <Paperclip size={15}/>}</button>
    })}</div>{!visible.length && <div className="mail-empty"><Mail size={26}/><b>{emails.length ? '没有符合筛选条件的邮件' : '还没有同步到邮件'}</b><span>{emails.length ? '更换分类或关键词后再试。' : '完成服务器端 IMAP 配置后，新的客户邮件会自动出现在这里。'}</span></div>}</section>
  </section>
}

function MailDetail({ email, customers, projects, products, close, updateCrm, linkEmail, createCustomer, updateStatus, openCustomer }: { email: MailEmail; customers: Customer[]; projects: Project[]; products: Product[]; close: () => void; updateCrm: (email: MailEmail, payload: { customer_id: string; project_id?: string; product_id?: string; customer_stage: CustomerStage; next_action: string; followup_date: string; notes: string; create_task: boolean; task_date?: string }) => Promise<void>; linkEmail: (email: MailEmail, customer: Customer) => Promise<void>; createCustomer: (email: MailEmail, payload: Omit<Customer, 'id' | 'created_at' | 'last_contact_date'>) => Promise<void>; updateStatus: (email: MailEmail, status: MailEmail['status']) => Promise<void>; openCustomer: (customer: Customer) => void }) {
  const [linking, setLinking] = useState(false)
  const [pickerOpen, setPickerOpen] = useState(false)
  const [crmOpen, setCrmOpen] = useState(false)
  const [crmSaving, setCrmSaving] = useState(false)
  const [crmError, setCrmError] = useState('')
  const [createCustomerOpen, setCreateCustomerOpen] = useState(false)
  const [createCustomerError, setCreateCustomerError] = useState('')
  const [creatingCustomer, setCreatingCustomer] = useState(false)
  const [crmCustomerId, setCrmCustomerId] = useState(email.customer_id || '')
  const [crmProjectId, setCrmProjectId] = useState(email.project_id || '')
  const [crmProductId, setCrmProductId] = useState(email.product_id || '')
  const [query, setQuery] = useState('')
  const customer = customers.find(item => item.id === email.customer_id)
  const project = projects.find(item => item.id === email.project_id || item.customer_id === email.customer_id)
  const product = products.find(item => item.id === email.product_id || item.id === project?.product_id || item.product_code === customer?.product_interest)
  const crmCustomer = customers.find(item => item.id === crmCustomerId)
  const crmProjects = projects.filter(item => item.customer_id === crmCustomerId)
  const candidates = customers.filter(item => `${item.company_name} ${item.country} ${item.contact_person} ${item.email}`.toLowerCase().includes(query.toLowerCase()))
  const suggestion = emailCustomerSuggestion(email, customers)
  const crmSuggestion = emailCrmSuggestion(email)
  const link = async (target: Customer) => { setLinking(true); try { await linkEmail(email, target); setPickerOpen(false) } finally { setLinking(false) } }
  const saveCrm = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>
    setCrmSaving(true); setCrmError('')
    try {
      await updateCrm(email, { customer_id: values.customer_id, project_id: values.project_id || undefined, product_id: values.product_id || undefined, customer_stage: values.customer_stage as CustomerStage, next_action: values.next_action, followup_date: values.followup_date, notes: values.notes, create_task: values.create_task === 'on', task_date: values.task_date || undefined })
      setCrmOpen(false)
    } catch (error) { setCrmError(error instanceof Error ? error.message : '保存失败，请稍后重试。') } finally { setCrmSaving(false) }
  }
  const saveNewCustomer = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setCreatingCustomer(true); setCreateCustomerError('')
    const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>
    try {
      await createCustomer(email, { company_name: values.company_name, country: values.country || '待确认', contact_person: values.contact_person || email.sender_name || '待确认', email: values.email, whatsapp: values.whatsapp || '', product_interest: values.product_interest || '', customer_stage: 'New Inquiry', next_followup_date: '', notes: `由邮件中心创建：${email.subject}` })
      setCreateCustomerOpen(false)
    } catch (error) { setCreateCustomerError(error instanceof Error ? error.message : '创建客户失败，请稍后重试。') } finally { setCreatingCustomer(false) }
  }
  const suggestedCompany = email.sender.includes('@') ? email.sender.split('@')[1].split('.')[0] : ''
  return <div className="drawer-layer" onMouseDown={close}><aside className="drawer mail-detail" onMouseDown={event => event.stopPropagation()}><button className="close" onClick={close}><X size={20}/></button><p className="eyebrow">MAIL DETAIL · {email.is_internal_sender ? 'INTERNAL FORWARD' : mailCategoryLabels[email.category]}</p><h2>{email.subject}</h2><div className="mail-detail-meta"><span>{email.sender_name || email.sender}</span><span>{email.sender}</span><time>{new Date(email.received_at).toLocaleString('zh-CN')}</time></div>{email.is_internal_sender && <div className="mail-forward-note"><Users size={14}/><span>此邮件来自内部同事转发，不会被当作客户邮箱自动关联。请在“更新 CRM”中选择真正的海外客户。</span></div>}{suggestion && <div className="mail-suggestion"><Brain size={16}/><div><b>智能处理建议 · {suggestion.confidence}置信度</b><span>建议关联到 {suggestion.customer.company_name}：{suggestion.reason}</span></div><button disabled={linking} onClick={() => void link(suggestion.customer)}>{linking ? '关联中…' : '采纳关联'}</button></div>}<div className="mail-content">{email.content_text || email.content_preview || '邮件正文不可用。'}</div>{email.attachment_count > 0 && <div className="mail-attachments"><Paperclip size={15}/>{email.attachment_count} 个附件（当前只记录数量，不下载或修改附件）</div>}
    <DetailSection title="Business Context"><div className="mail-link-card"><span>关联客户</span><b>{customer?.company_name ?? '未自动匹配'}</b><span>国家 / 联系人</span><b>{customer ? `${customer.country} · ${customer.contact_person}` : '待确认'}</b><span>项目</span><b>{project?.project_name ?? '待关联项目'}</b><span>产品</span><b>{product?.product_code ?? customer?.product_interest ?? '待确认'}</b><span>当前阶段</span><b>{customer ? stageLabels[customer.customer_stage] : '新线索'}</b><span>下一步</span><b>{customer?.next_action?.[0] ?? customer?.status_label ?? '确认邮件业务动作'}</b><span>状态</span><b>{mailStatusLabels[email.status]}</b></div>{customer && <div className="mail-customer-intel"><Brain size={15}/><span>{customer.customer_summary}</span></div>}{customer ? <button className="mail-open-customer" onClick={() => { close(); openCustomer(customer) }}>打开客户详情 <ChevronRight size={15}/></button> : <button className="mail-open-customer" onClick={() => setPickerOpen(true)}>关联客户 <ChevronRight size={15}/></button>}</DetailSection>
    {pickerOpen && <section className="mail-link-picker"><div><b>关联客户</b><button className="close" onClick={() => setPickerOpen(false)}><X size={16}/></button></div><label><Search size={15}/><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索公司、联系人或邮箱" /></label><div className="mail-customer-options">{candidates.map(item => <button key={item.id} disabled={linking} onClick={() => void link(item)}><span>{item.company_name}</span><small>{item.country} · {item.contact_person}</small><ChevronRight size={15}/></button>)}</div></section>}
    {createCustomerOpen && <section className="mail-crm-editor"><div className="mail-crm-editor-head"><div><b>从此邮件创建客户</b><span>客户会归入当前登录账号，并自动关联这封邮件。</span></div><button className="close" type="button" onClick={() => setCreateCustomerOpen(false)}><X size={16}/></button></div><form onSubmit={saveNewCustomer}><div className="form-grid"><Field label="公司名称 *" name="company_name" required defaultValue={suggestedCompany}/><Field label="国家 / 地区" name="country" defaultValue="待确认"/><Field label="联系人" name="contact_person" defaultValue={email.sender_name || ''}/><Field label="客户邮箱 *" name="email" type="email" required defaultValue={email.sender}/><Field label="WhatsApp" name="whatsapp"/><Field label="关注产品" name="product_interest"/></div>{createCustomerError && <div className="login-error">{createCustomerError}</div>}<div className="form-actions"><button type="button" onClick={() => setCreateCustomerOpen(false)}>取消</button><button className="primary" disabled={creatingCustomer}>{creatingCustomer ? '正在创建…' : '创建并关联邮件'}</button></div></form></section>}
    {crmOpen && <section className="mail-crm-editor"><div className="mail-crm-editor-head"><div><b>CRM 更新建议预览</b><span>系统按邮件类别预填建议；请核对后确认写入。</span></div><button className="close" type="button" onClick={() => setCrmOpen(false)}><X size={16}/></button></div><form onSubmit={saveCrm}><div className="form-grid"><label>客户 *<select name="customer_id" value={crmCustomerId} required onChange={event => { const id = event.target.value; const firstProject = projects.find(item => item.customer_id === id); setCrmCustomerId(id); setCrmProjectId(firstProject?.id || ''); setCrmProductId(firstProject?.product_id || '') }}><option value="">选择客户</option>{customers.map(item => <option key={item.id} value={item.id}>{item.company_name} · {item.contact_person}</option>)}</select></label><label>项目<select name="project_id" value={crmProjectId} onChange={event => { const id = event.target.value; const selectedProject = projects.find(item => item.id === id); setCrmProjectId(id); if (selectedProject?.product_id) setCrmProductId(selectedProject.product_id) }}><option value="">暂不关联项目</option>{crmProjects.map(item => <option key={item.id} value={item.id}>{item.project_name}</option>)}</select></label><label>产品<select name="product_id" value={crmProductId} onChange={event => setCrmProductId(event.target.value)}><option value="">暂不关联产品</option>{products.map(item => <option key={item.id} value={item.id}>{item.product_code} · {item.product_name}</option>)}</select></label><label>当前阶段 *<select name="customer_stage" defaultValue={crmCustomer?.customer_stage || customer?.customer_stage || crmSuggestion.stage}>{Object.entries(stageLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><Field label="下一步行动 *" name="next_action" required defaultValue={crmCustomer?.next_action?.[0] || customer?.next_action?.[0] || crmSuggestion.action}/><label>跟进日期 *<input name="followup_date" type="date" defaultValue={new Date().toISOString().slice(0, 10)} required/></label><label className="wide">备注 / 跟进内容 *<textarea name="notes" required defaultValue={`邮件：${email.subject}\n建议：${crmSuggestion.action}`} placeholder="记录客户反馈、判断和本次处理结论"/></label><label className="mail-task-check wide"><input type="checkbox" name="create_task"/><span>同时生成每日任务</span><input type="date" name="task_date" defaultValue={new Date().toISOString().slice(0, 10)} aria-label="任务日期"/></label></div>{crmError && <div className="login-error">{crmError}</div>}<div className="form-actions"><button type="button" onClick={() => setCrmOpen(false)}>取消</button><button className="primary" disabled={crmSaving}>{crmSaving ? '正在保存…' : '确认写入 CRM'}</button></div></form></section>}
    <div className="mail-detail-actions">{!customer && <><button onClick={() => setPickerOpen(true)}>关联客户</button>{!email.is_internal_sender && <button className="primary" onClick={() => setCreateCustomerOpen(true)}>创建客户并关联</button>}</>}<button className={customer ? 'primary' : ''} onClick={() => setCrmOpen(true)}>更新 CRM</button><button disabled={email.status === 'completed'} onClick={() => void updateStatus(email, 'completed')}>{email.status === 'completed' ? '已处理' : '标记已处理'}</button></div></aside></div>
}

function CustomerDrawer({customer,projects,quotes,followups,products,emails,tasks,timelineEvents,suppliers,supplierLinks,close,addFollowup,addQuote,updateStage,editCustomer,openEmail}:{customer:Customer;projects:Project[];quotes:Quote[];followups:Followup[];products:Product[];emails:MailEmail[];tasks:Task[];timelineEvents:TimelineEvent[];suppliers:Supplier[];supplierLinks:SupplierProjectLink[];close:()=>void;addFollowup:()=>void;addQuote:()=>void;updateStage:(customer:Customer,stage:CustomerStage)=>Promise<void>;editCustomer:()=>void;openEmail:(email:MailEmail)=>void}) {
  const [mobileTab, setMobileTab] = useState<'overview' | 'emails' | 'projects' | 'quotes' | 'timeline'>('overview')
  const notes = followups.filter(f=>f.customer_id===customer.id)
  const project = projects.find(item => item.customer_id === customer.id)
  const customerQuotes = quotes.filter(quote => quote.customer_id === customer.id)
  const product = products.find(item => item.id === project?.product_id || item.product_code === project?.product_code || item.product_code === customer.product_interest)
  const timeline = customer.timeline ?? notes.map(note => ({ date: note.date, title: note.content, detail: `Next: ${note.next_action}` }))
  const customerEmails = emails.filter(email => email.customer_id === customer.id)
  const customerTasks = tasks.filter(task => task.customer_id === customer.id).sort((a, b) => b.task_date.localeCompare(a.task_date)).slice(0, 5)
  const customerSupplyLinks = supplierLinks.filter(link => link.customer_id === customer.id)
  const recentCommunication = [...notes.map(note => ({ date: note.date, title: note.content, detail: `跟进：${note.next_action}` })), ...customerEmails.map(email => ({ date: email.received_at.slice(0, 10), title: `${email.sender_name || '客户'}：${email.subject}`, detail: email.content_preview || '邮件沟通' })), ...customerQuotes.map(quote => ({ date: quote.created_at || customer.last_contact_date, title: `报价：${quote.currency} ${quote.amount?.toLocaleString() || '待定'} · ${quote.status}`, detail: `${quote.quantity} · ${quote.trade_term || '贸易条款待确认'}` })), ...timelineEvents.filter(event => event.customer_id === customer.id && event.source === 'ai_import').map(event => ({ date: event.event_date, title: event.title, detail: 'AI 导入确认记录' })), ...(customer.sample_status ? [{ date: customer.last_contact_date, title: `样品状态：${customer.sample_status}`, detail: customer.status_label || '等待客户反馈' }] : [])].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 8)
  const list = (items?: string[]) => items?.length ? <ul className="detail-list">{items.map(item => <li key={item}>{item}</li>)}</ul> : <p className="detail-empty">暂无补充信息</p>
  return <div className="drawer-layer" onMouseDown={close}><aside className="drawer" data-mobile-tab={mobileTab} onMouseDown={e=>e.stopPropagation()}><button className="close" onClick={close}><X size={20}/></button>
    <div className="drawer-head intelligence-head"><div className="company-avatar large">{countryFlags[customer.country] ?? customer.company_name[0]}</div><div><p>{customer.country} · {customer.contact_person}</p><h2>{customer.company_name}</h2><div className="drawer-badges"><Stage stage={customer.customer_stage}/><ValueStars value={customer.customer_value}/></div></div></div><CustomerTags tags={customer.customer_tags}/>
    <div className="drawer-actions"><button className="primary" onClick={editCustomer}>编辑客户</button><button onClick={addFollowup}>添加跟进</button><button onClick={addQuote}>创建报价</button><button onClick={() => customerEmails[0] && openEmail(customerEmails[0])}>查看邮件</button></div><div className="mobile-detail-tabs">{([['overview', '概览'], ['emails', '邮件'], ['projects', '项目'], ['quotes', '报价'], ['timeline', '记录']] as const).map(([tab, label]) => <button key={tab} className={mobileTab === tab ? 'active' : ''} onClick={() => setMobileTab(tab)}>{label}</button>)}</div>
    <DetailSection title="Customer Memory" tab="overview"><div className="memory-card"><div><Brain size={16}/><span>客户是谁</span><b>{customer.customer_summary}</b></div><div><span>为什么联系</span><b>{customer.customer_background}</b></div><div><span>当前需求</span><b>{customer.customer_need}</b></div><div className="memory-notes"><span>注意事项</span><b>{customer.important_notes}</b></div></div></DetailSection>
    <DetailSection title="Company Profile" tab="overview"><div className="contact-grid"><span>联系人<b>{customer.contact_person}</b></span><span>国家 / 地区<b>{customer.country}</b></span><span>邮箱<b>{customer.email}</b></span><span>行业<b>{customer.industry}</b></span><span>应用<b>{customer.application ?? '待确认'}</b></span><span>WhatsApp<b>{customer.whatsapp}</b></span></div></DetailSection>
    <DetailSection title="Customer Project" tab="projects"><div className="project-summary"><span>项目名称</span><b>{project?.project_name ?? customer.product_interest}</b><span>产品</span><b>{project?.product_code ?? customer.product_interest}</b><span>应用</span><b>{project?.application ?? customer.application ?? '应用待确认'}</b><span>项目阶段</span><b>{stageLabels[project?.stage ?? customer.customer_stage]}</b>{customer.monthly_consumption && <><span>月度用量</span><b>{customer.monthly_consumption}</b></>}</div>{customer.project_background && list(customer.project_background)}{customer.requirements && <div className="requirement-box"><span>关键需求</span>{list(customer.requirements)}</div>}</DetailSection>
    <DetailSection title="Pipeline" tab="projects"><CustomerPipeline stage={project?.stage ?? customer.customer_stage}/></DetailSection>
    <DetailSection title="供应链协同" tab="projects">{customerSupplyLinks.length ? <div className="supply-link-list">{customerSupplyLinks.map(link => { const supplier = suppliers.find(item => item.id === link.supplier_id); return <div className="supplier-detail-row" key={link.id}><b>{supplier?.company_name || '供应商待确认'} · {link.match_status}</b><span>{link.reference_product || '参考型号待确认'} · {link.quote_status || '报价待确认'} · {link.sample_status || '样品待确认'}</span><small>{link.current_risk || link.next_action || '等待供应商资料或技术评估'}</small></div> })}</div> : <p className="detail-empty">尚未关联国内供应商。请在供应商中心将此客户项目与候选供应商关联。</p>}</DetailSection>
    <DetailSection title="Interested Products" tab="projects"><div className="product-detail"><span>{product?.product_code ?? customer.product_interest}</span><b>{product?.product_name ?? customer.application ?? '应用待确认'}</b></div><div className="document-tags"><span>TDS</span><span>COA</span><span>Product Images</span></div></DetailSection>
    <DetailSection title="Recent Communication" tab="timeline"><div className="communication-timeline">{recentCommunication.length ? recentCommunication.map(item => <div className="communication-item" key={`${item.date}-${item.title}`}><time>{item.date}</time><div><b>{item.title}</b>{item.detail && <span>{item.detail}</span>}</div></div>) : <p className="detail-empty">尚未添加沟通记录。</p>}</div></DetailSection>
    <DetailSection title="Email Timeline" tab="emails">{customerEmails.length ? <div className="communication-timeline">{customerEmails.map(email => <button className="communication-item email-timeline-item" key={email.id} onClick={() => { close(); openEmail(email) }}><time>{email.received_at.slice(0, 10)}</time><div><b>{email.sender_name || '客户'}：{email.subject}</b><span>{email.content_preview || '无邮件预览'}</span></div></button>)}</div> : <p className="detail-empty">尚未同步到该客户的邮件。</p>}</DetailSection>
    <DetailSection title="工作记录" tab="timeline">{customerTasks.length ? <div className="communication-timeline">{customerTasks.map(task => <div className="communication-item" key={task.id}><time>{task.task_date}</time><div><b>{task.status === 'Completed' ? '✓ 已完成：' : '待完成：'}{task.title}</b><span>{task.category} · {task.start_time ? timeLabel(task.start_time) : '全天'}</span></div></div>)}</div> : <p className="detail-empty">尚未为该客户安排工作任务。</p>}</DetailSection>
    <DetailSection title="Quotation History" tab="quotes">{customerQuotes.length ? <div className="quote-list">{customerQuotes.map(quote => <div className="quote-row" key={quote.id}><div><b>{quote.product_code ?? customer.product_interest}</b><span>{quote.quantity} · {quote.trade_term}</span></div><div><b>{quote.amount ? `${quote.currency} ${quote.amount.toLocaleString()}` : 'Amount pending'}</b><span>{quote.status}</span></div></div>)}</div> : customer.quotation ? <div className="quotation-box">{customer.quotation.map(item => <span key={item}>{item}</span>)}</div> : <p className="detail-empty">当前没有正式报价记录。</p>}</DetailSection>
    <DetailSection title="Sample Status" tab="overview"><div className="sample-box"><Package size={16}/><span>{customer.sample_status ?? customer.status_label ?? '等待样品安排'}</span></div>{customer.current_progress && <div className="progress-detail"><span>当前进度</span>{list(customer.current_progress)}</div>}</DetailSection>
    <div className="next-action customer-overview-action"><Sparkles size={17}/><div><span>Next Action</span><b>{customer.next_action?.[0] ?? notes[0]?.next_action ?? '安排下一次客户联系'}</b>{customer.next_action && customer.next_action.length > 1 && <small>{customer.next_action.slice(1).join(' · ')}</small>}</div><time>{customer.next_followup_date}</time></div><div className="stage-editor"><label htmlFor="customer-stage">更新客户阶段</label><select id="customer-stage" value={customer.customer_stage} onChange={event => void updateStage(customer, event.target.value as CustomerStage)}>{Object.entries(stageLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><button className="primary full" onClick={addFollowup}><Plus size={17}/> 添加跟进记录</button></aside></div>
}
function CustomerPipeline({ stage }: { stage: CustomerStage }) {
  const steps = ['Inquiry', 'Technical Discussion', 'Quotation', 'Sample', 'Testing', 'Negotiation', 'Won']
  const stageIndex = stage.includes('Technical') ? (stage === 'Technical Discussion' ? 1 : 4) : stage.includes('Sample') ? 3 : stage === 'Quotation' || stage === 'Quoted' ? 2 : stage === 'Negotiation' ? 5 : stage === 'Won' ? 6 : 0
  return <div className="customer-pipeline">{steps.map((step, index) => <div key={step} className={index === stageIndex ? 'current' : index < stageIndex ? 'done' : ''}><i/><span>{step}</span></div>)}</div>
}
function DetailSection({ title, children, tab }: { title: string; children: ReactNode; tab?: 'overview' | 'emails' | 'projects' | 'quotes' | 'timeline' }) { return <section className={`detail-section${tab ? ` detail-tab-${tab}` : ''}`}><h3>{title}</h3>{children}</section> }
function CustomerForm({close,submit}:{close:()=>void;submit:(f:HTMLFormElement)=>Promise<void>}) { return <Modal title="新建客户" close={close}><form onSubmit={async e=>{e.preventDefault();try { await submit(e.currentTarget) } catch (error) { alert(error instanceof Error ? error.message : '创建失败，请稍后重试。') }}}><div className="form-grid"><Field label="公司名称 *" name="company_name" required/><Field label="国家/地区 *" name="country" required/><Field label="联系人 *" name="contact_person" required/><Field label="邮箱 *" name="email" type="email" required/><Field label="WhatsApp" name="whatsapp"/><Field label="产品兴趣" name="product_interest"/><Field label="下次跟进" name="next_followup_date" type="date"/><label className="wide">备注<textarea name="notes" placeholder="记录客户背景、需求或特别事项"/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">创建客户</button></div></form></Modal> }
function CustomerEditForm({ customer, products, projects, close, submit }: { customer: Customer; products: Product[]; projects: Project[]; close: () => void; submit: (form: HTMLFormElement) => Promise<void> }) {
  const primaryProject = projects[0]
  const productId = products.find(product => product.product_code === customer.product_interest)?.id || primaryProject?.product_id || ''
  return <Modal title={`编辑客户 · ${customer.company_name}`} close={close}><form onSubmit={async event => { event.preventDefault(); try { await submit(event.currentTarget) } catch (error) { alert(error instanceof Error ? error.message : '保存失败，请稍后重试。') } }}><div className="form-grid">
    <Field label="公司名称 *" name="company_name" required defaultValue={customer.company_name}/><Field label="国家/地区 *" name="country" required defaultValue={customer.country}/><Field label="联系人 *" name="contact_person" required defaultValue={customer.contact_person}/><Field label="邮箱 *" name="email" type="email" required defaultValue={customer.email}/><Field label="WhatsApp" name="whatsapp" defaultValue={customer.whatsapp === '—' ? '' : customer.whatsapp}/><Field label="网站" name="website" defaultValue={customer.website || ''}/><Field label="微信 / 其他联系方式" name="wechat" defaultValue={customer.wechat || ''}/><Field label="所属行业" name="industry" defaultValue={customer.industry === '待确认行业' ? '' : customer.industry || ''}/>
    <label>优先级<select name="priority" defaultValue={customer.priority || 'MEDIUM'}><option value="HIGH">高</option><option value="MEDIUM HIGH">中高</option><option value="MEDIUM">中</option></select></label><label>客户价值（1–5）<select name="customer_value" defaultValue={String(customer.customer_value || 3)}>{[1,2,3,4,5].map(value => <option key={value} value={value}>{'★'.repeat(value)} {value}</option>)}</select></label><label>当前阶段<select name="customer_stage" defaultValue={customer.customer_stage}>{Object.entries(stageLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label>下次跟进日期<input name="next_followup_date" type="date" defaultValue={customer.next_followup_date === '—' ? '' : customer.next_followup_date}/></label>
    <label>主要产品<select name="product_id" defaultValue={productId}><option value="">暂不关联产品</option>{products.map(product => <option key={product.id} value={product.id}>{product.product_code} · {product.product_name}</option>)}</select></label><Field label="产品兴趣（无产品时填写）" name="product_interest" defaultValue={customer.product_interest === '—' ? '' : customer.product_interest}/><Field label="应用 / 需求场景" name="application" defaultValue={customer.application || ''}/><Field label="状态摘要" name="status_label" defaultValue={customer.status_label || ''}/>
    <label>关联项目<select name="project_id" defaultValue={primaryProject?.id || ''}><option value="">暂不修改项目</option>{projects.map(project => <option key={project.id} value={project.id}>{project.project_name}</option>)}</select></label><Field label="项目名称" name="project_name" defaultValue={primaryProject?.project_name || ''}/><label className="wide">项目备注<textarea name="project_notes" defaultValue={primaryProject?.notes || ''} placeholder="所选项目的内部备注；没有选择项目时不会保存"/></label>
    <label className="wide">客户画像<textarea name="customer_summary" defaultValue={customer.customer_summary === '待补充客户画像。' ? '' : customer.customer_summary || ''} placeholder="客户是谁、公司定位和业务概况"/></label><label className="wide">客户背景<textarea name="customer_background" defaultValue={customer.customer_background === '待补充客户背景。' ? '' : customer.customer_background || ''} placeholder="联系背景、合作机会或历史"/></label><label className="wide">当前需求<textarea name="customer_need" defaultValue={customer.customer_need === '待确认客户需求。' ? '' : customer.customer_need || ''} placeholder="产品、性能、数量、应用等需求"/></label><label className="wide">下一步行动（每行一项）<textarea name="next_action" defaultValue={(customer.next_action || []).join('\n')} placeholder="例如：发送样品 PI\n确认付款"/></label><label className="wide">客户标签（用逗号分隔）<input name="customer_tags" defaultValue={(customer.customer_tags || []).join(', ')} placeholder="例如：高潜力, 样品阶段, 食品包装"/></label><label className="wide">重要注意事项<textarea name="important_notes" defaultValue={customer.important_notes === '暂无特别注意事项。' ? '' : customer.important_notes || ''} placeholder="报价限制、风险、沟通偏好等"/></label><label className="wide">内部备注<textarea name="notes" defaultValue={customer.notes === '暂无备注' ? '' : customer.notes || ''} placeholder="仅供工作站内部查看"/></label>
  </div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">保存客户资料</button></div></form></Modal>
}
function SupplierForm({ close, submit }: { close: () => void; submit: (supplier: Omit<Supplier, 'id' | 'created_at'>) => Promise<void> }) { return <Modal title="新增供应商" close={close}><form onSubmit={event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; void submit({ company_name: values.company_name, english_name: values.english_name || null, country: values.country || 'China', province: values.province || null, city: values.city || null, address: values.address || null, website: values.website || null, supplier_type: values.supplier_type as Supplier['supplier_type'], export_status: values.export_status as Supplier['export_status'], main_phone: values.main_phone || null, main_email: values.main_email || null, wechat: values.wechat || null, product_keywords: values.product_keywords.split(/[,，]/).map(value => value.trim()).filter(Boolean), product_categories: values.product_categories.split(/[,，]/).map(value => value.trim()).filter(Boolean), supplier_tags: values.supplier_tags.split(/[,，]/).map(value => value.trim()).filter(Boolean), current_status: values.current_status as Supplier['current_status'], last_contact_date: null, next_action: values.next_action || null, next_followup_date: values.next_followup_date || null, notes: values.notes || null, risk_notes: values.risk_notes || null }) }}><div className="form-grid"><Field label="公司名称 *" name="company_name" required/><Field label="英文名" name="english_name"/><Field label="国家" name="country" defaultValue="China"/><Field label="省份 / 地区" name="province"/><Field label="城市" name="city"/><label>公司类型<select name="supplier_type" defaultValue="待确认"><option>待确认</option><option>工厂</option><option>贸易商</option></select></label><label>出口能力<select name="export_status" defaultValue="待确认"><option>待确认</option><option>可出口</option><option>不可出口</option></select></label><Field label="销售电话 / 总机" name="main_phone"/><Field label="邮箱" name="main_email" type="email"/><Field label="微信" name="wechat"/><Field label="官网" name="website"/><Field label="产品关键词（逗号分隔）" name="product_keywords"/><Field label="产品分类（逗号分隔）" name="product_categories"/><Field label="供应商标签（逗号分隔）" name="supplier_tags"/><label>当前状态<select name="current_status" defaultValue="待联系">{['待联系','已询价','等 TDS','等报价','等样品','技术评估','已合作','暂停','淘汰'].map(value => <option key={value}>{value}</option>)}</select></label><label>下次跟进日期<input name="next_followup_date" type="date"/></label><label className="wide">地址<textarea name="address"/></label><label className="wide">下一步<textarea name="next_action"/></label><label className="wide">风险备注<textarea name="risk_notes" placeholder="没有供应商正式资料时，保持待确认；不要对客户承诺替代。"/></label><label className="wide">内部备注<textarea name="notes"/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">保存供应商</button></div></form></Modal> }
function SupplierLinkForm({ suppliers, customers, projects, close, submit }: { suppliers: Supplier[]; customers: Customer[]; projects: Project[]; close: () => void; submit: (payload: Omit<SupplierProjectLink, 'id' | 'created_at'>) => Promise<void> }) { const [customerId, setCustomerId] = useState(customers[0]?.id || ''); const linkedProjects = projects.filter(project => project.customer_id === customerId); return <Modal title="关联供应商与客户项目" close={close}><form onSubmit={event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; void submit({ customer_id: values.customer_id, project_id: values.project_id, supplier_id: values.supplier_id, supplier_product_id: null, customer_need: values.customer_need || null, reference_product: values.reference_product || null, match_status: values.match_status as SupplierProjectLink['match_status'], technical_match_notes: values.technical_match_notes || null, quote_status: values.quote_status || null, sample_status: values.sample_status || null, current_risk: values.current_risk || null, next_action: values.next_action || null, next_followup_date: values.next_followup_date || null }) }}><div className="form-grid"><label>海外客户 *<select name="customer_id" value={customerId} onChange={event => setCustomerId(event.target.value)}>{customers.map(customer => <option key={customer.id} value={customer.id}>{customer.company_name}</option>)}</select></label><label>客户项目 *<select name="project_id" required>{linkedProjects.map(project => <option key={project.id} value={project.id}>{project.project_name}</option>)}</select></label><label>国内供应商 *<select name="supplier_id">{suppliers.map(supplier => <option key={supplier.id} value={supplier.id}>{supplier.company_name}</option>)}</select></label><label>匹配状态<select name="match_status" defaultValue="待询价">{['待询价','等资料','技术评估','已推荐','已送样','测试中','已成交','未匹配'].map(value => <option key={value}>{value}</option>)}</select></label><Field label="客户参考产品 / 竞品" name="reference_product"/><Field label="下次跟进日期" name="next_followup_date" type="date"/><label className="wide">客户需求<textarea name="customer_need"/></label><label className="wide">技术匹配说明<textarea name="technical_match_notes"/></label><label className="wide">报价 / 样品情况<textarea name="quote_status" placeholder="报价情况；可补充样品情况"/></label><label className="wide">当前风险<textarea name="current_risk"/></label><label className="wide">下一步<textarea name="next_action"/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">保存协同关联</button></div></form></Modal> }
function SupplierRfqForm({ suppliers, customers, projects, close, submit }: { suppliers: Supplier[]; customers: Customer[]; projects: Project[]; close: () => void; submit: (payload: Omit<SupplierRfq, 'id' | 'rfq_number' | 'created_date' | 'created_at'>) => Promise<void> }) { const [customerId, setCustomerId] = useState(customers[0]?.id || ''); const linkedProjects = projects.filter(project => project.customer_id === customerId); return <Modal title="创建供应商询价（RFQ）" close={close}><form onSubmit={event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; void submit({ customer_id: values.customer_id, project_id: values.project_id, supplier_id: values.supplier_id, supplier_product_id: null, demand_product: values.demand_product, reference_product: values.reference_product || null, end_application: values.end_application || null, technical_requirements: values.technical_requirements || null, sample_quantity: values.sample_quantity || null, expected_monthly_usage: values.expected_monthly_usage || null, expected_annual_usage: values.expected_annual_usage || null, destination_country: values.destination_country || null, requested_materials: values.requested_materials.split(/[,，]/).map(value => value.trim()).filter(Boolean), status: values.status as SupplierRfq['status'], sent_date: values.sent_date || null, next_followup_date: values.next_followup_date || null, reply_content: null }) }}><div className="form-grid"><label>海外客户 *<select name="customer_id" value={customerId} onChange={event => setCustomerId(event.target.value)}>{customers.map(customer => <option key={customer.id} value={customer.id}>{customer.company_name}</option>)}</select></label><label>客户项目 *<select name="project_id" required>{linkedProjects.map(project => <option key={project.id} value={project.id}>{project.project_name}</option>)}</select></label><label>供应商 *<select name="supplier_id">{suppliers.map(supplier => <option key={supplier.id} value={supplier.id}>{supplier.company_name}</option>)}</select></label><label>状态<select name="status" defaultValue="草稿"><option>草稿</option><option>已发送</option><option>供应商已回复</option><option>技术评估</option><option>关闭</option></select></label><Field label="需求产品 *" name="demand_product" required/><Field label="参考产品 / 对标型号" name="reference_product"/><Field label="终端应用" name="end_application"/><Field label="预计试样量" name="sample_quantity"/><Field label="预计月用量" name="expected_monthly_usage"/><Field label="预计年用量" name="expected_annual_usage"/><Field label="目的地 / 出口国家" name="destination_country"/><Field label="发送日期" name="sent_date" type="date"/><Field label="下次跟进日期" name="next_followup_date" type="date"/><label className="wide">技术要求<textarea name="technical_requirements"/></label><label className="wide">需要供应商回复的资料（逗号分隔）<textarea name="requested_materials" defaultValue="TDS, SDS, COA, 报价, MOQ, 样品, 交期, 包装, 出口能力"/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">创建 RFQ</button></div></form></Modal> }
function ProductCustomerLinkModal({ product, customers, relations, close, submit }: { product: Product; customers: Customer[]; relations: ProductCustomerRelation[]; close: () => void; submit: (customer: Customer) => Promise<void> }) { const [query, setQuery] = useState(''); const [saving, setSaving] = useState(''); const linkedIds = new Set(relations.filter(relation => relation.product_id === product.id).map(relation => relation.customer_id)); const available = customers.filter(customer => !linkedIds.has(customer.id) && `${customer.company_name} ${customer.country} ${customer.contact_person}`.toLowerCase().includes(query.toLowerCase())); return <Modal title={`关联客户 · ${product.product_code}`} close={close}><div className="relationship-modal-copy">选择一个客户，即可将 <b>{product.product_name}</b> 加入该客户的产品关系；不会改动原有项目或产品兴趣。</div><label className="relationship-search"><Search size={16}/><input autoFocus value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索公司、国家或联系人" /></label><div className="relationship-picker">{available.map(customer => <button type="button" key={customer.id} disabled={Boolean(saving)} onClick={async () => { setSaving(customer.id); try { await submit(customer) } catch (error) { alert(error instanceof Error ? error.message : '关联失败，请稍后重试。'); setSaving('') } }}><span>{countryFlags[customer.country] ?? '🌍'}</span><div><b>{customer.company_name}</b><small>{customer.country} · {customer.contact_person}</small></div><Plus size={15}/></button>)}{!available.length && <p className="detail-empty">没有可关联的客户。</p>}</div><div className="form-actions"><button type="button" onClick={close}>取消</button></div></Modal> }
type ProductHistoryItem = { id: string; date: string; source: string; title: string; detail?: string; customer?: string }
function ProductHistory({ product, customers, relations, projects, followups, emails, tasks, timelineEvents, close }: { product: Product; customers: Customer[]; relations: ProductCustomerRelation[]; projects: Project[]; followups: Followup[]; emails: MailEmail[]; tasks: Task[]; timelineEvents: TimelineEvent[]; close: () => void }) {
  const relatedRelations = relations.filter(relation => relation.product_id === product.id)
  const customerIds = new Set(relatedRelations.map(relation => relation.customer_id))
  const linkedCustomers = customers.filter(customer => customerIds.has(customer.id))
  const customerName = (id?: string | null) => customers.find(customer => customer.id === id)?.company_name
  const projectRows = projects.filter(project => project.product_id === product.id || project.product_code === product.product_code)
  const projectIds = new Set(projectRows.map(project => project.id))
  const rawHistory = [
    ...relatedRelations.map(relation => ({ id: `relation-${relation.id}`, date: relation.created_at?.slice(0, 10), source: '客户关联', title: `关联客户 · ${customerName(relation.customer_id) || '已关联客户'}`, detail: '产品-客户关系已创建', customer: customerName(relation.customer_id) })),
    ...projectRows.map(project => ({ id: `project-${project.id}`, date: project.created_at?.slice(0, 10), source: '项目', title: project.project_name, detail: [project.stage, project.application].filter(Boolean).join(' · '), customer: customerName(project.customer_id) })),
    ...followups.filter(followup => customerIds.has(followup.customer_id)).map(followup => ({ id: `followup-${followup.id}`, date: followup.date, source: '客户跟进', title: followup.content, detail: followup.next_action ? `下一步：${followup.next_action}` : undefined, customer: customerName(followup.customer_id) })),
    ...emails.filter(email => email.product_id === product.id || Boolean(email.project_id && projectIds.has(email.project_id))).map(email => ({ id: `email-${email.id}`, date: email.received_at?.slice(0, 10), source: '邮件', title: email.subject || '邮件沟通', detail: email.content_preview, customer: customerName(email.customer_id) })),
    ...tasks.filter(task => task.product_id === product.id || Boolean(task.project_id && projectIds.has(task.project_id))).map(task => ({ id: `task-${task.id}`, date: task.task_date, source: '任务', title: task.title, detail: task.description, customer: customerName(task.customer_id) })),
    ...timelineEvents.filter(event => event.product_id === product.id || Boolean(event.project_id && projectIds.has(event.project_id))).map(event => ({ id: `timeline-${event.id}`, date: event.event_date, source: event.source || '系统记录', title: event.title, customer: customerName(event.customer_id) })),
  ]
  const history: ProductHistoryItem[] = rawHistory.filter(item => Boolean(item.date)).map(item => ({ ...item, date: item.date! })).sort((left, right) => right.date.localeCompare(left.date))
  const actualCustomers = linkedCustomers.filter(customer => customer.customer_tags?.includes('实际推进客户'))
  const historicalCustomers = linkedCustomers.filter(customer => customer.customer_tags?.includes('历史项目'))
  return <Modal title={`${product.product_code} · 客户历史`} close={close}><section className="product-history"><div className="product-history-intro"><div><code>{product.product_code}</code><h3>{product.product_name}</h3><p>以下内容仅来自已保存的客户关联、项目、跟进、邮件、任务及系统记录；不会补造日期或沟通事件。</p></div><span>{history.length} 条真实记录</span></div><div className="product-history-customers"><b>当前关联客户</b><div>{actualCustomers.length ? actualCustomers.map(customer => <span key={customer.id}>{customer.company_name} · 实际推进</span>) : <small>暂无明确标注的实际推进客户</small>}{historicalCustomers.map(customer => <span className="historical" key={customer.id}>{customer.company_name} · 历史项目</span>)}</div></div><div className="product-history-list">{history.length ? history.map(item => <article className="product-history-item" key={item.id}><time>{item.date}</time><div><small>{item.source}{item.customer ? ` · ${item.customer}` : ''}</small><b>{item.title}</b>{item.detail && <p>{item.detail}</p>}</div></article>) : <div className="product-history-empty"><Clock3 size={22}/><b>尚无可展示的客户历史</b><span>关联客户后，后续保存的项目、跟进、邮件、任务与系统记录会出现在这里。</span></div>}</div></section></Modal>
}
function ProductForm({product,close,submit}:{product?:Product;close:()=>void;submit:(f:HTMLFormElement)=>Promise<void>}) { const csv = (items?: string[]) => (items || []).join(', '); return <Modal title={product ? `产品画像 · ${product.product_code}` : '添加产品画像'} close={close}><form onSubmit={async e=>{e.preventDefault();try { await submit(e.currentTarget) } catch (error) { alert(error instanceof Error ? error.message : '保存失败，请稍后重试。') }}}><div className="compliance-note">“已确认”表示画像中的应用、企业类型与证据已人工核对，可用于需求侧搜索；它不代表任何企业已经采购该产品。草稿产品不能用于需求侧搜客。</div><div className="form-grid"><Field label="产品名称 *" name="product_name" required defaultValue={product?.product_name}/><Field label="产品编号 *" name="product_code" required defaultValue={product?.product_code}/><Field label="产品分类" name="category" defaultValue={product?.category}/><Field label="简要应用说明" name="application" defaultValue={product?.application}/><label>画像状态<select name="profile_status" defaultValue={product?.profile_status || '草稿'}><option>草稿</option><option>已确认</option></select></label><label className="wide">技术关键词（逗号分隔）<textarea name="technical_keywords" defaultValue={csv(product?.technical_keywords)} placeholder="产品名称、牌号、材料或工艺技术词；供应工厂搜索使用"/></label><label className="wide">已确认下游应用（逗号分隔）<textarea name="confirmed_applications" defaultValue={csv(product?.confirmed_applications)} placeholder="仅填写产品官网、TDS、SDS、测试资料已证明的下游应用；需求侧搜索使用"/></label><label className="wide">目标行业（逗号分隔）<textarea name="target_industries" defaultValue={csv(product?.target_industries)} placeholder="例如包装、汽车、建材；按当前产品填写"/></label><label className="wide">目标企业类型（逗号分隔）<textarea name="target_company_types" defaultValue={csv(product?.target_company_types)} placeholder="例如配方商、加工厂、品牌方；按当前产品填写"/></label><label className="wide">排除规则（逗号分隔）<textarea name="exclusion_rules" defaultValue={csv(product?.exclusion_rules)} placeholder="例如贸易商、同行产品供应商、媒体；命中后进入排除"/></label><label className="wide">证据来源链接（逗号或换行分隔）<textarea name="evidence_urls" defaultValue={csv(product?.evidence_urls)} placeholder="产品官网、TDS、SDS、官方案例页 URL"/></label><label className="wide">产品描述<textarea name="description" defaultValue={product?.description} placeholder="产品特性、优势与边界"/></label><label className="wide">内部备注<textarea name="notes" defaultValue={product?.notes} placeholder="仅内部使用"/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">{product ? '保存产品画像' : '创建产品画像'}</button></div></form></Modal> }
function FollowupForm({ customer, close, submit }: { customer: Customer; close: () => void; submit: (form: HTMLFormElement) => Promise<void> }) { return <Modal title={`添加跟进 · ${customer.company_name}`} close={close}><form onSubmit={async event => { event.preventDefault(); try { await submit(event.currentTarget) } catch (error) { alert(error instanceof Error ? error.message : '保存失败，请稍后重试。') } }}><div className="form-grid"><Field label="日期 *" name="date" type="date" required/><Field label="下一步行动" name="next_action"/><label className="wide">沟通内容 *<textarea name="content" required placeholder="记录客户反馈、技术确认或项目进展"/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">保存跟进</button></div></form></Modal> }
function QuoteManagement({ quotes, orders, customers, projects, products, emails, create, edit, revise, convert, importMailDrafts }: { quotes: Quote[]; orders: SalesOrder[]; customers: Customer[]; projects: Project[]; products: Product[]; emails: MailEmail[]; create: () => void; edit: (quote: Quote) => void; revise: (quote: Quote) => Promise<void>; convert: (quote: Quote) => Promise<void>; importMailDrafts: () => Promise<void> }) {
  const [query, setQuery] = useState('')
  const filtered = quotes.filter(quote => `${quote.quote_number || ''} ${customers.find(customer => customer.id === quote.customer_id)?.company_name || ''} ${quote.product_code || ''} ${quote.status}`.toLowerCase().includes(query.toLowerCase()))
  const active = quotes.filter(quote => ['待内部确认', '已发送', '客户议价'].includes(quote.status)).length
  const drafts = quotes.filter(quote => quote.status === '草稿').length
  const accepted = quotes.filter(quote => quote.status === '已接受').length
  const orderFor = (quote: Quote) => orders.find(order => order.quote_id === quote.id)
  const customerName = (id: string) => customers.find(customer => customer.id === id)?.company_name || '客户待关联'
  const projectName = (id?: string | null) => projects.find(project => project.id === id)?.project_name
  const productName = (quote: Quote) => products.find(product => product.id === quote.product_id || product.product_code === quote.product_code)?.product_name || quote.product_name_snapshot || '产品待确认'
  return <section className="page quote-management"><div className="page-heading"><div><p className="eyebrow"><ClipboardList size={13}/> FORMAL QUOTATION CONTROL</p><h1>报价管理 2.0</h1><p>正式报价、版本、真实发送凭证与订单转换在同一条商业链路内管理；内部供应成本只保存在内部字段。</p></div><div className="quote-page-actions"><button className="secondary" onClick={() => { if (window.confirm('仅会从已关联客户的报价相关邮件建立“草稿”；不会提取或猜测金额、数量、条款，也不会标记为已发送。是否继续？')) void importMailDrafts().catch(error => alert(error instanceof Error ? error.message : '邮件草稿导入失败。')) }}><Mail size={16}/> 从邮件生成草稿</button><button className="primary" onClick={create}><Plus size={17}/> 新建正式报价</button></div></div><div className="quote-kpis"><span><b>{quotes.length}</b> 报价记录</span><span><b>{drafts}</b> 待核对草稿</span><span><b>{active}</b> 待客户推进</span><span><b>{accepted}</b> 已接受</span><span><b>{orders.length}</b> 已转订单</span></div><div className="quote-safety-note">“已发送 / 客户议价 / 已接受”必须关联真实邮件，或由你填写实际发送的人工确认说明；系统不会根据客户阶段、金额或邮件主题自动认定已发送。</div><section className="quote-list-panel"><div className="table-tools"><label><Search size={17}/><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索报价编号、客户、产品或状态" /></label><span>{filtered.length} 条</span></div><div className="formal-quote-grid">{filtered.map(quote => { const order = orderFor(quote); return <article className="formal-quote-card" key={quote.id}><header><div><small>{quote.quote_number || '历史报价'} · V{quote.version || 1}</small><b>{customerName(quote.customer_id)}</b><span>{projectName(quote.project_id) || '未关联项目'}</span></div><em className={`quote-status ${String(quote.status).replace(/\s/g, '-')}`}>{quote.status}</em></header><dl><div><dt>产品 / 规格</dt><dd>{quote.product_code || '待确认'} · {productName(quote)}{quote.specification ? ` · ${quote.specification}` : ''}</dd></div><div><dt>报价</dt><dd>{quote.amount != null ? `${quote.currency} ${quote.amount.toLocaleString()}` : quote.unit_price != null ? `${quote.currency} ${quote.unit_price} / ${quote.quantity_unit || '单位待确认'}` : '金额待确认'} · {quote.quantity || '数量待确认'}</dd></div><div><dt>贸易与交期</dt><dd>{[quote.incoterm || quote.trade_term, quote.loading_port, quote.destination_port, quote.lead_time].filter(Boolean).join(' · ') || '待确认'}</dd></div><div><dt>有效期 / 付款</dt><dd>{[quote.valid_until || '未设置有效期', quote.payment_terms].filter(Boolean).join(' · ')}</dd></div><div><dt>发送凭证</dt><dd>{quote.source_email_id ? '已关联真实邮件' : quote.manual_send_confirmed_at ? `人工确认：${quote.manual_send_note || '已记录'}` : '未记录，不能标记已发送'}</dd></div></dl>{quote.source_evidence_summary && <p className="quote-evidence">{quote.source_evidence_summary}</p>}{order && <p className="quote-order-link">已转订单：{order.order_number} · {order.status}</p>}<footer><button className="secondary" onClick={() => edit(quote)}>编辑</button><button className="secondary" onClick={() => void revise(quote).catch(error => alert(error instanceof Error ? error.message : '创建版本失败。'))}>新版本</button><button className="primary" disabled={quote.status !== '已接受' || Boolean(order)} onClick={() => void convert(quote).catch(error => alert(error instanceof Error ? error.message : '转订单失败。'))}>{order ? '已转订单' : '转为订单'}</button></footer></article>})}</div>{!filtered.length && <div className="empty">暂无报价记录。可以新建正式报价，或从已关联的报价相关邮件建立待核对草稿。</div>}</section></section>
}
function QuoteForm({ quote, customer, customers, projects, products, emails, close, submit }: { quote?: Quote; customer?: Customer; customers: Customer[]; projects: Project[]; products: Product[]; emails: MailEmail[]; close: () => void; submit: (payload: any) => Promise<void> }) {
  const [customerId, setCustomerId] = useState(quote?.customer_id || customer?.id || customers[0]?.id || '')
  const customerProjects = projects.filter(project => project.customer_id === customerId)
  const customerEmails = emails.filter(email => email.customer_id === customerId && !email.is_internal_sender)
  const csv = (items?: string[]) => (items || []).join(', ')
  const statuses = ['草稿','待内部确认','已发送','客户议价','已接受','已失效','已拒绝']
  if (quote?.status && !statuses.includes(quote.status)) statuses.unshift(quote.status)
  return <Modal title={quote ? `${quote.quote_number || '报价'} · V${quote.version || 1}` : `新建正式报价${customer ? ` · ${customer.company_name}` : ''}`} close={close}><form onSubmit={async event => { event.preventDefault(); const value = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; const list = (key: string) => (value[key] || '').split(/[,，\n]/).map(item => item.trim()).filter(Boolean); const payload = { customer_id: value.customer_id, project_id: value.project_id || null, product_id: value.product_id || null, product_code: value.product_code || null, product_name_snapshot: value.product_name_snapshot || null, specification: value.specification || null, packaging: value.packaging || null, quantity: value.quantity || '待确认', quantity_unit: value.quantity_unit || null, unit_price: value.unit_price ? Number(value.unit_price) : null, amount: value.amount ? Number(value.amount) : null, currency: value.currency || 'USD', trade_term: value.incoterm || null, incoterm: value.incoterm || null, loading_port: value.loading_port || null, destination_port: value.destination_port || null, lead_time: value.lead_time || null, moq: value.moq || null, valid_until: value.valid_until || null, payment_terms: value.payment_terms || null, status: value.status || '草稿', source_email_id: value.source_email_id || null, source_evidence_summary: value.source_evidence_summary || null, manual_send_confirmed: value.manual_send_confirmed === 'on', manual_send_note: value.manual_send_note || null, internal_supplier_quote_refs: list('internal_supplier_quote_refs'), internal_technical_document_refs: list('internal_technical_document_refs'), internal_notes: value.internal_notes || null }; try { await submit(payload) } catch (error) { alert(error instanceof Error ? error.message : '保存失败，请稍后重试。') } }}><div className="quote-form-note">报价商业条款由你确认；“邮件证据”仅关联已经同步的真实邮件。内部供应商报价、成本和技术资料不会出现在任何客户可见内容中。</div><div className="form-grid"><label>客户 *<select name="customer_id" value={customerId} onChange={event => setCustomerId(event.target.value)} disabled={Boolean(customer)}>{customers.map(item => <option key={item.id} value={item.id}>{item.company_name}</option>)}</select></label><label>关联项目<select name="project_id" defaultValue={quote?.project_id || ''}><option value="">未关联项目</option>{customerProjects.map(project => <option key={project.id} value={project.id}>{project.project_name}</option>)}</select></label><label>关联产品<select name="product_id" defaultValue={quote?.product_id || ''}><option value="">未关联产品</option>{products.map(product => <option key={product.id} value={product.id}>{product.product_code} · {product.product_name}</option>)}</select></label><Field label="产品编号" name="product_code" defaultValue={quote?.product_code || customer?.product_interest || ''}/><Field label="产品名称快照" name="product_name_snapshot" defaultValue={quote?.product_name_snapshot || ''}/><Field label="规格 / 牌号" name="specification" defaultValue={quote?.specification || ''}/><Field label="包装" name="packaging" defaultValue={quote?.packaging || ''}/><Field label="数量" name="quantity" defaultValue={quote?.quantity || ''} placeholder="例如 25"/><Field label="数量单位" name="quantity_unit" defaultValue={quote?.quantity_unit || ''} placeholder="kg / drum / ton"/><Field label="单价" name="unit_price" type="number" defaultValue={quote?.unit_price != null ? String(quote.unit_price) : ''}/><Field label="总金额" name="amount" type="number" defaultValue={quote?.amount != null ? String(quote.amount) : ''}/><Field label="币种" name="currency" defaultValue={quote?.currency || 'USD'}/><label>Incoterms<select name="incoterm" defaultValue={quote?.incoterm || quote?.trade_term || ''}><option value="">待确认</option>{['EXW','FCA','FOB','CFR','CIF','CPT','CIP','DAP','DDP'].map(term => <option key={term}>{term}</option>)}</select></label><Field label="起运港" name="loading_port" defaultValue={quote?.loading_port || ''}/><Field label="目的港 / 地" name="destination_port" defaultValue={quote?.destination_port || ''}/><Field label="交期" name="lead_time" defaultValue={quote?.lead_time || ''}/><Field label="MOQ" name="moq" defaultValue={quote?.moq || ''}/><Field label="报价有效期" name="valid_until" type="date" defaultValue={quote?.valid_until || ''}/><Field label="付款条款" name="payment_terms" defaultValue={quote?.payment_terms || ''} placeholder="例如 T/T 30% deposit"/><label>状态<select name="status" defaultValue={quote?.status || '草稿'}>{['草稿','待内部确认','已发送','客户议价','已接受','已失效','已拒绝'].map(status => <option key={status}>{status}</option>)}</select></label><label>真实邮件凭证<select name="source_email_id" defaultValue={quote?.source_email_id || ''}><option value="">不关联邮件</option>{customerEmails.map(email => <option key={email.id} value={email.id}>{email.received_at.slice(0, 10)} · {email.subject}</option>)}</select></label><label className="wide">凭证说明<textarea name="source_evidence_summary" defaultValue={quote?.source_evidence_summary || ''} placeholder="例如：邮件中确认的报价版本、发送时间或客户反馈；未明确则保留待确认。"/></label><label className="wide checkbox-field"><input type="checkbox" name="manual_send_confirmed"/> 我已实际发送该报价，并在下方填写确认说明（不能用于推测性标记）</label><label className="wide">人工发送确认说明<textarea name="manual_send_note" defaultValue={quote?.manual_send_note || ''} placeholder="填写实际发送渠道、日期与可核对线索；未实际发送请留空。"/></label><label className="wide">内部供应商报价参考（仅内部）<textarea name="internal_supplier_quote_refs" defaultValue={csv(quote?.internal_supplier_quote_refs)} placeholder="供应商名称、报价单编号或内部链接；不向客户展示。"/></label><label className="wide">内部技术资料参考（仅内部）<textarea name="internal_technical_document_refs" defaultValue={csv(quote?.internal_technical_document_refs)} placeholder="TDS/SDS/测试资料编号或内部链接；不向客户展示。"/></label><label className="wide">内部备注<textarea name="internal_notes" defaultValue={quote?.internal_notes || ''}/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">保存正式报价</button></div></form></Modal>
}
function TaskForm({ close, submit, customers, projects, products, initialDate }: { close: () => void; submit: (form: HTMLFormElement) => Promise<void>; customers: Customer[]; projects: Project[]; products: Product[]; initialDate: string }) { return <Modal title="新建任务" close={close}><form onSubmit={async event => { event.preventDefault(); try { await submit(event.currentTarget) } catch (error) { alert(error instanceof Error ? error.message : '保存失败，请稍后重试。') } }}><div className="form-grid"><Field label="任务名称 *" name="title" required/><label>日期 *<input name="task_date" type="date" defaultValue={initialDate} required/></label><label>优先级<select name="priority" defaultValue="normal"><option value="important">🔥 重要</option><option value="normal">⭐ 普通</option><option value="low">○ 低</option></select></label><label>分类<select name="category" defaultValue="外贸"><option>外贸</option><option>网站</option><option>设计</option><option>学习</option><option>生活</option><option>其他</option></select></label><Field label="开始时间" name="start_time" type="time"/><Field label="结束时间" name="end_time" type="time"/><Field label="预计分钟" name="estimated_minutes" type="number"/><label>关联客户<select name="customer_id" defaultValue=""><option value="">不关联客户</option>{customers.map(customer => <option key={customer.id} value={customer.id}>{customer.company_name} · {customer.country}</option>)}</select></label><label>关联项目<select name="project_id" defaultValue=""><option value="">不关联项目</option>{projects.map(project => <option key={project.id} value={project.id}>{project.project_name}</option>)}</select></label><label>关联产品<select name="product_id" defaultValue=""><option value="">不关联产品</option>{products.map(product => <option key={product.id} value={product.id}>{product.product_code} · {product.product_name}</option>)}</select></label><label className="wide">说明<textarea name="description" placeholder="补充任务背景、目标或注意事项"/></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">创建任务</button></div></form></Modal> }
function DailyReviewForm({ close, submit, value, date }: { close: () => void; submit: (form: HTMLFormElement) => Promise<void>; value: DailyLog | null; date: string }) { return <Modal title={`${dateLabel(date)} · 今日复盘`} close={close}><form onSubmit={async event => { event.preventDefault(); try { await submit(event.currentTarget) } catch (error) { alert(error instanceof Error ? error.message : '保存失败，请稍后重试。') } }}><div className="form-grid"><label className="wide">今日完成<textarea name="summary" defaultValue={value?.summary || ''} placeholder="今天完成了哪些关键动作？"/></label><label className="wide">今日遇到问题<textarea name="problem" defaultValue={value?.problem || ''} placeholder="哪些事情卡住了？下一次如何更好处理？"/></label><label className="wide">明日重点<textarea name="tomorrow_plan" defaultValue={value?.tomorrow_plan || ''} placeholder="明天最关键的 1-3 件事"/></label><label>工作评分<select name="rating" defaultValue={value?.rating ? String(value.rating) : ''}><option value="">暂不评分</option><option value="1">★</option><option value="2">★★</option><option value="3">★★★</option><option value="4">★★★★</option><option value="5">★★★★★</option></select></label></div><div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary">保存复盘</button></div></form></Modal> }
function PasswordForm({ close }: { close: () => void }) { const [error, setError] = useState(''); const [saving, setSaving] = useState(false); return <Modal title="修改登录密码" close={close}><form onSubmit={async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; if (values.password.length < 8) return setError('新密码至少需要 8 位。'); if (values.password !== values.confirm_password) return setError('两次输入的密码不一致。'); setSaving(true); setError(''); try { await api.updatePassword(values.password); alert('密码已更新，请使用新密码登录。'); close() } catch (reason) { setError(reason instanceof Error ? reason.message : '修改失败，请重新登录后再试。') } finally { setSaving(false) } }}><div className="password-hint">为保证安全，请设置至少 8 位的新密码。登录会话必须仍然有效。</div><div className="form-grid"><Field label="新密码 *" name="password" type="password" required/><Field label="确认新密码 *" name="confirm_password" type="password" required/></div>{error && <div className="login-error">{error}</div>}<div className="form-actions"><button type="button" onClick={close}>取消</button><button className="primary" disabled={saving}>{saving ? '正在更新…' : '更新密码'}</button></div></form></Modal> }
function Field({label,name,type='text',required=false,defaultValue,placeholder}:{label:string;name:string;type?:string;required?:boolean;defaultValue?:string;placeholder?:string}) { return <label>{label}<input name={name} type={type} required={required} defaultValue={defaultValue} placeholder={placeholder}/></label> }
function Modal({title,close,children}:{title:string;close:()=>void;children:ReactNode}) { return <div className="modal-layer"><section className="modal"><div className="modal-head"><h2>{title}</h2><button className="close" onClick={close}><X size={20}/></button></div>{children}</section></div> }

function Login({ onAuthenticated }: { onAuthenticated: () => void }) {
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [forgot, setForgot] = useState(false)
  const recovery = new URLSearchParams(window.location.hash.replace(/^#/, ''))
  const recoveryToken = recovery.get('type') === 'recovery' ? recovery.get('access_token') : null
  const login = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setLoading(true); setError('')
    const values = Object.fromEntries(new FormData(event.currentTarget))
    try {
      const response = await fetch(`${import.meta.env.VITE_API_URL || (import.meta.env.PROD ? 'https://zhiwu-os-api.gjsx.uno' : 'http://localhost:8000')}/api/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(values) })
      if (!response.ok) throw new Error('邮箱或密码不正确，请检查后重试。')
      const session = await response.json()
      sessionStorage.setItem('zhiwu-access-token', session.access_token)
      sessionStorage.setItem('zhiwu-account-email', String(values.email || '').trim().toLowerCase())
      onAuthenticated()
    } catch (reason) { setError(reason instanceof Error ? reason.message : '暂时无法登录，请稍后重试。') } finally { setLoading(false) }
  }
  if (recoveryToken) return <LoginFrame><RecoveryPassword token={recoveryToken}/></LoginFrame>
  if (forgot) return <LoginFrame><RecoveryRequest back={() => setForgot(false)}/></LoginFrame>
  return <LoginFrame><form className="login-form" onSubmit={login}><div className="mobile-brand brand"><div className="brand-mark"><img src={`${import.meta.env.BASE_URL}favicon.svg`} alt="干就是学工作站"/></div><strong>干就是学工作站</strong></div><p className="eyebrow">SECURE WORKSPACE</p><h2>密码登录</h2><p>使用已在 Supabase 创建的邮箱和密码进入专属工作空间。</p><label>登录邮箱<input type="email" name="email" placeholder="you@example.com" autoComplete="email" required /></label><label>密码<input type="password" name="password" placeholder="输入密码" autoComplete="current-password" required /></label>{error && <div className="login-error">{error}</div>}<button className="primary login-submit" disabled={loading}>{loading ? '正在验证…' : '安全登录'} <ArrowUpRight size={17}/></button><button type="button" className="demo-login" onClick={() => setForgot(true)}>忘记密码？</button><small>密码由 Supabase 安全验证，不会保存到 GitHub 或腾讯云服务器。</small></form></LoginFrame>
}
function LoginFrame({ children }: { children: ReactNode }) { return <main className="login-page"><section className="login-intro"><div className="brand"><div className="brand-mark"><img src={`${import.meta.env.BASE_URL}favicon.svg`} alt="干就是学工作站"/></div><div><strong>干就是学</strong><span>工作站</span></div></div><div><p className="eyebrow"><span className="pulse"/> PERSONAL CEO WORKSPACE</p><h1>为今天的关键决策，<br/>腾出一个清晰的空间。</h1><p>外贸、产品与项目，全部聚合在同一个专注的工作台。</p></div><div className="login-quote">“小而清晰的系统，胜过散落各处的待办。”</div></section><section className="login-form-wrap">{children}</section></main> }
function RecoveryRequest({ back }: { back: () => void }) { const [error, setError] = useState(''); const [sent, setSent] = useState(false); const [loading, setLoading] = useState(false); return <form className="login-form" onSubmit={async event => { event.preventDefault(); const email = String(new FormData(event.currentTarget).get('email') || ''); setLoading(true); setError(''); try { await api.requestPasswordRecovery(email); setSent(true) } catch (reason) { setError(reason instanceof Error ? reason.message : '暂时无法发送重置邮件。') } finally { setLoading(false) } }}><p className="eyebrow">PASSWORD RECOVERY</p><h2>重置密码</h2><p>输入登录邮箱，我们会发送一个一次性的密码重置链接。</p><label>登录邮箱<input type="email" name="email" defaultValue="gjsxning@163.com" autoComplete="email" required /></label>{error && <div className="login-error">{error}</div>}{sent && <div className="recovery-success">若该邮箱已注册，重置链接已发送。请检查收件箱和垃圾邮件。</div>}<button className="primary login-submit" disabled={loading}>{loading ? '正在发送…' : '发送重置链接'} <ArrowUpRight size={17}/></button><button type="button" className="demo-login" onClick={back}>返回登录</button></form> }
function RecoveryPassword({ token }: { token: string }) { const [error, setError] = useState(''); const [saving, setSaving] = useState(false); const [done, setDone] = useState(false); return <form className="login-form" onSubmit={async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>; if (values.password.length < 8) return setError('新密码至少需要 8 位。'); if (values.password !== values.confirm_password) return setError('两次输入的密码不一致。'); setSaving(true); setError(''); try { await api.updatePassword(values.password, token); window.history.replaceState(null, '', window.location.pathname); setDone(true) } catch (reason) { setError(reason instanceof Error ? reason.message : '重置链接已失效，请重新申请。') } finally { setSaving(false) } }}><p className="eyebrow">PASSWORD RECOVERY</p><h2>设置新密码</h2><p>为你的干就是学工作站设置一个新的登录密码。</p>{done ? <div className="recovery-success">密码已更新。请刷新页面后使用新密码登录。</div> : <><label>新密码<input type="password" name="password" autoComplete="new-password" required /></label><label>确认新密码<input type="password" name="confirm_password" autoComplete="new-password" required /></label>{error && <div className="login-error">{error}</div>}<button className="primary login-submit" disabled={saving}>{saving ? '正在更新…' : '更新密码'} <ArrowUpRight size={17}/></button></>}</form> }

createRoot(document.getElementById('root')!).render(<App />)

